script/05_DeployQueueAndWire.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Script} from "forge-std/Script.sol";
import {console2} from "forge-std/console2.sol";
import {stdJson} from "forge-std/StdJson.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

import {ExitFeeController} from "../src/ExitFeeController.sol";
import {ExitDelayQueue} from "../src/ExitDelayQueue.sol";
import {IExitDelayQueueHost} from "../src/interfaces/IExitDelayQueueHost.sol";

/// @title  Deploy ExitDelayQueue + wire the product hosts (activation step 1)
/// @notice activation ordering STEP 1: deploy the `ExitDelayQueue` impl +
///         ERC1967Proxy alongside the already-deployed `ExitFeeController` (from
///         `03_DeployController`), then WIRE the queue pointer into each product
///         host via `setExitDelayQueue`: the `sovrynProtocol`
///         singleton (lending + loan/margin) and the Zero `BorrowerOperations`
///         proxy.
///
///         IMPORTANT — this script performs ONLY the deploy + host-wire (step 1).
///         It DELIBERATELY does NOT configure the security-critical controller
///         state (`setAdmin`, `setGlobalDelaySeconds`) — those are activation steps 4–5
///         OWNER actions, executed as a SIP / Safe tx, NOT by this deployer script
///         (roles-not-actors: the deployer must not silently hold guardian/delay
///         authority). It also does NOT enable the perimeter (step 8).
///
///         The go-live GATES — (`controller.admin == queue.admin`)
///         and (`controller.globalDelaySeconds >= queue.minimumDelaySeconds`)
///         — are NOT asserted here. They CANNOT be: this script runs at step 1,
///         BEFORE the Owner has configured the controller's admin + global delay
///         (steps 4–5), so `controller.admin() == 0` and `globalDelaySeconds() == 0`
///         at this point. A correctly-ordered first deploy would therefore ALWAYS
///         revert if the assertions lived here (the ordering constraint below).
///         Instead they live in the dedicated READ-ONLY `06_VerifyActivation.s.sol`
///         verify script, run LAST as the step-7 go-live gate — AFTER the Owner
///         has configured admin + globalDelaySeconds.
///
///         The controller never reads or calls the queue at RUNTIME (kill-switch
///         queue-independence). The host wiring here is the ONLY
///         on-chain coupling and it is one-directional (host → queue pointer).
///
/// @dev Usage:
///
///   export EXIT_DELAY_QUEUE_OWNER=0x...        # queue Owner (multisig / timelock)
///   export EXIT_DELAY_QUEUE_ADMIN=0x...        # queue Admin (MAY equal Owner; must == controller.admin, set later)
///   export WRBTC_ADDRESS=0x...                 # canonical wrapped-RBTC ERC20
///   export QUEUE_MIN_DELAY_SECONDS=3600        # per-request delay floor
///   export QUEUE_ALLOWED_SOURCES=0xA,0xB       # comma-separated hooked sources (optional; activation step 2)
///   # Product hosts to wire (activation step 1). BOTH are REQUIRED non-zero UNLESS you
///   # set DEFER_HOSTS=true. A missing/misspelled host env var must ABORT the deploy
///   # (C2, no silent address(0) no-op wire) — deferral must be EXPLICIT, never
///   # implicit-via-blank. When DEFER_HOSTS=true, an unset/zero host is skipped so
///   # its wiring can be moved to a later per-host Owner SIP/Safe tx.
///   export SOVRYN_PROTOCOL_HOST=0x...          # sovrynProtocol singleton (lending + loan/margin)
///   export ZERO_BORROWER_OPERATIONS_HOST=0x... # Zero BorrowerOperations proxy
///   export DEFER_HOSTS=true                    # OPTIONAL explicit opt-in to defer a zero host
///
///   forge script script/05_DeployQueueAndWire.s.sol \
///       --rpc-url $RSK_RPC --broadcast --account deployer \
///       --sig "run(uint256)" <chainId>
///
///   Reads `deployments/<chainId>/ExitFeeController.json` for the controller proxy.
///   After this script:
///     1. tools/finalize-deployment.sh ExitDelayQueue 05_DeployQueueAndWire <chainId>
///     2. activation steps 2–6 (allowed sources, routes, setGlobalDelaySeconds,
///        setAdmin×2, bypass) — Owner SIP / Safe txs.
///     3. `06_VerifyActivation.s.sol` — the step-7 read-only go-live gate.
///     4. controller.setSecurityPerimeterEnabled(true) — step 8.
contract DeployQueueAndWire is Script {
    using stdJson for string;

    /// @dev Validated deploy configuration, parsed from env by `_readConfig`. Held
    ///      in a struct so `run()` keeps only ONE live local across the broadcast
    ///      (avoids a stack-too-deep on the non-viaIR Paris build).
    struct DeployConfig {
        address queueOwner;
        address queueAdmin;
        address wrbtc;
        uint32 minDelay;
        address[] allowedSources;
        address sovrynHost;
        address zeroHost;
    }

    /// @param chainId          the target chain (selects the deployments artifact dir)
    /// @return queueProxy       the deployed ExitDelayQueue proxy
    /// @return queueImpl        the deployed ExitDelayQueue implementation
    function run(uint256 chainId) external returns (address queueProxy, address queueImpl) {
        ExitFeeController controller = _controller(chainId);
        DeployConfig memory cfg = _readConfig();

        console2.log("ExitFeeController @", address(controller));
        console2.log("  controller.admin (pre-config, expect 0):", controller.admin());
        console2.log(
            "  controller.globalDelaySeconds (pre-config, expect 0):",
            uint256(controller.globalDelaySeconds())
        );
        console2.log("  queue owner:                  ", cfg.queueOwner);
        console2.log("  queue admin:                  ", cfg.queueAdmin);
        console2.log("  queue minimumDelaySeconds:    ", uint256(cfg.minDelay));
        console2.log("  sovrynProtocol host:          ", cfg.sovrynHost);
        console2.log("  Zero BorrowerOperations host: ", cfg.zeroHost);
        console2.log("");

        uint256 wiredCount;
        vm.startBroadcast();

        // ── Deploy the queue behind its proxy (initialize sets owner/admin/floor). ──
        queueImpl = address(new ExitDelayQueue());
        queueProxy = address(
            new ERC1967Proxy(
                queueImpl,
                abi.encodeCall(
                    ExitDelayQueue.initialize,
                    (cfg.queueOwner, cfg.queueAdmin, cfg.wrbtc, cfg.minDelay, cfg.allowedSources)
                )
            )
        );

        // ── WIRE the queue pointer into each supplied product host. ──
        //    setExitDelayQueue is host-Owner/Timelock-gated; the broadcast wallet
        //    must hold that authority for the wire to land (else the host reverts).
        //    A zero host is skipped (only reachable under DEFER_HOSTS=true — the
        //    require()s in _readConfig already aborted a blank host otherwise).
        wiredCount = wireHosts(queueProxy, cfg.sovrynHost, cfg.zeroHost);

        vm.stopBroadcast();

        console2.log("ExitDelayQueue impl deployed at:  ", queueImpl);
        console2.log("ExitDelayQueue proxy deployed at: ", queueProxy);
        console2.log("");
        // (C2) The "hosts wired" success line prints ONLY when a host was actually
        //      wired — a deferred-all deploy says so explicitly instead of claiming
        //      a wire that never happened.
        if (wiredCount > 0) {
            console2.log(
                unicode"OK: queue deployed + hosts wired (activation step 1). hosts wired:", wiredCount
            );
        } else {
            console2.log(
                unicode"OK: queue deployed, NO hosts wired (DEFER_HOSTS) — wire each host via a later Owner SIP (activation step 1)."
            );
        }
        console2.log(unicode"NOTE: admin + globalDelaySeconds are Owner steps 4-5 (NOT set here).");
        console2.log(unicode"Verify with 06_VerifyActivation.s.sol (step-7 gate) AFTER steps 4-5,");
        console2.log(unicode"then controller.setSecurityPerimeterEnabled(true) (step 8).");
        console2.log("Next: tools/finalize-deployment.sh ExitDelayQueue 05_DeployQueueAndWire <chainId>");
    }

    /// @dev Locate the already-deployed controller from its deployment artifact.
    function _controller(uint256 chainId) internal view returns (ExitFeeController) {
        string memory ctrlArtifact =
            vm.readFile(string.concat("deployments/", vm.toString(chainId), "/ExitFeeController.json"));
        return ExitFeeController(ctrlArtifact.readAddress(".proxyAddress"));
    }

    /// @dev Parse + VALIDATE the deploy config from env (C1/C2: no silent
    ///      address(0) defaults). A missing/misspelled critical env var ABORTS the
    ///      deploy here rather than defaulting to address(0) on-chain. In particular
    ///      EXIT_DELAY_QUEUE_OWNER is required (C1): ExitDelayQueue.initialize
    ///      resolves a zero `owner_` to msg.sender, which would silently leave the
    ///      deployer EOA holding UUPS/upgrade/source-registry/recovery/sweep
    ///      authority. Product hosts are REQUIRED non-zero unless DEFER_HOSTS=true
    ///      (C2: a blank host must ABORT, never no-op-wire a fail-open surface;
    ///      deferral must be EXPLICIT).
    function _readConfig() internal view returns (DeployConfig memory cfg) {
        cfg.queueOwner = vm.envAddress("EXIT_DELAY_QUEUE_OWNER");
        cfg.queueAdmin = vm.envAddress("EXIT_DELAY_QUEUE_ADMIN");
        cfg.wrbtc = vm.envAddress("WRBTC_ADDRESS");
        uint256 minDelay = vm.envUint("QUEUE_MIN_DELAY_SECONDS");
        require(minDelay <= type(uint32).max, "05: QUEUE_MIN_DELAY_SECONDS overflows uint32");
        cfg.minDelay = uint32(minDelay);

        cfg.allowedSources = vm.envOr("QUEUE_ALLOWED_SOURCES", ",", new address[](0));

        cfg.sovrynHost = vm.envOr("SOVRYN_PROTOCOL_HOST", address(0));
        cfg.zeroHost = vm.envOr("ZERO_BORROWER_OPERATIONS_HOST", address(0));

        // The address/host safety checks are factored into a PURE validator so a
        // unit test can drive every abort branch on an in-memory struct — NO
        // vm.setEnv (which mutates process-global env forge does not isolate
        // between parallel test functions, a genuine race across env-driven tests).
        validateConfig(cfg, vm.envOr("DEFER_HOSTS", false));
    }

    /// @notice Validate the deploy config (C1/C2 no-silent-blanks safety). Reverts
    ///         with a DISTINCT message per missing/misspelled critical input;
    ///         returns silently when the config is deployable. Pure so it is
    ///         driveable in a unit test with an in-memory struct, race-free.
    /// @param cfg          the parsed config
    /// @param deferHosts   the explicit DEFER_HOSTS opt-in (true ⇒ a zero host is
    ///                     an intentional deferral, not an error)
    function validateConfig(DeployConfig memory cfg, bool deferHosts) public pure {
        // C1 — no silent address(0) for the security-critical queue inputs. A zero
        // owner would let ExitDelayQueue.initialize resolve owner_ to msg.sender,
        // silently leaving the deployer EOA with queue authority — so abort loud.
        require(
            cfg.queueOwner != address(0),
            "05: EXIT_DELAY_QUEUE_OWNER must be set (C1: zero owner => deployer EOA holds queue authority)"
        );
        require(cfg.queueAdmin != address(0), "05: EXIT_DELAY_QUEUE_ADMIN must be set");
        // No admin-vs-owner separation is enforced: the launch shape has the
        // same multisig holding both roles, and the authority split becomes
        // meaningful only once ownership later moves while the admin stays put.
        require(cfg.wrbtc != address(0), "05: WRBTC_ADDRESS must be set");

        // C2 — a blank host must ABORT (never no-op-wire a fail-open zero-delay
        // surface) UNLESS deferral is EXPLICIT via DEFER_HOSTS=true.
        if (!deferHosts) {
            require(
                cfg.sovrynHost != address(0),
                "05: SOVRYN_PROTOCOL_HOST must be set (or set DEFER_HOSTS=true to defer)"
            );
            require(
                cfg.zeroHost != address(0),
                "05: ZERO_BORROWER_OPERATIONS_HOST must be set (or set DEFER_HOSTS=true to defer)"
            );
        }

        // (C2 duplicate-host guard) A non-zero duplicate pair (both spec-named host
        // vars pointing at the SAME address — a copy-paste footgun) would wire one
        // surface twice and leave the OTHER silently unwired at zero-delay. Reject
        // it. The `== address(0)` clause preserves the both-zero DEFER_HOSTS path.
        require(
            cfg.sovrynHost != cfg.zeroHost || cfg.sovrynHost == address(0),
            "05: SOVRYN_PROTOCOL_HOST == ZERO_BORROWER_OPERATIONS_HOST (duplicate host)"
        );
    }

    /// @notice Wire the queue pointer into the two product hosts,
    ///         skipping any zero host (wiring deferred to a per-host SIP/Safe tx).
    ///         Public so a unit test can drive the wire step directly WITHOUT the
    ///         env-parsing broadcast path (whose `vm.setEnv` mutates process-global
    ///         env that forge does not isolate between parallel test functions).
    ///         Must be called from a context authorized to set each host pointer.
    /// @return wiredCount how many hosts were actually wired (a zero host is not
    ///         counted) — drives the conditional "hosts wired" success line (C2).
    function wireHosts(address queue, address sovrynHost, address zeroHost)
        public
        returns (uint256 wiredCount)
    {
        if (_wireHost(sovrynHost, queue, "sovrynProtocol")) wiredCount++;
        if (_wireHost(zeroHost, queue, "Zero BorrowerOperations")) wiredCount++;
    }

    /// @dev Wire one product host's queue pointer, verifying the write took.
    ///      A zero host is a no-op (wiring deferred to a later per-host SIP/Safe tx).
    /// @return wired true iff the host was non-zero and its pointer was written.
    function _wireHost(address host, address queue, string memory label) internal returns (bool wired) {
        if (host == address(0)) {
            console2.log(string.concat("  wire SKIPPED (host unset): "), label);
            return false;
        }
        IExitDelayQueueHost(host).setExitDelayQueue(queue);
        require(
            IExitDelayQueueHost(host).exitDelayQueue() == queue, "05: setExitDelayQueue did not take on host"
        );
        console2.log(string.concat("  wired queue -> host: "), label);
        return true;
    }
}

script/06_VerifyActivation.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Script} from "forge-std/Script.sol";
import {console2} from "forge-std/console2.sol";
import {stdJson} from "forge-std/StdJson.sol";

import {ExitFeeController} from "../src/ExitFeeController.sol";
import {ExitDelayQueue} from "../src/ExitDelayQueue.sol";
import {IExitDelayQueueHost} from "../src/interfaces/IExitDelayQueueHost.sol";
import {IExitFeeControllerHost} from "../src/interfaces/IExitFeeControllerHost.sol";

/// @title  Verify Activation — activation step-7 go-live gate (C1/C2)
/// @notice READ-ONLY. Run LAST, AFTER the Owner has configured the controller's
///         `admin` + `globalDelaySeconds` (activation steps 4–5), the guardian on both
///         contracts (step 5), the allowed-sources + host wiring (steps 1–2), and
///         BEFORE `setSecurityPerimeterEnabled(true)` (step 8): a fat-fingered
///         security-contract deploy must fail LOUD here rather than silently ship
///         fail-open (unwired host = zero-delay direct-pay) or fail-closed
///         (mis-owned / wired-but-not-allowed = bricked).
///
///         SCOPE: the two STORAGE HOSTS that hold the queue pointer are not the
///         addresses the queue sees as `msg.sender`. On the lender surface the
///         record caller is the iToken PROXY — `LoanTokenLogicShared` calls
///         `recordERC20Exit` from the iToken's own context — so `onlyAllowedSource`
///         is evaluated against each pool, one by one. A gate that checked only the
///         two pointer-holders would certify a deploy in which iXUSD is on the
///         allow-list and iDOC was missed: every iDOC withdrawal then reverts
///         `UnregisteredSource` from the moment the delay is armed.
///
///         So the checked list is the UNION of the two spec-named hosts and every
///         hooked record caller named in `QUEUE_ALLOWED_SOURCES` — the SAME
///         variable `05_DeployQueueAndWire` registers from, so the two cannot drift
///         — of arbitrary length, deduplicated, and each entry held to BOTH
///         predicates. The iToken proxies answer `exitDelayQueue()` through the
///         protocol pointer, so the per-host assertion works on them unchanged.
///
///         RESIDUAL, stated rather than inherited: this gate checks the declared
///         intent. A pool left out of `QUEUE_ALLOWED_SOURCES` *and* off the chain's
///         allow-list is invisible to it. That list is the operator's statement of
///         what the release hooks, and it is what the step-2 source SIP registers.
///
///         Asserts, each with a DISTINCT revert message:
///            controller.admin() == queue.admin(), both non-zero  -- guardian
///              controller.globalDelaySeconds() > 0 AND
///                       >= queue.minimumDelaySeconds()                   -- delay floor
///                   (C2: the `> 0` gates the ACTIVE global delay — a
///                    zero global delay leaves the perimeter inert. The queue's
///                    `minimumDelaySeconds` FLOOR itself MAY be 0; that only leaves
///                    the per-request DelayBelowFloor backstop inactive — Owner-
///                    remediable, NOT a go-live blocker.)
///           (C1)    queue.owner()      == intendedOwner != deployer
///                   controller.owner() == intendedOwner != deployer   -- ownership
///           (C2)    for each intended host:
///                     host.exitDelayQueue() == queue                    -- queue wired
///                     host.exitFeeController() == controller            -- controller wired
///                     queue.isAllowedSource(host)                       -- allowed-source
///
///         C1 host-input safety: both spec-named product hosts are
///         REQUIRED inputs read via `vm.envAddress` (which REVERTS on an unset or
///         typo'd var) — a fresh-shell / mistyped run must NOT silently yield an
///         empty intended-host list and vacuously "PASS" while a surface ships
///         unwired at zero-delay (fail-open). Skipping a host is allowed ONLY via an
///         EXPLICIT, LOUD `VERIFY_DEFER_HOSTS=true` opt-in; each deferred host prints
///         a warning line and the success banner is downgraded to the qualified
///         (warned) variant. The unqualified "safe to run step 8" banner is emitted
///         ONLY when BOTH spec-named hosts were actually checked.
///
///         The assertions live HERE — NOT inside `05_DeployQueueAndWire`'s broadcast
///         (step 1, BEFORE config) — so the documented activation order does not
///         self-abort.
///
///         Read-only: no `vm.startBroadcast()`, no state change. verify() does NOT
///         mutate (roles-not-actors: setAdmin/setGlobalDelaySeconds stay Owner
///         actions run at steps 4–5, not here).
///
/// @dev Usage:
///
///   export EXIT_DELAY_OWNER=0x...                    # intended Owner (multisig/timelock)
///   export EXIT_DELAY_DEPLOYER=0x...                # the broadcast EOA that ran the deploy
///   export SOVRYN_PROTOCOL_HOST=0x...               # intended host (REQUIRED unless VERIFY_DEFER_HOSTS=true)
///   export ZERO_BORROWER_OPERATIONS_HOST=0x...      # intended host (REQUIRED unless VERIFY_DEFER_HOSTS=true)
///   export QUEUE_ALLOWED_SOURCES=0xA,0xB,0xC        # every hooked record caller — the iToken proxies and the
///                                                   # Zero BorrowerOperations proxy (REQUIRED unless
///                                                   # VERIFY_DEFER_HOSTS=true). ActivePool, the native pusher,
///                                                   # is recorded separately by setNativePusher as provenance
///                                                   # and must NOT be listed here — it has no allowed-source
///                                                   # gate to pass and calls no record function itself.
///   # export VERIFY_DEFER_HOSTS=true                # ONLY to intentionally defer a host's wiring to a later SIP
///
///   forge script script/06_VerifyActivation.s.sol \
///       --rpc-url $RSK_RPC --sig "run(uint256)" <chainId>
///
///   Reads BOTH `deployments/<chainId>/ExitFeeController.json` and
///   `deployments/<chainId>/ExitDelayQueue.json` for the two proxy addresses, and
///   the intended-host list from the same env vars the deploy script wires from.
contract VerifyActivation is Script {
    using stdJson for string;

    /// @param chainId  the target chain (selects the deployments artifact dir)
    function run(uint256 chainId) external view {
        (ExitFeeController controller, ExitDelayQueue queue) = _loadProxies(chainId);

        // ── Intended Owner + deployer EOA (C1). Both REQUIRED non-zero
        //    so a blank never trivially satisfies "owner == intendedOwner" or the
        //    "owner != deployer" check. ──
        address intendedOwner = vm.envAddress("EXIT_DELAY_OWNER");
        address deployer = vm.envAddress("EXIT_DELAY_DEPLOYER");

        // ── Intended product hosts (C1 host-input safety). BOTH spec-
        //    named hosts are REQUIRED via vm.envAddress (reverts on unset/typo) so a
        //    fresh-shell run can NEVER produce an empty list that vacuously PASSes
        //    while a surface ships unwired (fail-open zero-delay). A host may be
        //    skipped ONLY via an EXPLICIT `VERIFY_DEFER_HOSTS=true`. ──
        bool deferHosts = vm.envOr("VERIFY_DEFER_HOSTS", false);
        (address sovrynHost, address zeroHost) = _readHostEnv(deferHosts);
        address[] memory storageHosts = _resolveHosts(deferHosts, sovrynHost, zeroHost);
        address[] memory recordingHosts =
            _resolveRecordingHosts(deferHosts, _readRecordingHostsEnv(deferHosts));
        address[] memory hosts = _mergeHosts(storageHosts, recordingHosts);

        console2.log("ExitFeeController @", address(controller));
        console2.log("ExitDelayQueue    @", address(queue));
        console2.log("intended Owner    @", intendedOwner);
        console2.log("deployer EOA      @", deployer);
        console2.log("intended hosts    :", hosts.length);
        console2.log("  of which record :", recordingHosts.length);
        console2.log("");

        verify(controller, queue, intendedOwner, deployer, hosts, deferHosts);

        // (C2) The banner is keyed off the RESOLVED FACT — whether BOTH
        // spec-named hosts were actually C2-checked — NOT the raw VERIFY_DEFER_HOSTS
        // flag: with defer=true but both hosts present, all surfaces ARE certified
        // and the unqualified banner is correct; the qualified/warned banner is for
        // an ACTUAL deferral (a spec-named host dropped from the checked list).
        bool anyHostDeferred =
            storageHosts.length < _EXPECTED_HOST_COUNT || recordingHosts.length == 0;
        _reportPass(anyHostDeferred);
    }

    /// @dev The number of spec-named product hosts (activation step-7 scope: the
    ///      `sovrynProtocol` singleton + the Zero `BorrowerOperations` proxy). A
    ///      resolved list shorter than this means at least one host was deferred.
    uint256 private constant _EXPECTED_HOST_COUNT = 2;

    /// @dev Read the two spec-named host env vars. When NOT deferring, use
    ///      `vm.envAddress` (REQUIRED — reverts LOUD on an unset or typo'd var,
    ///      exactly like 05_DeployQueueAndWire's non-zero rule) so a fresh-shell or
    ///      mistyped run cannot silently yield an empty intended-host list and
    ///      vacuously "PASS". When deferring, fall back to `vm.envOr(..., 0)` so an
    ///      operator can leave a host unset ON PURPOSE.
    function _readHostEnv(bool deferHosts) internal view returns (address sovrynHost, address zeroHost) {
        if (deferHosts) {
            sovrynHost = vm.envOr("SOVRYN_PROTOCOL_HOST", address(0));
            zeroHost = vm.envOr("ZERO_BORROWER_OPERATIONS_HOST", address(0));
        } else {
            // REQUIRED: reverts on unset/typo — no silent empty list.
            sovrynHost = vm.envAddress("SOVRYN_PROTOCOL_HOST");
            zeroHost = vm.envAddress("ZERO_BORROWER_OPERATIONS_HOST");
        }
    }

    /// @dev Read the hooked record callers from `QUEUE_ALLOWED_SOURCES` — the SAME
    ///      comma-separated variable `05_DeployQueueAndWire` registers the queue's
    ///      allowed-source set from, so the deploy and this gate cannot describe
    ///      different systems. REQUIRED when not deferring (`vm.envAddress` reverts
    ///      on unset or typo'd), so a fresh shell cannot yield a silently empty list.
    function _readRecordingHostsEnv(bool deferHosts) internal view returns (address[] memory) {
        if (deferHosts) {
            return vm.envOr("QUEUE_ALLOWED_SOURCES", ",", new address[](0));
        }
        return vm.envAddress("QUEUE_ALLOWED_SOURCES", ",");
    }

    /// @notice Validate the hooked record-caller list. Public-of-env (the harness
    ///         drives it on in-memory addresses) for the same reason `_resolveHosts`
    ///         is: `vm.setEnv` mutates process-global state forge does not isolate
    ///         between concurrently-scheduled test functions.
    ///
    ///         Contract:
    ///           - a zero entry is ALWAYS a hard REVERT, deferral or not: a blank in
    ///             a comma-separated list is a typo, never an intention.
    ///           - an EMPTY list is a hard REVERT unless deferral is EXPLICIT. An
    ///             empty list would leave every pool unchecked while the gate
    ///             certifies go-live — the vacuous-PASS the spec-named hosts are
    ///             already protected against.
    /// @param deferHosts  the explicit VERIFY_DEFER_HOSTS opt-in
    /// @param raw         the list as read from the environment
    /// @return hosts      the same list, validated
    function _resolveRecordingHosts(bool deferHosts, address[] memory raw)
        internal
        view
        returns (address[] memory hosts)
    {
        for (uint256 i; i < raw.length; i++) {
            require(
                raw[i] != address(0),
                "C1: QUEUE_ALLOWED_SOURCES carries a zero entry -- a blank in the list is a typo"
            );
        }
        if (raw.length == 0) {
            require(
                deferHosts,
                "C1: QUEUE_ALLOWED_SOURCES is empty -- list every hooked record caller (iToken proxies; the Zero BorrowerOperations proxy), or set VERIFY_DEFER_HOSTS=true to defer explicitly"
            );
            console2.log(
                unicode"⚠ no record callers checked -- every hooked pool ships UNVERIFIED:"
            );
            console2.log(unicode"    QUEUE_ALLOWED_SOURCES (iToken proxies; the Zero BorrowerOperations proxy)");
        }
        return raw;
    }

    /// @dev Union the pointer-holders and the record callers, keeping first-seen
    ///      order and dropping repeats. The protocol singleton is BOTH — it holds
    ///      the pointer and records the borrower surface itself — so without this
    ///      it would be asserted twice and reported as two hosts.
    function _mergeHosts(address[] memory storageHosts, address[] memory recordingHosts)
        internal
        pure
        returns (address[] memory hosts)
    {
        address[] memory buf = new address[](storageHosts.length + recordingHosts.length);
        uint256 n;
        for (uint256 i; i < storageHosts.length; i++) {
            n = _pushUnique(buf, n, storageHosts[i]);
        }
        for (uint256 i; i < recordingHosts.length; i++) {
            n = _pushUnique(buf, n, recordingHosts[i]);
        }
        hosts = new address[](n);
        for (uint256 i; i < n; i++) {
            hosts[i] = buf[i];
        }
    }

    function _pushUnique(address[] memory buf, uint256 n, address a) private pure returns (uint256) {
        for (uint256 i; i < n; i++) {
            if (buf[i] == a) return n;
        }
        buf[n] = a;
        return n + 1;
    }

    /// @dev Read the controller + queue proxy addresses from the deployment
    ///      artifacts. Split out of `run` to keep its live-local count low
    ///      (avoids a stack-too-deep on the non-viaIR Paris build).
    function _loadProxies(uint256 chainId)
        internal
        view
        returns (ExitFeeController controller, ExitDelayQueue queue)
    {
        string memory dir = string.concat("deployments/", vm.toString(chainId), "/");
        controller = ExitFeeController(
            vm.readFile(string.concat(dir, "ExitFeeController.json")).readAddress(".proxyAddress")
        );
        queue = ExitDelayQueue(
            payable(vm.readFile(string.concat(dir, "ExitDelayQueue.json")).readAddress(".proxyAddress"))
        );
    }

    /// @notice Build the intended-host list from the two spec-named hosts, enforcing
    ///         the C1 host-input safety rule and emitting a LOUD per-host warning for
    ///         each explicitly-deferred (zero) host. Public + pure-of-env so a unit
    ///         test drives every branch on in-memory addresses WITHOUT `vm.setEnv`
    ///         (which mutates process-global env forge does not isolate between
    ///         parallel test functions — a genuine race).
    ///
    ///         Contract:
    ///           - deferHosts == false: BOTH hosts MUST be non-zero (the caller's
    ///             `vm.envAddress` already reverts on unset; this is the belt-and-
    ///             suspenders check for a caller-supplied zero). A zero host here is
    ///             a hard REVERT — a surface would ship unwired at zero-delay.
    ///           - deferHosts == true: a zero host is an INTENTIONAL deferral; it is
    ///             dropped from the list and a LOUD warning is printed naming the
    ///             surface whose delay is NOT yet active.
    ///
    /// @param deferHosts   the explicit VERIFY_DEFER_HOSTS opt-in
    /// @param sovrynHost   SOVRYN_PROTOCOL_HOST (lending + loan/margin surfaces)
    /// @param zeroHost     ZERO_BORROWER_OPERATIONS_HOST (Zero surface)
    /// @return hosts       the tightly-sized list of hosts that WILL be C2-checked
    function _resolveHosts(bool deferHosts, address sovrynHost, address zeroHost)
        internal
        view
        returns (address[] memory hosts)
    {
        // (C2 duplicate-host guard) A non-zero duplicate pair (both spec-named vars
        // pointing at the SAME host — a copy-paste footgun) would C2-check one
        // surface twice and leave the OTHER silently unchecked/unwired. Reject it.
        // The `== address(0)` clause preserves the both-zero EXPLICIT-defer path
        // (deferHosts==true, both hosts intentionally unset): that is not a dup.
        require(
            sovrynHost != zeroHost || sovrynHost == address(0),
            "C1: SOVRYN_PROTOCOL_HOST == ZERO_BORROWER_OPERATIONS_HOST (duplicate host)"
        );

        bool sovrynIn = _includeHost(deferHosts, sovrynHost, "sovrynProtocol (SOVRYN_PROTOCOL_HOST)");
        bool zeroIn =
            _includeHost(deferHosts, zeroHost, "Zero BorrowerOperations (ZERO_BORROWER_OPERATIONS_HOST)");

        uint256 n;
        if (sovrynIn) n++;
        if (zeroIn) n++;

        hosts = new address[](n);
        uint256 i;
        if (sovrynIn) hosts[i++] = sovrynHost;
        if (zeroIn) hosts[i++] = zeroHost;
    }

    /// @dev Decide whether one spec-named host is included in the C2-checked list.
    ///      A non-zero host is always included. A zero host is a hard REVERT unless
    ///      deferral is EXPLICIT (VERIFY_DEFER_HOSTS=true), in which case it is
    ///      dropped with a LOUD warning naming the un-delayed surface.
    function _includeHost(bool deferHosts, address host, string memory label)
        internal
        view
        returns (bool included)
    {
        if (host != address(0)) return true;
        // host == 0
        require(
            deferHosts,
            string.concat(
                "C1: intended host ",
                label,
                " == 0 -- set it, or set VERIFY_DEFER_HOSTS=true to defer explicitly"
            )
        );
        console2.log(unicode"⚠ perimeter enabling with host UNWIRED -- that surface has NO delay:");
        console2.log(string.concat(unicode"    ", label));
        return false;
    }

    /// @dev Emit the go-live success banner. The UNQUALIFIED "safe to run step 8"
    ///      banner is emitted ONLY when BOTH spec-named hosts were actually checked
    ///      (`anyHostDeferred == false`). When at least one spec-named host was
    ///      ACTUALLY dropped from the checked list (a real deferral) the banner is
    ///      DOWNGRADED to the qualified/warned variant so a deferred surface is never
    ///      implicitly certified. (C2: keyed off the resolved fact, NOT the raw
    ///      VERIFY_DEFER_HOSTS flag — defer=true with both hosts present certifies
    ///      everything and earns the unqualified banner.)
    /// @param anyHostDeferred  true iff fewer than the two spec-named hosts were
    ///                         actually C2-checked (a real deferral happened)
    function _reportPass(bool anyHostDeferred) internal view {
        if (anyHostDeferred) {
            console2.log(unicode"OK (QUALIFIED): activation step-7 gate PASSED for the CHECKED hosts.");
            console2.log(unicode"  guardian + delay floor + ownership + wiring for wired hosts.");
            console2.log(
                unicode"⚠ VERIFY_DEFER_HOSTS=true -- one or more surfaces are UNWIRED (see warnings above)."
            );
            console2.log(
                unicode"  Do NOT treat this as a full go-live: each deferred host has NO delay until wired + re-verified."
            );
        } else {
            console2.log(
                unicode"OK: activation step-7 gate PASSED for: guardian + delay floor + ownership + host wiring."
            );
            console2.log(
                unicode"NOTE (scope): the checked list is the two STORAGE HOSTS plus every record caller named in"
            );
            console2.log(
                unicode"  QUEUE_ALLOWED_SOURCES (the iToken proxies; the Zero BorrowerOperations proxy). Each was proved wired AND"
            );
            console2.log(
                unicode"  allowed-source. A hooked caller left out of that variable AND off the chain's allow-list is"
            );
            console2.log(
                unicode"  invisible here — the variable is the operator's statement of what this release hooks."
            );
            console2.log(unicode"Safe to run step 8 (setSecurityPerimeterEnabled(true)).");
        }
    }

    /// @notice The step-7 COMPREHENSIVE go-live gate as a public read-only entry, so
    ///         a unit test — and an operator running a dry-run against live proxies —
    ///         can drive the EXACT assertions the `run` path runs. Reverts on any
    ///         unmet invariant with a DISTINCT message; returns silently when the
    ///         whole deploy is correctly configured. Read-only (`view`), never
    ///         mutates (setAdmin/setGlobalDelaySeconds are Owner steps 4–5, not this).
    ///
    ///         Revert taxonomy (distinct messages; "not yet configured" variants
    ///         first within each check so an early run points the operator back at
    ///         the missing step rather than at a false mis-config):
    ///           - admin unset            -> "...(unconfigured): controller.admin==0..."
    ///           - admin mismatch         -> "...: controller.admin() != queue.admin()..."
    ///           - globalDelaySeconds==0  -> "...(unconfigured): controller.globalDelaySeconds==0..."
    ///           - sub-floor delay        -> "...: controller.globalDelaySeconds() < ...floor..."
    ///           - owner still deployer   -> "...(C1): queue/controller.owner() == deployer..."
    ///           - owner != intended      -> "...(C1): queue/controller.owner() != the intended Owner..."
    ///           - host queue not wired      -> "...(C2): host <addr> not wired -- host.exitDelayQueue()..."
    ///           - host controller not wired -> "...(C2): host <addr> not wired -- host.exitFeeController()..."
    ///           - host not allowed-src      -> "...(C2): host <addr> not allowed-source..."
    ///
    /// @param controller       the deployed ExitFeeController proxy
    /// @param queue            the deployed ExitDelayQueue proxy
    /// @param intendedOwner    the intended Owner (must own BOTH; != deployer)
    /// @param deployer         the broadcast EOA that ran the deploy (must own NEITHER)
    /// @param hosts            the intended product hosts (each must be wired + allowed-source)
    /// @param deferHosts       the explicit VERIFY_DEFER_HOSTS opt-in. An EMPTY host
    ///                         list is a vacuous wiring PASS (fail-open: a surface
    ///                         could ship unwired at zero-delay while this gate
    ///                         certifies "safe to run step 8"). The dry-run entry
    ///                         REFUSES an empty list unless the caller EXPLICITLY
    ///                         asserts deferral via `deferHosts == true` (C1,
    ///                         "refuse vacuous PASS"). The
    ///                         legitimate defer-both `run()` path still passes.
    function verify(
        ExitFeeController controller,
        ExitDelayQueue queue,
        address intendedOwner,
        address deployer,
        address[] memory hosts,
        bool deferHosts
    ) public view {
        // (C1) Refuse a vacuous wiring PASS: an empty intended-host list means the
        // C2 wiring loop asserts NOTHING, so the gate would certify go-live while a
        // surface ships unwired (fail-open zero-delay). Only an EXPLICIT deferral
        // opt-in may legitimately produce an empty list.
        require(
            hosts.length != 0 || deferHosts,
            "empty intended-host list without VERIFY_DEFER_HOSTS=true -- refusing vacuous wiring PASS"
        );
        _verifyGuardian(controller, queue);
        _verifyFloor(controller, queue);
        _verifyNotPaused(queue);
        _verifyOwnership(controller, queue, intendedOwner, deployer);
        _verifyWiring(controller, queue, hosts);
    }

    // ── The queue must not be left paused. A paused queue keeps escrowing
    //    ingress but blocks every executeExit/recoverStuckExit, so enabling the
    //    perimeter against it freezes every withdrawal system-wide. A pause set
    //    during setup drills must be cleared before go-live. ──
    function _verifyNotPaused(ExitDelayQueue queue) internal view {
        require(
            !queue.securityPerimeterPaused(),
            "queue is paused -- unpause before enabling the perimeter (step 8)"
        );
    }

    // ── single guardian. "not yet configured" (admin==0) is distinct from a
    //    genuine guardian mismatch. ──
    function _verifyGuardian(ExitFeeController controller, ExitDelayQueue queue) internal view {
        address ctrlAdmin = controller.admin();
        address queueAdmin = queue.admin();
        require(
            ctrlAdmin != address(0),
            "guardian unconfigured: controller.admin()==0 -- run step 5 (setAdmin) first"
        );
        require(
            ctrlAdmin == queueAdmin,
            "single guardian violated: controller.admin() != queue.admin() -- single guardian violated"
        );
    }

    // ── delay-floor liveness. globalDelaySeconds==0 (step 4 not run) is
    //    distinct from a configured-but-sub-floor delay. The queue's own per-request
    //    `require(d >= minimumDelaySeconds)` is the SAFETY enforcement; this is the
    //    LIVENESS check that a legit global delay does not sit below the floor and
    //    self-brick every non-bypassed exit.
    //
    //    C2: the `> 0` guard is on the ACTIVE globalDelaySeconds — a
    //    zero global delay = inert perimeter, rejected here at go-live. The queue's
    //    `minimumDelaySeconds` FLOOR itself MAY be 0 (the per-request DelayBelowFloor
    //    backstop is then inactive, Owner-remediable, NOT a go-live blocker) — so
    //    there is deliberately NO `minimumDelaySeconds != 0` assertion. ──
    function _verifyFloor(ExitFeeController controller, ExitDelayQueue queue) internal view {
        uint256 globalDelay = uint256(controller.globalDelaySeconds());
        uint256 floor = uint256(queue.minimumDelaySeconds());
        require(
            globalDelay != 0,
            "delay unconfigured: controller.globalDelaySeconds()==0 -- run step 4 (setGlobalDelaySeconds) first"
        );
        require(
            globalDelay >= floor,
            "sub-floor delay: controller.globalDelaySeconds() < queue.minimumDelaySeconds() -- sub-floor delay self-bricks exits"
        );
    }

    // ── C1: ownership. BOTH the queue and the controller must be owned by the
    //    intended Owner and NOT by the deployer EOA — a blank/zero owner
    //    that silently left the deployer in control (ExitDelayQueue.initialize
    //    resolves a zero owner_ to msg.sender) MUST NOT pass go-live. The
    //    "owner == deployer" check is reported BEFORE the "== intendedOwner"
    //    check so the still-deployer case gets the most actionable message. ──
    function _verifyOwnership(
        ExitFeeController controller,
        ExitDelayQueue queue,
        address intendedOwner,
        address deployer
    ) internal view {
        require(
            intendedOwner != address(0),
            "C1: the intended Owner arg == 0 -- set EXIT_DELAY_OWNER"
        );
        require(
            deployer != address(0),
            "C1: deployer arg == 0 -- set EXIT_DELAY_DEPLOYER"
        );
        require(
            intendedOwner != deployer,
            "C1: the intended Owner == deployer -- they must differ"
        );

        address queueOwner = queue.owner();
        address ctrlOwner = controller.owner();

        // still-deployer first (the silent-blank-owner footgun this gate exists for)
        require(
            queueOwner != deployer,
            "C1: queue.owner() == deployer EOA -- ownership not handed to the Owner"
        );
        require(
            ctrlOwner != deployer,
            "C1: controller.owner() == deployer EOA -- ownership not handed to the Owner"
        );
        require(queueOwner == intendedOwner, "C1: queue.owner() != the intended Owner");
        require(ctrlOwner == intendedOwner, "C1: controller.owner() != the intended Owner");
    }

    // ── C2: wiring. Every intended host must (i) point its queue pointer at THIS
    //    queue (else that surface pays direct at zero-delay = fail-OPEN), (ii) point
    //    its controller pointer at THIS controller (else that surface quotes no fee
    //    and no delay and pays direct = fail-OPEN, per PerimeterLib.safeControllerLookup),
    //    AND (iii) be a registered allowed-source (else its records revert
    //    UnregisteredSource = bricked fail-CLOSED). All three mis-states must be
    //    caught before enabling. The revert names the specific host address for a
    //    fast fix. ──
    function _verifyWiring(ExitFeeController controller, ExitDelayQueue queue, address[] memory hosts)
        internal
        view
    {
        for (uint256 i; i < hosts.length; i++) {
            address host = hosts[i];
            // (defensive: a zero host is never an intended host — _resolveHosts
            //  filters/reverts them — but guard so a caller-supplied list cannot
            //  slip a 0.)
            require(host != address(0), "C2: intended host == 0");

            require(
                IExitDelayQueueHost(host).exitDelayQueue() == address(queue),
                string.concat(
                    "C2: host ",
                    vm.toString(host),
                    " not wired -- host.exitDelayQueue() != queue (fail-open zero-delay)"
                )
            );
            require(
                IExitFeeControllerHost(host).exitFeeController() == address(controller),
                string.concat(
                    "C2: host ",
                    vm.toString(host),
                    " not wired -- host.exitFeeController() != controller (fail-open zero-fee/zero-delay)"
                )
            );
            require(
                queue.isAllowedSource(host),
                string.concat(
                    "C2: host ",
                    vm.toString(host),
                    " not allowed-source -- queue.isAllowedSource(host)==false (bricked fail-closed)"
                )
            );
        }
    }
}

script/07_BlockExits.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Script} from "forge-std/Script.sol";
import {console2} from "forge-std/console2.sol";

import {ExitDelayQueue} from "../src/ExitDelayQueue.sol";
import {ExitFeeController} from "../src/ExitFeeController.sol";
import {IExitDelayQueue} from "../src/interfaces/IExitDelayQueue.sol";

/// @title  Block Exits - emergency stop for queued withdrawals
/// @notice READ-ONLY. Resolves who would be blocked, checks the call would not
///         revert, prints the exact calldata to submit from the Admin Safe, and
///         prints the command that verifies the result afterwards. It never
///         broadcasts: both block levers are `onlyAdminOrOwner`, and neither the
///         Admin nor the Owner is an EOA this script could sign for.
///
///         TWO LEVERS, DELIBERATELY DIFFERENT IN BLAST RADIUS:
///
///         `freeze` / `blacklist` - per-actor. A blocked originator, owner or
///         receiver cannot `executeExit` and cannot `recoverStuckExit`, so the
///         funds stay escrowed in the queue until the block is cleared or the
///         Owner resolves the request away. Everyone else keeps exiting
///         normally. `freeze` is the reversible hold (cleared by `unfreeze`);
///         `blacklist` is the confirmed state (cleared only by `unblacklist`).
///         A frozen address escalates to blacklisted in place. A blacklisted
///         address comes back down only through `downgrade`, which moves it to
///         frozen in one call with no window in which it is unblocked; the flat
///         `freeze` over a blacklisted address REVERTS on chain, which is why
///         this script refuses it here.
///
///         `pause` - global. Stops `executeExit`, `executeExits` and
///         `recoverStuckExit` for every caller - the originator, the owner, and
///         anyone delivering a contract-owned request - so users have no path of
///         their own while it holds. It does NOT stop new exits entering the
///         queue: the four `record*` functions and `receive` keep escrowing, so
///         the products keep working. It does NOT stop the block levers, the
///         Admin-or-Owner `resolveToProtocol` (still bound to a blacklisted
///         originator or owner and a matching active route), or the Owner's
///         `resolveByOwner`, which reaches only requests with a blacklisted party,
///         paused or not. Owner configuration and `sweepSurplus` are unaffected.
///         Use it when the target is not yet identified; use the per-actor lever
///         once it is.
///
///         WHAT NEITHER LEVER DOES: they do not stop a withdrawal from being
///         initiated on the product. Exits keep escrowing; what stops is the
///         payout at the far end of the delay. Disabling the perimeter itself
///         (`setSecurityPerimeterEnabled(false)` on the controller) is the
///         OPPOSITE action - it makes exits pay out directly, with no delay and
///         no queue. It is a liveness escape, not an incident lever.
///
///         BY-REQUEST MODE resolves each request's `originator` and `owner`, then
///         splits the ids into a CLEAN group (neither is already frozen or
///         blacklisted) and a HELD group (at least one of them already is). Only
///         a clean request's `receiver` is blocked alongside it - a request that
///         already has a blocked party is left with its receiver untouched,
///         because a blocked actor can set up an honest-looking receiver to move
///         funds through it. `freeze` sends only the clean group: a held request
///         is already covered by its existing block, so freezing it again would
///         change nothing, and the script skips it rather than submit a no-op;
///         it refuses outright when every id resolves to the held group.
///         `blacklist` sends both groups - it escalates a held party the same as
///         a clean one, just without its receiver. This is the speed lever:
///         given a list of malicious request ids from the watcher, it blocks
///         every clean party behind them, correctly holding receivers back where
///         they should be, without the operator transcribing addresses or
///         judging a receiver under pressure. The on-chain batch is atomic - one
///         unknown id reverts the whole call - so unknown ids are rejected here
///         rather than after signatures are collected.
///
/// @dev Usage:
///
///   export EXIT_DELAY_QUEUE=0x...            # the queue (required)
///   export EXIT_FEE_CONTROLLER=0x...         # controller; only the delay switch actions and their verify actions need it
///   export BLOCK_ACTION=freeze               # freeze|blacklist|downgrade|unfreeze|unblacklist
///                                            # |verify-freeze|verify-blacklist|verify-downgrade
///                                            # |verify-unfreeze|verify-unblacklist
///                                            # |pause|unpause|verify-pause|verify-unpause
///                                            # |disable-perimeter|enable-perimeter (controller kill switch)
///                                            # |verify-disable-perimeter|verify-enable-perimeter
///
///   # exactly one of these two for freeze/blacklist; actors only for downgrade and the clears:
///   export BLOCK_ACTORS=0xaaa,0xbbb          # addresses to block or clear
///   export BLOCK_REQUEST_IDS=41,42,43        # resolve the parties behind these requests
///
///   export BLOCK_REASON="incident label"     # by-request only; hashed into the event
///
///   forge script script/07_BlockExits.s.sol --rpc-url $RPC
///
///   Then submit the printed calldata from the Admin Safe and re-run with the
///   verify action the preview prints. The multisig reports success even when
///   the call inside it failed, so the state is read back rather than assumed:
///   `verify-freeze` and `verify-blacklist` read every resolved request's
///   parties back - the clean group's receiver must now read blocked, and the
///   held group's receiver must still read untouched; `verify-downgrade`,
///   `verify-unfreeze` and `verify-unblacklist` read the block states of the
///   named addresses (keep BLOCK_ACTORS or BLOCK_REQUEST_IDS set); `verify-pause`
///   and `verify-unpause` read the pause state; `verify-disable-perimeter` and
///   `verify-enable-perimeter` read the delay switch and its length. Each
///   verify-* action refuses unless the state matches the call.
contract BlockExits is Script {
    ExitDelayQueue internal queue;
    ExitFeeController internal controller;

    function run() external {
        _init(vm.envAddress("EXIT_DELAY_QUEUE"));
        address ctrl = vm.envOr("EXIT_FEE_CONTROLLER", address(0));
        if (ctrl != address(0)) {
            _initController(ctrl);
        }
        _dispatch(
            vm.envString("BLOCK_ACTION"),
            vm.envOr("BLOCK_ACTORS", ",", new address[](0)),
            vm.envOr("BLOCK_REQUEST_IDS", ",", new uint256[](0)),
            vm.envOr("BLOCK_REASON", string(""))
        );
    }

    function _init(address q) internal {
        queue = ExitDelayQueue(payable(q));
    }

    function _initController(address c) internal {
        controller = ExitFeeController(c);
    }

    /// @dev Every input is an explicit argument so the decision logic is
    ///      driveable without process-global env, which forge does not isolate
    ///      between parallel tests.
    function _dispatch(
        string memory action,
        address[] memory actors,
        uint256[] memory ids,
        string memory reason
    ) internal view {
        console2.log("=== Perimeter: block exits ===");
        console2.log("queue                :", address(queue));
        console2.log("admin                :", queue.admin());
        console2.log("owner                :", queue.owner());
        console2.log("perimeter paused     :", queue.securityPerimeterPaused());
        console2.log("action               :", action);
        console2.log("");

        bytes32 a = keccak256(bytes(action));
        if (a == keccak256("pause")) {
            _pause(true);
        } else if (a == keccak256("unpause")) {
            _pause(false);
        } else if (a == keccak256("freeze")) {
            _blockActors(true, actors, ids, reason);
        } else if (a == keccak256("blacklist")) {
            _blockActors(false, actors, ids, reason);
        } else if (a == keccak256("downgrade")) {
            _downgrade(actors, ids);
        } else if (a == keccak256("unfreeze")) {
            _clear(true, actors, ids);
        } else if (a == keccak256("unblacklist")) {
            _clear(false, actors, ids);
        } else if (a == keccak256("verify-freeze")) {
            _verify(actors, ids, IExitDelayQueue.BlockState.Frozen, true);
        } else if (a == keccak256("verify-blacklist")) {
            _verify(actors, ids, IExitDelayQueue.BlockState.Blacklisted, true);
        } else if (a == keccak256("verify-downgrade")) {
            _verify(actors, ids, IExitDelayQueue.BlockState.Frozen, false);
        } else if (a == keccak256("verify-unfreeze")) {
            _verify(actors, ids, IExitDelayQueue.BlockState.None, false);
        } else if (a == keccak256("verify-unblacklist")) {
            _verify(actors, ids, IExitDelayQueue.BlockState.None, false);
        } else if (a == keccak256("verify-pause")) {
            _verifyPause(true);
        } else if (a == keccak256("verify-unpause")) {
            _verifyPause(false);
        } else if (a == keccak256("disable-perimeter")) {
            _killSwitch(false);
        } else if (a == keccak256("enable-perimeter")) {
            _killSwitch(true);
        } else if (a == keccak256("verify-disable-perimeter")) {
            _verifyDelaySwitch(false);
        } else if (a == keccak256("verify-enable-perimeter")) {
            _verifyDelaySwitch(true);
        } else {
            revert(
                "BLOCK_ACTION must be one of: freeze, blacklist, downgrade, unfreeze, unblacklist, verify-freeze, verify-blacklist, verify-downgrade, verify-unfreeze, verify-unblacklist, pause, unpause, verify-pause, verify-unpause, disable-perimeter, enable-perimeter, verify-disable-perimeter, verify-enable-perimeter"
            );
        }
    }

    // --- Global pause ---------------------------------------------------

    function _pause(bool on) internal view {
        if (queue.securityPerimeterPaused() == on) {
            console2.log("ALREADY in the requested state - nothing to submit.");
            return;
        }
        if (on) {
            console2.log(
                "Stops executeExit, executeExits and recoverStuckExit for every caller - the originator, the"
            );
            console2.log("owner, and anyone delivering a contract-owned request. New exits keep escrowing.");
            console2.log(
                "Still live, and still paying out: the Admin-or-Owner resolveToProtocol (a blacklisted"
            );
            console2.log(
                "originator or owner with a matching active route) and the Owner's resolveByOwner, which"
            );
            console2.log(
                "reaches only requests with a blacklisted party, paused or not. The block levers, Owner"
            );
            console2.log("configuration and sweepSurplus are unaffected.");
        } else {
            console2.log(
                "Resumes executeExit, executeExits and recoverStuckExit. Per-actor blocks are unaffected."
            );
            console2.log("resolveByOwner is unchanged: it reaches only requests with a blacklisted party.");
        }
        _emitCalldata(
            address(queue),
            abi.encodeCall(IExitDelayQueue.setSecurityPerimeterPaused, (on)),
            on ? "pause" : "unpause"
        );
    }

    // --- Controller kill switch -----------------------------------------

    /// @dev The OPPOSITE lever to everything else in this script: switching
    ///      the withdrawal delay off makes every hooked withdrawal pay straight
    ///      out - nothing is held and nothing escrows. The Perimeter fee has its
    ///      own switch and is not touched here. It is a LIVENESS escape for a
    ///      broken perimeter, not an incident response; during an attack it is
    ///      the last thing to touch. Funds already escrowed are NOT released by
    ///      it - they stay in the queue behind their own holds and blocks.
    ///
    ///      Switching on reverts on the controller while the global delay length
    ///      is unset (0), and the multisig records a failed inner call without
    ///      reverting its own transaction. So the length is read first and the
    ///      preview refuses, rather than handing out calldata that fails silently.
    ///      The unset length is checked before the current state: a switch that
    ///      already reads on with no length holds nothing, so it is reported as
    ///      unset, never as already done.
    function _killSwitch(bool enabled) internal view {
        _requireController();
        console2.log("controller           :", address(controller));
        console2.log("controller admin     :", controller.admin());
        console2.log("controller owner     :", controller.owner());
        bool current = controller.securityPerimeterEnabled();
        uint32 length = controller.globalDelaySeconds();
        console2.log("perimeter enabled    :", current);
        console2.log("global delay length  :", uint256(length), "seconds (0 = unset)");
        if (enabled && length == 0) {
            if (current) {
                console2.log("The switch already reads on, but with the length unset no withdrawal is held.");
            }
            console2.log("WOULD REVERT (DelayUnset): the controller refuses to switch the delay on while");
            console2.log("its length is unset. The Owner sets it first with setGlobalDelaySeconds.");
            revert(
                "enable-perimeter would revert: the global delay length is unset (0) - the Owner must call setGlobalDelaySeconds first"
            );
        }
        if (current == enabled) {
            console2.log("ALREADY in the requested state - nothing to submit.");
            return;
        }
        console2.log(
            enabled
                ?
                "Switches the withdrawal delay back on: every hooked withdrawal that is not exempt is held for the global delay length again. The Perimeter fee has its own switch."
                :
                "LIVENESS ESCAPE: every hooked withdrawal pays straight out - nothing is held, nothing escrows. The Perimeter fee has its own switch. Already-escrowed funds stay held in the queue."
        );
        _emitCalldata(
            address(controller),
            abi.encodeCall(ExitFeeController.setSecurityPerimeterEnabled, (enabled)),
            enabled ? "enable-perimeter" : "disable-perimeter"
        );
    }

    // --- Per-actor block ------------------------------------------------

    /// @dev `freezing == false` means blacklist. Actor mode and by-request mode
    ///      build calls differently enough - one flat call against another that
    ///      may split into two - that each gets its own function; both are
    ///      previewed with the same vocabulary.
    function _blockActors(
        bool freezing,
        address[] memory actorsIn,
        uint256[] memory ids,
        string memory reason
    ) internal view {
        if (ids.length > 0) {
            require(
                actorsIn.length == 0,
                "set BLOCK_ACTORS or BLOCK_REQUEST_IDS, not both - they build different calls"
            );
            _blockByRequest(freezing, ids, reason);
            return;
        }
        _blockByAddress(freezing, actorsIn);
    }

    /// @dev Flat block by address. No request evidence rides on this call, so a
    ///      freeze over an already-blacklisted address is a caller mistake the
    ///      queue reverts on (`AlreadyBlacklisted`) - refused here instead,
    ///      while it costs nothing.
    function _blockByAddress(bool freezing, address[] memory actors) internal view {
        require(actors.length > 0, "set BLOCK_ACTORS or BLOCK_REQUEST_IDS");
        _validateActors(actors, false);
        bytes memory data = freezing
            ? abi.encodeWithSignature("freeze(address[])", actors)
            : abi.encodeWithSignature("blacklist(address[])", actors);

        IExitDelayQueue.BlockState target =
            freezing ? IExitDelayQueue.BlockState.Frozen : IExitDelayQueue.BlockState.Blacklisted;

        uint256 changing;
        bool wouldRevert;
        for (uint256 i = 0; i < actors.length; ++i) {
            IExitDelayQueue.BlockState from = queue.blockStateOf(actors[i]);
            IExitDelayQueue.BlockState to = target;
            string memory note;
            if (from == IExitDelayQueue.BlockState.Blacklisted && target == IExitDelayQueue.BlockState.Frozen)
            {
                to = from;
                note = "WOULD REVERT (already blacklisted - use BLOCK_ACTION=downgrade)";
                wouldRevert = true;
            } else if (from == target) {
                note = "already in this state (no state change, recorded evidence kept)";
            } else {
                note = "WILL CHANGE";
                ++changing;
            }
            console2.log(
                string.concat(
                    "  ", vm.toString(actors[i]), "  ", _stateName(from), " -> ", _stateName(to), "   ", note
                )
            );
        }
        console2.log("");
        console2.log("actors resolved      :", actors.length);
        console2.log("state changes        :", changing);
        // The on-chain batch is atomic, so one refused address wastes the whole
        // Safe round. Refuse here instead, while it costs nothing.
        require(
            !wouldRevert,
            "freeze would revert: an address is already blacklisted - use BLOCK_ACTION=downgrade to move it to frozen"
        );
        if (changing == 0) {
            console2.log("NOTE: no state changes. The call still succeeds and re-emits AccountBlocked.");
        }
        _emitCalldata(address(queue), data, freezing ? "freeze" : "blacklist");
    }

    /// @dev By-request block. Splits `ids` into a CLEAN group (originator and
    ///      owner both unblocked) and a HELD group (at least one of them
    ///      already frozen or blacklisted), then builds the call(s) the
    ///      Admin-or-Owner reach describes: `freeze` submits the clean group
    ///      only - a held request needs nothing more from a freeze, so it is
    ///      left out rather than sent for a no-op - and refuses outright when
    ///      every id is held; `blacklist` submits both groups, the held one
    ///      without its receiver, since escalating an already-frozen party is
    ///      exactly what blacklist is for.
    function _blockByRequest(bool freezing, uint256[] memory ids, string memory reason) internal view {
        bytes32 reasonHash = _reasonHash(reason);
        (uint256[] memory cleanIds, uint256[] memory heldIds) = _splitByHeldState(ids);

        console2.log("clean requests       :", cleanIds.length, "(neither party already blocked)");
        console2.log("held requests        :", heldIds.length, "(originator or owner already blocked)");
        console2.log("reason hash          :", vm.toString(reasonHash));
        console2.log("");

        if (freezing) {
            if (heldIds.length > 0) {
                console2.log(string.concat(vm.toString(heldIds.length), " request(s) skipped: already held"));
            }
            require(
                cleanIds.length > 0,
                string.concat(vm.toString(heldIds.length), " request(s) skipped: already held")
            );
            _previewByRequestGroup(cleanIds, true, IExitDelayQueue.BlockState.Frozen);
            bytes memory data = abi.encodeWithSignature(
                "freezeFromRequest(uint256[],bool,bytes32)", cleanIds, true, reasonHash
            );
            _emitCalldata(address(queue), data, "freeze");
            return;
        }

        // Blacklist escalates a held party exactly as it does a clean one, so
        // both groups go out - the held group just never reaches its receiver.
        if (cleanIds.length > 0) {
            _previewByRequestGroup(cleanIds, true, IExitDelayQueue.BlockState.Blacklisted);
            bytes memory cleanData = abi.encodeWithSignature(
                "blacklistFromRequest(uint256[],bool,bytes32)", cleanIds, true, reasonHash
            );
            _emitCalldata(address(queue), cleanData, "blacklist");
        }
        if (heldIds.length > 0) {
            _previewByRequestGroup(heldIds, false, IExitDelayQueue.BlockState.Blacklisted);
            bytes memory heldData = abi.encodeWithSignature(
                "blacklistFromRequest(uint256[],bool,bytes32)", heldIds, false, reasonHash
            );
            _emitCalldata(address(queue), heldData, "blacklist");
        }
    }

    /// @dev Prints the parties a by-request group resolves to and the state
    ///      change each one is headed for.
    function _previewByRequestGroup(
        uint256[] memory ids,
        bool includeReceiver,
        IExitDelayQueue.BlockState target
    ) internal view {
        console2.log(
            includeReceiver ? "  clean group (receiver included):" : "  held group (receiver left alone):"
        );
        address[] memory actors = _partiesBehind(ids, includeReceiver);
        for (uint256 i = 0; i < actors.length; ++i) {
            IExitDelayQueue.BlockState from = queue.blockStateOf(actors[i]);
            console2.log(
                string.concat(
                    "    ", vm.toString(actors[i]), "  ", _stateName(from), " -> ", _stateName(target)
                )
            );
        }
        console2.log("");
    }

    // --- Blacklisted -> Frozen ------------------------------------------

    /// @dev Clear/downgrade require distinct actors: a second transition for
    ///      the same address would revert the batch. Blocks permit repeats.
    function _validateActors(address[] memory actors, bool requireDistinct) internal pure {
        for (uint256 i = 0; i < actors.length; ++i) {
            require(actors[i] != address(0), "BLOCK_ACTORS contains the zero address");
            if (requireDistinct) {
                for (uint256 j = 0; j < i; ++j) {
                    require(actors[i] != actors[j], "BLOCK_ACTORS contains a duplicate address");
                }
            }
        }
    }

    /// @dev The one call that weakens a block without unblocking first, for an
    ///      address blacklisted in haste that should only be held while it is
    ///      investigated. The queue reverts on any address that is not
    ///      Blacklisted and the batch is atomic, so every address is checked here.
    function _downgrade(address[] memory actors, uint256[] memory ids) internal view {
        require(actors.length > 0, "set BLOCK_ACTORS");
        require(ids.length == 0, "downgrade is by address only - the queue has no by-request downgrade");
        _validateActors(actors, true);

        bool wouldRevert;
        for (uint256 i = 0; i < actors.length; ++i) {
            IExitDelayQueue.BlockState from = queue.blockStateOf(actors[i]);
            bool ok = from == IExitDelayQueue.BlockState.Blacklisted;
            if (!ok) wouldRevert = true;
            console2.log(
                string.concat(
                    "  ",
                    vm.toString(actors[i]),
                    "  ",
                    _stateName(from),
                    ok ? " -> Frozen" : "   WOULD REVERT (not blacklisted)"
                )
            );
        }
        console2.log("");
        require(
            !wouldRevert,
            "downgrade requires every address to be Blacklisted - freeze is how a clear address is held"
        );
        console2.log("NOTE: the recorded trigger is kept - a downgrade is still a block.");
        _emitCalldata(
            address(queue), abi.encodeWithSignature("downgradeToFrozen(address[])", actors), "downgrade"
        );
    }

    // --- Per-actor clear ------------------------------------------------

    /// @dev `unfreezing == false` means unblacklist. The contract reverts when
    ///      the current state does not match the clear being run, and the batch
    ///      is atomic, so one wrong address would waste a whole Safe round. Every
    ///      address is checked here first.
    function _clear(bool unfreezing, address[] memory actors, uint256[] memory ids) internal view {
        require(actors.length > 0, "set BLOCK_ACTORS");
        _validateActors(actors, true);
        require(ids.length == 0, "clears are by address only - the queue has no by-request clear");

        IExitDelayQueue.BlockState required =
            unfreezing ? IExitDelayQueue.BlockState.Frozen : IExitDelayQueue.BlockState.Blacklisted;

        bool wouldRevert;
        for (uint256 i = 0; i < actors.length; ++i) {
            IExitDelayQueue.BlockState from = queue.blockStateOf(actors[i]);
            bool ok = from == required;
            if (!ok) wouldRevert = true;
            console2.log(
                string.concat(
                    "  ",
                    vm.toString(actors[i]),
                    "  ",
                    _stateName(from),
                    ok ? " -> None" : "   WOULD REVERT (wrong clear for this state)"
                )
            );
        }
        console2.log("");
        require(
            !wouldRevert,
            unfreezing
                ? "unfreeze requires every address to be Frozen - use unblacklist for blacklisted ones"
                : "unblacklist requires every address to be Blacklisted - use unfreeze for frozen ones"
        );

        _emitCalldata(
            address(queue),
            unfreezing
                ? abi.encodeWithSignature("unfreeze(address[])", actors)
                : abi.encodeWithSignature("unblacklist(address[])", actors),
            unfreezing ? "unfreeze" : "unblacklist"
        );
    }

    // --- Verify ---------------------------------------------------------

    /// @dev Run after a pause or unpause executes. The multisig reports success
    ///      even when the call inside it failed, so the pause state is read back
    ///      and the check refuses unless it matches the call that was emitted.
    function _verifyPause(bool paused) internal view {
        if (queue.securityPerimeterPaused() != paused) {
            revert(
                paused
                    ? "NOT CONFIRMED: the queue reads unpaused - the pause did not take effect"
                    : "NOT CONFIRMED: the queue still reads paused - the resume did not take effect"
            );
        }
        console2.log(paused ? "CONFIRMED: the queue reads paused." : "CONFIRMED: the queue reads unpaused.");
    }

    /// @dev Run after the delay switch executes. Reads the switch and the length
    ///      back and refuses unless they match the call that was emitted. A
    ///      switch-on is confirmed only with a length set: a switch that reads on
    ///      with the length unset holds no withdrawal.
    function _verifyDelaySwitch(bool enabled) internal view {
        _requireController();
        bool current = controller.securityPerimeterEnabled();
        uint32 length = controller.globalDelaySeconds();
        console2.log("controller           :", address(controller));
        console2.log("perimeter enabled    :", current);
        console2.log("global delay length  :", uint256(length), "seconds (0 = unset)");
        if (enabled) {
            if (!current) {
                revert("NOT CONFIRMED: the delay switch reads off - the switch-on did not take effect");
            }
            if (length == 0) {
                revert(
                    "NOT CONFIRMED: the delay switch reads on but the length is unset (0) - no withdrawal is held"
                );
            }
            console2.log("CONFIRMED: the delay switch reads on with a length set.");
        } else {
            if (current) {
                revert("NOT CONFIRMED: the delay switch still reads on - the switch-off did not take effect");
            }
            console2.log("CONFIRMED: the delay switch reads off - hooked withdrawals pay straight out.");
        }
    }

    /// @dev Run after a block, downgrade or clear executes. By address
    ///      (`ids.length == 0`, or a downgrade/clear verify), this reads the
    ///      live state of every named address and refuses unless every one of
    ///      them reads `target` - the state the submitted call was supposed to
    ///      produce - so a failed inner call is not read as confirmation from a
    ///      multisig transaction that itself reported success. `acceptStronger`
    ///      widens the check to "at least as strong as `target`": a freeze over
    ///      an already-blacklisted party correctly holds the stronger state
    ///      instead of moving to Frozen, and that must read as confirmed, not as
    ///      a freeze that failed. A downgrade or a clear never sets it - there, a
    ///      party still reading a stronger state than the target is the genuine
    ///      unconfirmed case.
    ///
    ///      By request, with `acceptStronger` set (`verify-freeze` /
    ///      `verify-blacklist`), the check instead goes through `_verifyByRequest`,
    ///      which reads the clean and held groups apart.
    function _verify(
        address[] memory actorsIn,
        uint256[] memory ids,
        IExitDelayQueue.BlockState target,
        bool acceptStronger
    ) internal view {
        if (ids.length > 0 && acceptStronger) {
            _verifyByRequest(ids, target);
            return;
        }

        address[] memory actors = ids.length > 0 ? _partiesBehind(ids, false) : actorsIn;
        require(actors.length > 0, "set BLOCK_ACTORS or BLOCK_REQUEST_IDS");

        bool mismatchFound;
        address mismatchAddr;
        IExitDelayQueue.BlockState mismatchState;
        bool anyStronger;
        for (uint256 i = 0; i < actors.length; ++i) {
            IExitDelayQueue.BlockState state = queue.blockStateOf(actors[i]);
            console2.log(
                string.concat(
                    "  ",
                    vm.toString(actors[i]),
                    "  ",
                    _stateName(state),
                    "  trigger request #",
                    vm.toString(queue.blockTrigger(actors[i]))
                )
            );
            bool strongerThanAsked = acceptStronger && uint8(state) > uint8(target);
            if (strongerThanAsked) anyStronger = true;
            if (!mismatchFound && state != target && !strongerThanAsked) {
                mismatchFound = true;
                mismatchAddr = actors[i];
                mismatchState = state;
            }
        }
        if (mismatchFound) {
            revert(
                string.concat(
                    "NOT CONFIRMED: ",
                    vm.toString(mismatchAddr),
                    " reads ",
                    _stateName(mismatchState),
                    ", not ",
                    _stateName(target),
                    " - the call did not take effect"
                )
            );
        }
        console2.log(
            anyStronger
                ? string.concat(
                    "CONFIRMED: every resolved address reads ",
                    _stateName(target),
                    " or a stronger block state it already held."
                )
                : string.concat("CONFIRMED: every resolved address reads ", _stateName(target), ".")
        );
    }

    /// @dev Verifies a by-request freeze or blacklist, reading the clean and
    ///      held groups apart rather than re-deriving them from the current
    ///      originator/owner state - after a blacklist both groups read the
    ///      same target state on those two parties, so that state alone cannot
    ///      say which group a request was in. `_receiverIncludedInBatch` reads
    ///      the group instead: a receiver counts as included when its recorded
    ///      trigger names ANY id in this same batch that also resolves to that
    ///      address in ANY role - receiver, originator, or owner - not only
    ///      `ids[i]`'s own receiver field. The trigger keeps only the
    ///      last id that wrote it, so two ids sharing an address in the same
    ///      clean-group call would otherwise leave the earlier one unmatched
    ///      even though its receiver was blocked alongside it. This reads true
    ///      only for the clean group, under either action - a receiver an
    ///      unrelated batch or a flat lever blocked still names an id outside
    ///      this batch, or no id at all. For a request that reads clean this
    ///      way, originator, owner and receiver must all reach `target` or
    ///      stronger. For one that reads held, the receiver must still read
    ///      below `target` (the call left it alone); its originator and owner
    ///      are checked at the strength each action actually gives a held
    ///      request - freeze never touches it, so only the party that was
    ///      already blocked is guaranteed to still read blocked, not both;
    ///      blacklist escalates it exactly as it does a clean request, so both
    ///      must reach `target`. A receiver that reads excluded from the
    ///      batch but whose own request IS evidenced (`_requestEvidenced`) is
    ///      flagged rather than silently confirmed as held - see
    ///      `_receiverCheck` for why that reads as unambiguous drift under
    ///      freeze (a held id's freeze call never runs, so it is never
    ///      evidenced) but only as an unresolvable ambiguity under blacklist
    ///      (a held id's call DOES run, just without the receiver, so it is
    ///      evidenced exactly like a clean id's) - by-request verify refuses
    ///      a blacklisted held id's receiver claim either way rather than
    ///      guess; re-verify a held id's parties by address instead. This
    ///      function proves what current chain state shows, not what an
    ///      intervening admin action may have undone.
    function _verifyByRequest(uint256[] memory ids, IExitDelayQueue.BlockState target) internal view {
        bool mismatchFound;
        address mismatchAddr;
        string memory mismatchNote;

        for (uint256 i = 0; i < ids.length; ++i) {
            IExitDelayQueue.ExitRequest memory r = queue.getRequest(ids[i]);
            require(
                r.status != IExitDelayQueue.ExitStatus.None,
                string.concat("unknown request id ", vm.toString(ids[i]), " - the batch is atomic")
            );

            IExitDelayQueue.BlockState oState = queue.blockStateOf(r.originator);
            IExitDelayQueue.BlockState wState = queue.blockStateOf(r.owner);
            IExitDelayQueue.BlockState rState = queue.blockStateOf(r.receiver);
            bool receiverIncluded = _receiverIncludedInBatch(ids, i, r.receiver);

            console2.log(
                string.concat(
                    "  request #",
                    vm.toString(ids[i]),
                    "  originator ",
                    _stateName(oState),
                    "  owner ",
                    _stateName(wState),
                    "  receiver ",
                    _stateName(rState),
                    receiverIncluded ? "  (clean group)" : "  (held group - receiver left alone)"
                )
            );

            bool partiesOk;
            if (receiverIncluded || target == IExitDelayQueue.BlockState.Blacklisted) {
                // Clean group under either action, or held group under
                // blacklist: both parties are always processed, so both must
                // reach target.
                partiesOk = uint8(oState) >= uint8(target) && uint8(wState) >= uint8(target);
            } else {
                // Held group under freeze: the request was skipped outright, so
                // only the party that was already blocked is guaranteed to
                // still read blocked - not both.
                partiesOk = uint8(oState) >= uint8(target) || uint8(wState) >= uint8(target);
            }
            if (!mismatchFound && !partiesOk) {
                mismatchFound = true;
                mismatchAddr = r.originator;
                mismatchNote = "originator/owner did not reach the expected block state";
            }

            if (!mismatchFound) {
                (bool receiverOk, string memory receiverNote) =
                    _receiverCheck(ids, i, target, rState, receiverIncluded);
                if (!receiverOk) {
                    mismatchFound = true;
                    mismatchAddr = r.receiver;
                    mismatchNote = receiverNote;
                }
            }

            // Evidence check, independent of the state comparison above: a
            // party reading `target` or stronger is not proof that THIS id's
            // own call is what put it there. `_setBlock` only writes
            // `_blockTrigger` for a party when the call touching it actually
            // ran, so `blockTrigger(party) == ids[i]` is the on-chain link
            // back to this exact request. Without it, the state comparison
            // may have passed only because the party already sat at or above
            // `target` from an earlier, unrelated action while this specific
            // call never ran (it reverted, or - for a held request under
            // freeze - was never submitted). Either way no withdrawal
            // escapes, so this does not fail verification; it only keeps the
            // CONFIRMED banner honest about whose evidence backs it.
            if (partiesOk && !mismatchFound && !_requestEvidenced(ids[i])) {
                console2.log(
                    string.concat(
                        "    NOTE: request #",
                        vm.toString(ids[i]),
                        " reads the expected state, but this action's own evidence was not recorded",
                        " - the block predates it."
                    )
                );
            }
        }

        if (mismatchFound) {
            revert(
                string.concat(
                    "NOT CONFIRMED: ",
                    vm.toString(mismatchAddr),
                    " - ",
                    mismatchNote,
                    " - the call did not take effect"
                )
            );
        }
        console2.log(
            "CONFIRMED: every clean request's receiver is blocked and every held request's receiver is untouched."
        );
    }

    /// @dev Split out of `_verifyByRequest` to keep its own frame inside the
    ///      stack limit. Included receivers must reach `target`; excluded
    ///      ones must read below it UNLESS this id's own call is evidenced
    ///      (`_requestEvidenced`), in which case this cannot be confirmed as
    ///      a legitimate exclusion. That check applies to BOTH actions, but
    ///      for a different reason each time.
    ///
    ///      Under freeze, `_blockByRequest` only ever submits the clean group,
    ///      always with the receiver included - a held id's freeze call never
    ///      runs at all, so it is never evidenced. An evidenced-but-excluded
    ///      receiver there can therefore only mean one thing: this id WAS
    ///      clean when submitted, and a later, unrelated action (e.g. an
    ///      Admin `unfreeze` on the receiver alone) cleared what this call
    ///      set. Current chain state alone cannot tell "genuinely held, never
    ///      touched" apart from "was blocked, later cleared" in general, but
    ///      for freeze specifically the first possibility is ruled out by
    ///      construction, so the flag is unambiguous.
    ///
    ///      Under blacklist, `_blockByRequest` submits the held group too -
    ///      escalating a held party exactly as it does a clean one - just
    ///      without its receiver. That means a held id's own call IS
    ///      evidenced (its originator/owner trigger names it), exactly like a
    ///      clean id's. So an evidenced-but-excluded receiver under blacklist
    ///      is genuinely ambiguous: it is either a clean request whose
    ///      receiver was blocked and later cleared (the bug this guards
    ///      against), or a held request whose receiver was correctly never
    ///      touched (`freezeReceiver=false`, by design) - both leave the
    ///      identical trace (receiver's trigger absent, originator/owner
    ///      trigger naming this id). By-request verify cannot resolve that
    ///      ambiguity from chain state and refuses rather than guess either
    ///      way; a held id's parties must be re-verified by address
    ///      (`BLOCK_ACTORS`), which makes no claim about the receiver at all.
    function _receiverCheck(
        uint256[] memory ids,
        uint256 i,
        IExitDelayQueue.BlockState target,
        IExitDelayQueue.BlockState rState,
        bool receiverIncluded
    ) internal view returns (bool ok, string memory note) {
        if (receiverIncluded) {
            return (uint8(rState) >= uint8(target), "receiver did not reach the expected block state");
        }
        if (_requestEvidenced(ids[i])) {
            if (target == IExitDelayQueue.BlockState.Frozen) {
                return (
                    false,
                    string.concat(
                        "receiver's own freeze call set its block, but it now reads ",
                        _stateName(rState),
                        " - a later action must have cleared it; this cannot be confirmed as still blocked"
                    )
                );
            }
            return (
                false,
                string.concat(
                    "receiver reads ",
                    _stateName(rState),
                    " with no trigger of its own, but this id's own evidence is recorded - this cannot be told apart",
                    " from a clean request whose receiver was blocked then cleared; re-verify this id's",
                    " originator/owner alone with BLOCK_ACTORS, which makes no claim about the receiver"
                )
            );
        }
        return (
            uint8(rState) < uint8(target),
            "receiver was blocked but belongs to an already-held request - it should have been left alone"
        );
    }

    /// @dev True when `receiver`'s recorded trigger names this batch's own
    ///      handling of it: `ids[i]` itself, or another id in `ids` that also
    ///      resolves to `receiver` IN ANY ROLE - its own receiver, its
    ///      originator, or its owner. `_blockTrigger` keeps only the last id
    ///      that wrote it, so checking `ids[i]` alone misreads every id but
    ///      the last one when several ids in the same batch touch the same
    ///      address - the shape several malicious withdrawals from one wallet
    ///      produce, whether they share a payout address or one pays out to
    ///      an address the same wallet also used to originate a different
    ///      withdrawal. Checking every role on the whole batch instead is
    ///      still specific to it: a trigger of 0 (never blocked, or blocked by
    ///      a flat lever that carries no id) or one naming an id outside `ids`
    ///      (an earlier, unrelated action) correctly reads not included.
    function _receiverIncludedInBatch(uint256[] memory ids, uint256 i, address receiver)
        internal
        view
        returns (bool)
    {
        uint256 trigger = queue.blockTrigger(receiver);
        if (trigger == ids[i]) return true;
        if (trigger == 0) return false;
        for (uint256 k = 0; k < ids.length; ++k) {
            if (k == i || trigger != ids[k]) continue;
            IExitDelayQueue.ExitRequest memory rk = queue.getRequest(ids[k]);
            if (rk.receiver == receiver || rk.originator == receiver || rk.owner == receiver) return true;
        }
        return false;
    }

    /// @dev True when request `id`'s own by-request call is the reason its
    ///      resolved originator (and owner, if distinct) currently carry the
    ///      block they read - i.e. `_setBlock` actually ran while processing
    ///      `id` and last wrote `_blockTrigger` for both. False means their
    ///      current state, whatever it is, was not produced by this id's own
    ///      call - it predates it or comes from a different one. Read after
    ///      the fact, so this deliberately does not (cannot) distinguish "the
    ///      call for this id was skipped by design" from "it was submitted
    ///      and reverted" - both leave the same on-chain trace, which is
    ///      exactly the ambiguity `_verifyByRequest` surfaces rather than
    ///      papering over.
    function _requestEvidenced(uint256 id) internal view returns (bool) {
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (queue.blockTrigger(r.originator) != id) return false;
        if (r.owner != r.originator && queue.blockTrigger(r.owner) != id) return false;
        return true;
    }

    // --- Helpers --------------------------------------------------------

    /// @dev Splits by-request ids into a CLEAN group (originator and owner both
    ///      unblocked) and a HELD group (at least one of them already frozen or
    ///      blacklisted), read live - the same rule and the same live state
    ///      `_partiesBehind` resolves against, so the split reflects exactly
    ///      what the multisig will see. Rejects unknown ids up front, same as
    ///      `_partiesBehind`.
    function _splitByHeldState(uint256[] memory ids)
        internal
        view
        returns (uint256[] memory clean, uint256[] memory held)
    {
        uint256[] memory cleanBuf = new uint256[](ids.length);
        uint256[] memory heldBuf = new uint256[](ids.length);
        uint256 nc;
        uint256 nh;
        for (uint256 i = 0; i < ids.length; ++i) {
            IExitDelayQueue.ExitRequest memory r = queue.getRequest(ids[i]);
            require(
                r.status != IExitDelayQueue.ExitStatus.None,
                string.concat("unknown request id ", vm.toString(ids[i]), " - the batch is atomic")
            );
            bool isClean = queue.blockStateOf(r.originator) == IExitDelayQueue.BlockState.None
                && queue.blockStateOf(r.owner) == IExitDelayQueue.BlockState.None;
            if (isClean) {
                cleanBuf[nc++] = ids[i];
            } else {
                heldBuf[nh++] = ids[i];
            }
        }
        clean = new uint256[](nc);
        for (uint256 i = 0; i < nc; ++i) {
            clean[i] = cleanBuf[i];
        }
        held = new uint256[](nh);
        for (uint256 i = 0; i < nh; ++i) {
            held[i] = heldBuf[i];
        }
    }

    /// @dev Resolve every party the on-chain batch would block, with the same
    ///      rules the contract uses: originator always, owner when distinct,
    ///      receiver only when flagged. Rejects unknown ids so the Safe never
    ///      signs a call that reverts on-chain.
    function _partiesBehind(uint256[] memory ids, bool freezeReceiver)
        internal
        view
        returns (address[] memory)
    {
        address[] memory buf = new address[](ids.length * 3);
        uint256 n;
        for (uint256 i = 0; i < ids.length; ++i) {
            IExitDelayQueue.ExitRequest memory r = queue.getRequest(ids[i]);
            require(
                r.status != IExitDelayQueue.ExitStatus.None,
                string.concat("unknown request id ", vm.toString(ids[i]), " - the batch is atomic")
            );
            console2.log(
                string.concat(
                    "  request #",
                    vm.toString(ids[i]),
                    "  status ",
                    vm.toString(uint256(uint8(r.status))),
                    "  amount ",
                    vm.toString(uint256(r.amount)),
                    "  token ",
                    vm.toString(r.token),
                    "  unlockAt ",
                    vm.toString(uint256(r.unlockAt))
                )
            );
            n = _push(buf, n, r.originator);
            if (r.owner != r.originator) n = _push(buf, n, r.owner);
            if (freezeReceiver) n = _push(buf, n, r.receiver);
        }
        address[] memory out = new address[](n);
        for (uint256 i = 0; i < n; ++i) {
            out[i] = buf[i];
        }
        console2.log("");
        return out;
    }

    /// @dev Append unless already present - the same address behind several
    ///      requests should be listed once in the preview.
    function _push(address[] memory buf, uint256 n, address a) internal pure returns (uint256) {
        for (uint256 i = 0; i < n; ++i) {
            if (buf[i] == a) return n;
        }
        buf[n] = a;
        return n + 1;
    }

    /// @dev The reason is hashed, not stored: the event carries the digest and
    ///      the incident record carries the text. An empty reason is allowed but
    ///      called out, because the digest is the only on-chain link to why.
    function _reasonHash(string memory reason) internal view returns (bytes32) {
        if (bytes(reason).length == 0) {
            console2.log("WARNING: BLOCK_REASON is empty - the event will carry a zero digest.");
            return bytes32(0);
        }
        return keccak256(bytes(reason));
    }

    /// @dev Prints the calldata to submit for `action`, then the verify action
    ///      that reads back what it changed.
    function _emitCalldata(address to, bytes memory data, string memory action) internal view {
        console2.log("--- submit from the Admin multisig ---");
        console2.log("to   :", to);
        console2.log("value: 0");
        console2.log("data :", vm.toString(data));
        console2.log("");
        console2.log("Submit via the multisig's Read/Write contract tab on Blockscout:");
        console2.log("  https://rootstock.blockscout.com/address/<ADMIN_MULTISIG>?tab=read_write_contract");
        console2.log("  method 20. submitTransaction: destination = `to` above, value = 0,");
        console2.log("  data = the hex above. Simulate first, then Write. Further owners");
        console2.log("  confirm the emitted transactionId via method 4. confirmTransaction;");
        console2.log("  the threshold confirmation executes the call in the same transaction.");
        console2.log("");
        console2.log("--- then confirm the result ---");
        console2.log(
            "The multisig reports success even when the call inside it failed, so read the state after it executes:"
        );
        console2.log(
            string.concat(
                "BLOCK_ACTION=",
                _verifyActionFor(action),
                " forge script script/07_BlockExits.s.sol --rpc-url $RPC"
            )
        );
    }

    /// @dev The verify action that reads back what `action` changed - the pause
    ///      state after pause or unpause, the switch and length after the delay
    ///      switch, or the block states of the parties after a block, downgrade
    ///      or clear. Every action's verify action is its own name prefixed with
    ///      "verify-", so each one refuses on the exact state it is named for.
    function _verifyActionFor(string memory action) internal pure returns (string memory) {
        return string.concat("verify-", action);
    }

    /// @dev The delay switch lives on the controller, so its actions and their
    ///      verification need its address.
    function _requireController() internal view {
        require(
            address(controller) != address(0),
            "set EXIT_FEE_CONTROLLER for disable-perimeter / enable-perimeter and their verify actions"
        );
    }

    function _stateName(IExitDelayQueue.BlockState s) internal pure returns (string memory) {
        if (s == IExitDelayQueue.BlockState.Frozen) return "Frozen";
        if (s == IExitDelayQueue.BlockState.Blacklisted) return "Blacklisted";
        return "None";
    }
}

script/InspectController.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Script} from "forge-std/Script.sol";
import {console2} from "forge-std/console2.sol";
import {stdJson} from "forge-std/StdJson.sol";

import {ExitFeeController} from "../src/ExitFeeController.sol";
import {IExitFeeController} from "../src/interfaces/IExitFeeController.sol";
import {ExitDelayQueue} from "../src/ExitDelayQueue.sol";

/// @title  Inspect ExitFeeController
/// @notice Prints the live state of a deployed `ExitFeeController` proxy:
///         ownership, global flags, surface policies, and every configured
///         sub-product / actor override (read from the on-chain enumeration
///         index -- no log scans). Beside every stored sub-product and actor
///         row, on both the fee and the delay side, it prints the value that
///         actually resolves for that address, labelled with the sub-product
///         used, so an entry written inactive that is still exempt through a
///         broader tier reads as exempt. While the delay is switched off, each
///         delay row also shows what it would resolve to once switched on.
///
/// @dev Usage:
///
///   forge script script/InspectController.s.sol \
///       --rpc-url $RSK_RPC --sig "run(uint256)" <chainId>
///
/// Reads `deployments/<chainId>/ExitFeeController.json` to find the proxy
/// address (committed for mainnet/testnet, gitignored for local anvil).
/// It never broadcasts and produces no transaction. The only state it writes is
/// in this run's local simulation: for the "would resolve once switched on"
/// lines it writes the controller's delay switch and length word with
/// `vm.store`, quotes, and writes the original word back.
contract InspectController is Script {
    using stdJson for string;

    // Every canonical surface, including the ones that ship off -- an
    // inspector that skipped them would report "off" as silence. Keep
    // aligned with the registered surface names and the set that
    // 04_BootstrapController.s.sol writes.
    string[5] internal surfaceNames = [
        "PERIMETER_SURFACE_LENDING_LENDER_WITHDRAW",
        "PERIMETER_SURFACE_LENDING_BORROWER_WITHDRAW",
        "PERIMETER_SURFACE_ZERO_WITHDRAW_COLL",
        "PERIMETER_SURFACE_ZERO_CLAIM_SURPLUS",
        "PERIMETER_SURFACE_AMM_REMOVE_LIQUIDITY"
    ];

    // EIP-1967 implementation storage slot.
    bytes32 internal constant EIP1967_IMPL_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function run(uint256 chainId) external {
        string memory artifact =
            vm.readFile(string.concat("deployments/", vm.toString(chainId), "/ExitFeeController.json"));
        address proxy = artifact.readAddress(".proxyAddress");
        address savedImpl = artifact.readAddress(".implAddress");

        ExitFeeController c = ExitFeeController(proxy);

        console2.log("ExitFeeController @", proxy);
        console2.log("  chainId:     ", chainId);
        console2.log("  saved impl:  ", savedImpl);

        address onchainImpl = address(uint160(uint256(vm.load(proxy, EIP1967_IMPL_SLOT))));
        if (onchainImpl != savedImpl) {
            console2.log("  WARNING on-chain impl differs:", onchainImpl);
            console2.log("  deployment artifact may be stale -- run tools/finalize-deployment.sh");
        }
        console2.log("");

        console2.log(unicode"── Ownership ─────────────────────────────────────────");
        console2.log("  owner:        ", c.owner());
        console2.log("  pendingOwner: ", c.pendingOwner());
        console2.log("  admin:        ", c.admin());
        console2.log("");

        console2.log(unicode"── Global state ──────────────────────────────────────");
        console2.log("  exitFeeEnabled:", c.exitFeeEnabled());
        console2.log("  feeReceiver:   ", c.feeReceiver());
        console2.log("  MAX_BPS:       ", uint256(c.MAX_BPS()));
        console2.log("");

        console2.log(unicode"── Delay perimeter (global) ──────────────────────────");
        bool delayOn = c.securityPerimeterEnabled();
        uint32 delayLength = c.globalDelaySeconds();
        console2.log("  securityPerimeterEnabled:", delayOn);
        console2.log(
            string.concat(
                "  globalDelaySeconds:       ",
                vm.toString(uint256(delayLength)),
                _delayLengthNote(delayOn, delayLength)
            )
        );
        console2.log("  admin:                   ", c.admin());
        console2.log("");

        // ── single-guardian identity assertion. The controller keeps its
        //    OWN local `admin` (used by the kill switch AND by setFeeReceiver,
        //    which re-points where the Perimeter fee is paid) and NEVER reads
        //    queue.admin() at runtime (that would couple those levers to queue
        //    liveness and break). Instead this tooling asserts, at
        //    deploy/inspect time, that the two guardians are ONE identity so a
        //    single Safe bundle rotates both. Off unless the queue artifact exists.
        _assertSingleGuardian(c, chainId);

        console2.log(unicode"── Surface policies + delay bypass ───────────────────");
        for (uint256 i = 0; i < surfaceNames.length; i++) {
            _printSurface(c, surfaceNames[i]);
        }

        // ── dump EVERY delay-bypass entry via the on-chain enumeration
        //    getters — NOT the hardcoded surface list above. A bypass under an
        //    arbitrary surfaceId (never registered as a named fee surface) is
        //    still fully surfaced here.
        _printDelayBypassRegistry(c);
    }

    /// @dev What a delay length means beside its raw value. Zero is the unset
    ///      state: the controller refuses to switch the delay on while it holds,
    ///      and a switch that reads on with a zero length holds nothing. A
    ///      non-zero length needs no note.
    function _delayLengthNote(bool enabled, uint32 length) internal pure returns (string memory) {
        if (length != 0) return "";
        if (enabled) return "  WARNING: switched on with the length unset (0) - no withdrawal is held";
        return "  (0 = unset: switching the delay on is refused until the Owner sets a length)";
    }

    // ── Resolved values beside stored rows ──────────────────────────────

    /// @dev Gross used to show what a fee row resolves to; the labels print it
    ///      as 1e18. The resolved rate is what matters, the amount only makes
    ///      the charge visible.
    uint256 internal constant SAMPLE_GROSS = 1e18;

    /// @dev The sub-products an actor row is resolved at: none first, then every
    ///      sub-product stored under the same surface on the same side. What an
    ///      actor resolves to depends on the sub-product it withdraws from, so an
    ///      exemption reachable only through a sub-product entry is shown too.
    function _resolutionSubProducts(address[] memory keys) internal pure returns (address[] memory subs) {
        subs = new address[](keys.length + 1);
        for (uint256 i = 0; i < keys.length; i++) {
            subs[i + 1] = keys[i];
        }
    }

    /// @dev Names the resolution a line reports: the sub-product used and, for a
    ///      sub-product row, that no actor entry applied.
    function _resolutionLabel(address sub, address actor) internal pure returns (string memory) {
        string memory label =
            sub == address(0) ? "sub-product none" : string.concat("sub-product ", vm.toString(sub));
        return actor == address(0) ? string.concat(label, ", actor without an entry") : label;
    }

    /// @dev What `quoteExitDelay` returns for this address, in words. A zero
    ///      reads as exempt only while the delay is switched on with a length
    ///      set; a switched-off delay and an unset length are named as such.
    ///      While the delay is switched off every row reads 0s, so the line also
    ///      says what the row would resolve to once switched on.
    function _resolvedDelay(ExitFeeController c, bytes32 id, address sub, address actor)
        internal
        returns (string memory)
    {
        uint32 d = c.quoteExitDelay(id, sub, actor);
        bool switchedOn = c.securityPerimeterEnabled();
        string memory value;
        if (d != 0) value = string.concat("delayed ", vm.toString(uint256(d)), "s");
        else if (!switchedOn) value = "0s (delay switched off)";
        else if (c.globalDelaySeconds() == 0) value = "0s (length unset - nothing held)";
        else value = "exempt (0s)";
        string memory line = string.concat("resolves ", value, " for ", _resolutionLabel(sub, actor));
        if (switchedOn) return line;
        return string.concat(line, "; would resolve once switched on: ", _delayOnceSwitchedOn(c, id, sub, actor));
    }

    /// @dev Storage slot holding the controller's delay switch (lowest byte) and
    ///      delay length (the next four bytes), packed.
    uint256 internal constant DELAY_SWITCH_SLOT = 267;

    /// @dev Length written into the simulation while the real length is unset.
    ///      Any non-zero length separates held from exempt; this number is never
    ///      printed.
    uint32 internal constant PLACEHOLDER_DELAY_LENGTH = 1;

    /// @dev What `quoteExitDelay` would return for this address once the delay
    ///      is switched on, in words. Local simulation only, never broadcast:
    ///      writes the switch on (and the placeholder length when the length is
    ///      unset) into this run's copy of the controller's storage with
    ///      `vm.store`, quotes, then writes the original word back. The quote is
    ///      used only when both getters read back the written values; otherwise
    ///      the line says it could not simulate rather than reporting a value.
    function _delayOnceSwitchedOn(ExitFeeController c, bytes32 id, address sub, address actor)
        internal
        returns (string memory)
    {
        uint32 length = c.globalDelaySeconds();
        uint32 simulated = length == 0 ? PLACEHOLDER_DELAY_LENGTH : length;
        bytes32 slot = bytes32(DELAY_SWITCH_SLOT);
        bytes32 saved = vm.load(address(c), slot);
        // Replace the switch byte and the four length bytes; keep the rest of the word.
        uint256 patched = (uint256(saved) & ~uint256(0xFFFFFFFFFF)) | (uint256(simulated) << 8) | 1;
        vm.store(address(c), slot, bytes32(patched));
        bool readBack = c.securityPerimeterEnabled() && c.globalDelaySeconds() == simulated;
        uint32 d = readBack ? c.quoteExitDelay(id, sub, actor) : 0;
        vm.store(address(c), slot, saved);

        if (!readBack) return "NOT SIMULATED - the switch and length are not at the storage slot this inspector writes";
        if (d == 0) return "exempt (0s)";
        if (length == 0) return "held (length unset - the Owner sets it before switching on)";
        return string.concat("delayed ", vm.toString(uint256(d)), "s");
    }

    /// @dev What `quoteExitFee` returns for this address on SAMPLE_GROSS, in
    ///      words: the rate and fee when charged, exempt at an active 0 bps, and
    ///      the skip reason when no fee applies.
    function _resolvedFee(ExitFeeController c, bytes32 id, address sub, address actor)
        internal
        view
        returns (string memory)
    {
        IExitFeeController.ExitFeeQuote memory q = c.quoteExitFee(id, sub, actor, SAMPLE_GROSS);
        string memory value;
        if (!q.active) value = string.concat("no fee (", _skipReasonName(q.reason), ")");
        else if (q.rateBps == 0) value = "exempt (0 bps)";
        else value = string.concat(vm.toString(uint256(q.rateBps)), " bps, fee ", vm.toString(q.feeAmount));
        return string.concat("resolves ", value, " on sample gross 1e18 for ", _resolutionLabel(sub, actor));
    }

    function _skipReasonName(uint8 reason) internal pure returns (string memory) {
        if (reason == uint8(IExitFeeController.SkipReason.INACTIVE)) return "INACTIVE: fee switch off";
        if (reason == uint8(IExitFeeController.SkipReason.DISABLED)) {
            return "DISABLED: surface off or no fee receiver";
        }
        if (reason == uint8(IExitFeeController.SkipReason.INVALID_QUOTE)) return "INVALID_QUOTE";
        return string.concat("reason ", vm.toString(uint256(reason)));
    }

    /// @dev Logs `line` and records it at `rows[n]`, so a row printer returns
    ///      exactly the lines it printed. Returns the next free index.
    function _emitRow(string[] memory rows, uint256 n, string memory line) internal pure returns (uint256) {
        console2.log(line);
        rows[n] = line;
        return n + 1;
    }

    /// @dev `a` followed by `b`.
    function _concatRows(string[] memory a, string[] memory b) internal pure returns (string[] memory out) {
        out = new string[](a.length + b.length);
        for (uint256 i = 0; i < a.length; i++) {
            out[i] = a[i];
        }
        for (uint256 i = 0; i < b.length; i++) {
            out[a.length + i] = b[i];
        }
    }

    /// @dev Prints each stored fee sub-product row with the fee it resolves to.
    ///      Returns the printed lines.
    function _printFeeSubProductRows(ExitFeeController c, bytes32 id, address[] memory subs)
        internal
        view
        returns (string[] memory rows)
    {
        if (subs.length == 0) return rows;
        rows = new string[](1 + 2 * subs.length);
        uint256 n = _emitRow(rows, 0, "  sub-products:");
        for (uint256 j = 0; j < subs.length; j++) {
            IExitFeeController.RatePolicy memory p = c.subProductPolicy(id, subs[j]);
            n = _emitRow(rows, n, string.concat("    ", vm.toString(subs[j]), "  ", _fmtPolicy(p)));
            n = _emitRow(rows, n, string.concat("      ", _resolvedFee(c, id, subs[j], address(0))));
        }
    }

    /// @dev Prints each stored fee actor row with the fee it resolves to at no
    ///      sub-product and at every stored sub-product. Returns the printed
    ///      lines.
    function _printFeeActorRows(ExitFeeController c, bytes32 id, address[] memory actors, address[] memory subs)
        internal
        view
        returns (string[] memory rows)
    {
        if (actors.length == 0) return rows;
        address[] memory at = _resolutionSubProducts(subs);
        rows = new string[](1 + actors.length * (1 + at.length));
        uint256 n = _emitRow(rows, 0, "  actors:");
        for (uint256 j = 0; j < actors.length; j++) {
            IExitFeeController.RatePolicy memory p = c.actorPolicy(id, actors[j]);
            n = _emitRow(rows, n, string.concat("    ", vm.toString(actors[j]), "  ", _fmtPolicy(p)));
            for (uint256 k = 0; k < at.length; k++) {
                n = _emitRow(rows, n, string.concat("      ", _resolvedFee(c, id, at[k], actors[j])));
            }
        }
    }

    /// @dev Prints each stored delay sub-product row with the delay it resolves
    ///      to. Returns the printed lines.
    function _printDelaySubProductRows(ExitFeeController c, bytes32 id, address[] memory subs)
        internal
        returns (string[] memory rows)
    {
        rows = new string[](2 * subs.length);
        uint256 n;
        for (uint256 j = 0; j < subs.length; j++) {
            IExitFeeController.DelayBypassPolicy memory p = c.subProductBypass(id, subs[j]);
            n = _emitRow(rows, n, string.concat("    sub-product ", vm.toString(subs[j]), "  ", _fmtBypass(p)));
            n = _emitRow(rows, n, string.concat("      ", _resolvedDelay(c, id, subs[j], address(0))));
        }
    }

    /// @dev Prints each stored delay actor row with the delay it resolves to at
    ///      no sub-product and at every stored sub-product. Returns the printed
    ///      lines.
    function _printDelayActorRows(ExitFeeController c, bytes32 id, address[] memory actors, address[] memory subs)
        internal
        returns (string[] memory rows)
    {
        address[] memory at = _resolutionSubProducts(subs);
        rows = new string[](actors.length * (1 + at.length));
        uint256 n;
        for (uint256 j = 0; j < actors.length; j++) {
            IExitFeeController.DelayBypassPolicy memory p = c.actorBypass(id, actors[j]);
            n = _emitRow(rows, n, string.concat("    actor       ", vm.toString(actors[j]), "  ", _fmtBypass(p)));
            for (uint256 k = 0; k < at.length; k++) {
                n = _emitRow(rows, n, string.concat("      ", _resolvedDelay(c, id, at[k], actors[j])));
            }
        }
    }

    /// @dev single-guardian assertion. Reads the queue proxy from its
    ///      deployment artifact (if present) and requires `controller.admin ==
    ///      queue.admin`. This is a DEPLOY/INSPECT-time identity check ONLY — the
    ///      controller never reads the queue at runtime (kill-switch
    ///      queue-independence). Skipped with a notice when the queue
    ///      artifact is absent (e.g. controller-only inspection).
    function _assertSingleGuardian(ExitFeeController c, uint256 chainId) internal view {
        string memory path = string.concat("deployments/", vm.toString(chainId), "/ExitDelayQueue.json");
        try vm.readFile(path) returns (string memory queueArtifact) {
            address queueProxy = queueArtifact.readAddress(".proxyAddress");
            address queueAdmin = ExitDelayQueue(payable(queueProxy)).admin();
            address ctrlAdmin = c.admin();
            console2.log(unicode"── Single-guardian identity ──────────────────");
            console2.log("  controller.admin:", ctrlAdmin);
            console2.log("  queue.admin:     ", queueAdmin);
            require(ctrlAdmin == queueAdmin, "controller.admin != queue.admin (single guardian violated)");
            console2.log("  OK: single guardian identity holds");
            console2.log("");
        } catch {
            console2.log(unicode"── Single-guardian identity ──────────────────");
            console2.log("  queue artifact absent -- skipping controller.admin==queue.admin check");
            console2.log("");
        }
    }

    /// @dev the complete surfaceId probe set that drives the bypass dump —
    ///        `bypassSurfaceIds()` ∪ the named surfaces.
    ///      The `bypassSurfaceIds()` master set is ANY-TIER-TOUCHED: a surface
    ///      carrying ONLY a sub-product- or actor-tier bypass is present here even
    ///      though it was never passed to `setSurfaceBypass`. The named fee surfaces
    ///      are folded in so the human-readable rows always render, and duplicates
    ///      are collapsed.
    function _probeSurfaceIds(ExitFeeController c) internal view returns (bytes32[] memory) {
        bytes32[] memory bypassIds = c.bypassSurfaceIds();

        // Upper bound on the union size; trim to the deduped count below.
        bytes32[] memory acc = new bytes32[](bypassIds.length + surfaceNames.length);
        uint256 n = 0;

        // Named fee surfaces first (stable ordering; keeps human rows at the top).
        for (uint256 i = 0; i < surfaceNames.length; i++) {
            n = _pushUnique(acc, n, keccak256(bytes(surfaceNames[i])));
        }
        for (uint256 i = 0; i < bypassIds.length; i++) {
            n = _pushUnique(acc, n, bypassIds[i]);
        }

        bytes32[] memory out = new bytes32[](n);
        for (uint256 i = 0; i < n; i++) {
            out[i] = acc[i];
        }
        return out;
    }

    /// @dev Append `id` to `acc[0..n)` iff not already present; returns the new n.
    function _pushUnique(bytes32[] memory acc, uint256 n, bytes32 id) internal pure returns (uint256) {
        for (uint256 i = 0; i < n; i++) {
            if (acc[i] == id) return n;
        }
        acc[n] = id;
        return n + 1;
    }

    /// @dev Human-readable label for a surfaceId: the canonical name if it is a
    ///      named fee surface, else the raw bytes32.
    function _labelFor(bytes32 id) internal view returns (string memory) {
        for (uint256 i = 0; i < surfaceNames.length; i++) {
            if (id == keccak256(bytes(surfaceNames[i]))) {
                return surfaceNames[i];
            }
        }
        return vm.toString(id);
    }

    /// @dev Is `id` in the surface-bypass key index? A soft-retired surface
    ///      entry ({false,false}) is indistinguishable from never-set by its
    ///      policy alone; the key set is the source of truth for presence.
    function _surfaceBypassKeyPresent(ExitFeeController c, bytes32 id) internal view returns (bool) {
        bytes32[] memory keys = c.surfaceBypassKeys();
        for (uint256 i = 0; i < keys.length; i++) {
            if (keys[i] == id) return true;
        }
        return false;
    }

    /// @dev dump every surface / sub-product / actor delay-bypass
    ///      entry, driven by the ANY-TIER-TOUCHED probe set (`bypassSurfaceIds()` ∪
    ///      named surfaces) so a sub-product- or
    ///      actor-only bypass under an arbitrary surfaceId is never missed. A probed
    ///      surfaceId with no live bypass entry at any tier prints nothing.
    ///      Returns the stored-row lines it printed: every sub-product and actor
    ///      row with its resolved lines, in print order.
    function _printDelayBypassRegistry(ExitFeeController c) internal returns (string[] memory rows) {
        console2.log(unicode"── Delay-bypass registry (enumerated) ────────────────");
        bytes32[] memory ids = _probeSurfaceIds(c);
        bool anyPrinted = false;
        for (uint256 i = 0; i < ids.length; i++) {
            bytes32 id = ids[i];

            IExitFeeController.DelayBypassPolicy memory sb = c.surfaceBypass(id);
            address[] memory subBp = c.subProductBypassKeys(id);
            address[] memory actorBp = c.actorBypassKeys(id);
            // A surface-tier entry set then soft-retired reads {false,false} but
            // still lives in the key index; it must stay visible, since the
            // documented way to disable-while-auditable is exactly that state.
            bool surfaceEntryPresent = _surfaceBypassKeyPresent(c, id);

            // Skip a probed id that carries no bypass entry at any tier (e.g. a
            // named fee surface never given one).
            if (!surfaceEntryPresent && subBp.length == 0 && actorBp.length == 0) {
                continue;
            }
            anyPrinted = true;

            console2.log(string.concat("  surface ", _labelFor(id), "  ", _fmtBypass(sb)));
            // Beside each stored row, the delay that resolves for that address.
            // Sub-product rows print before actor rows.
            string[] memory subRows = _printDelaySubProductRows(c, id, subBp);
            string[] memory actorRows = _printDelayActorRows(c, id, actorBp, subBp);
            rows = _concatRows(rows, _concatRows(subRows, actorRows));
        }
        if (!anyPrinted) {
            console2.log("  (no delay bypasses configured at any tier)");
        }
        console2.log("");
    }



    /// @dev Prints one named surface: its id, its policy, and every stored
    ///      sub-product and actor row with the fee each resolves to. Returns the
    ///      stored-row lines it printed, sub-product rows first.
    function _printSurface(ExitFeeController c, string memory name) internal view returns (string[] memory rows) {
        bytes32 id = keccak256(bytes(name));

        console2.log(name);
        console2.log("  id:     ", vm.toString(id));

        IExitFeeController.RatePolicy memory sp = c.surfacePolicy(id);
        console2.log(string.concat("  policy: ", _fmtPolicy(sp)));

        // Beside each stored row, the fee that resolves for that address.
        // Sub-product rows print before actor rows.
        address[] memory subs = c.subProductKeys(id);
        string[] memory subRows = _printFeeSubProductRows(c, id, subs);
        string[] memory actorRows = _printFeeActorRows(c, id, c.actorKeys(id), subs);
        rows = _concatRows(subRows, actorRows);
        // NOTE: delay-bypass tiers are dumped separately in
        // `_printDelayBypassRegistry`, driven by the ANY-TIER-TOUCHED master set
        // `bypassSurfaceIds()` ∪ the named surfaces (NOT this hardcoded surface
        // list, and NOT the surface-tier-only `surfaceBypassKeys()`). Because that
        // master set is recorded by EVERY bypass writer (surface / sub-product /
        // actor), an entry under an arbitrary surfaceId — including a sub-product-
        // or actor-ONLY bypass — is discovered there.
        console2.log("");
    }

    function _fmtPolicy(IExitFeeController.RatePolicy memory p) internal pure returns (string memory) {
        return string.concat(
            "(active=", p.active ? "true" : "false", ", rateBps=", vm.toString(uint256(p.rateBps)), ")"
        );
    }

    function _fmtBypass(IExitFeeController.DelayBypassPolicy memory p)
        internal
        pure
        returns (string memory)
    {
        return string.concat(
            "(active=", p.active ? "true" : "false", ", bypass=", p.bypass ? "true" : "false", ")"
        );
    }
}

