// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from
    "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import {IExitDelayQueue} from "./interfaces/IExitDelayQueue.sol";

/// @notice Minimal WRBTC (wrapped-RBTC) surface. `unwrapOnDelivery` requests
///         hold WRBTC and unwrap to native RBTC at `executeExit`.
interface IWRBTC {
    function withdraw(uint256 amount) external;
}

/// @title  ExitDelayQueue
/// @notice Per-request escrow for the *user* leg of an exit. Each exit becomes
///         an immutable request with its own monotonic id; execution targets
///         explicit ids (no cursor, no ordering assumption). During the delay,
///         a detected theft can be Frozen/Blacklisted and disposed via the
///         three recovery legs. UUPS-upgradeable, mirroring the
///         `ExitFeeVault` skeleton.
///
///         Authoritative build spec:
///         The invariants are enumerated with the properties below and
///         pinned by the forge invariant suite.
///
///         Two-principal authority: `Owner` (Ownable2Step) holds UUPS
///         upgrade + all security-critical CONFIG; `Admin` (a single stored
///         address, `onlyAdminOrOwner`) is the fast guardian — freeze/blacklist,
///         pause, Leg-1 release, Leg-2 along Owner-approved routes. The two roles
///         MAY be the same address; the authority split constrains the Admin only
///         once ownership moves to a separate holder.
//
// The queue custodies escrowed RBTC/ERC20/WRBTC by design; the only value-in
// path is the gated ingress (record*/receive()), and value-out is CEI-ordered
// behind nonReentrant. aderyn's "contract-locks-ether" is intentional here.
// aderyn-ignore-next-line(contract-locks-ether)
contract ExitDelayQueue is
    IExitDelayQueue,
    Initializable,
    UUPSUpgradeable,
    Ownable2StepUpgradeable,
    ReentrancyGuardUpgradeable
{
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.UintSet;
    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.Bytes32Set;

    // ─── Storage layout ──────────────────────────────────────────
    // Verified via `forge inspect ExitDelayQueue storageLayout`. Inherited-OZ
    // namespaces occupy proxy slots 0..300 (Initializable/Context/Ownable/
    // Ownable2Step/ReentrancyGuard, each with a 50-slot __gap; UUPS/Context add
    // no fields). This contract's own slot 0 sits at proxy slot 301:
    //
    //   301  admin (address; the Admin guardian — 1 slot, no OZ AccessControl)
    //   302  lastRequestId (uint256)
    //   303  _requests (mapping head)
    //   304  _activeByParty (mapping head)
    //   305  _recoveryRoutes (mapping head)
    //   306  _recoveryRouteIds._values (Bytes32Set array head)   ┐ 2 slots
    //   307  _recoveryRouteIds._indexes (mapping head)           ┘
    //   308  _topUpFeasible (mapping head)
    //   309  _blockState (mapping head)
    //   310  _blockedAccounts._values (AddressSet array head)    ┐ 2 slots
    //   311  _blockedAccounts._indexes (mapping head)            ┘
    //   312  _blockTrigger (mapping head)
    //   313  _allowedSource (mapping head)
    //   314  _allowedSources._values (AddressSet array head)     ┐ 2 slots
    //   315  _allowedSources._indexes (mapping head)             ┘
    //   316  _totalEscrowed (mapping head)
    //   317  nativePusher (address)         ┐ address(20) + uint32(4) + bool(1)
    //        minimumDelaySeconds (uint32)   │ = 25 bytes → PACKED into one slot
    //        securityPerimeterPaused (bool) ┘
    //   318  wrbtc (address; canonical WRBTC — own slot)
    //   319 .. 350  __gap[32]  (50 − 18 own slots)
    //
    // own_slots = 18 (admin, lastRequestId, 8 mapping heads, 3 EnumerableSet ×2,
    // the packed nativePusher+minimumDelaySeconds+securityPerimeterPaused slot,
    // and wrbtc). __gap = 50 − 18 = 32. Re-derive at build time with
    // `forge inspect ExitDelayQueue storageLayout` before any deployment and
    // set __gap accordingly. Upgrades adding storage MUST consume from __gap.
    //
    // A bouncing honest recipient is handled self-service by the
    // {originator, owner, receiver} set via the dedicated
    // recoverStuckExit(id, altReceiver) leg — which attempts the STORED
    // receiver FIRST and pays altReceiver if that attempt fails, including
    // insufficient gas for the receiver. There is no stored
    // failure flag, no Admin/Owner recovery path, and no request re-targeting.
    // The all-four-actor block gate covers the STORED receiver so a blocked
    // original receiver refuses recovery and falls to Leg-3.

    /// @notice Fast operational guardian. Not an OZ AccessControl role —
    ///         a single stored address checked by `onlyAdminOrOwner`. MAY equal
    ///         the Owner; the authority bounds between the two roles bind only
    ///         once ownership moves to a separate holder.
    address public admin;

    /// @notice Monotonic id source; ids are never reused. The first
    ///         recorded id is 1 (0 is reserved as "no request" / arbitrary block).
    uint256 public lastRequestId;

    mapping(uint256 => ExitRequest) internal _requests;

    /// @dev Recorded party (originator, owner, receiver) → status==Queued
    ///      request ids. A freeze HOLDS but does not remove (Frozen is an
    ///      address state, not a request status). Keyed by up to three
    ///      addresses; EnumerableSet dedups when any of them coincide. No
    ///      on-chain path iterates the full set — only O(1) add/remove and the
    ///      paginated `getActive` view touch it.
    mapping(address => EnumerableSet.UintSet) internal _activeByParty;

    mapping(bytes32 => RecoveryRoute) internal _recoveryRoutes;
    EnumerableSet.Bytes32Set internal _recoveryRouteIds;

    /// @dev surfaceId → may a topUpPool=true route be registered? Owner-set;
    ///      true only for lending-lender/borrower surfaces at launch.
    mapping(bytes32 => bool) internal _topUpFeasible;

    /// @dev Execution & recovery treat Frozen and Blacklisted alike as "blocked";
    ///      recovery-away distinguishes them.
    mapping(address => BlockState) internal _blockState;
    EnumerableSet.AddressSet internal _blockedAccounts; // Frozen ∪ Blacklisted, for getters

    /// @dev addr → exit-request id that triggered the block (0 = arbitrary block).
    mapping(address => uint256) internal _blockTrigger;

    mapping(address => bool) internal _allowedSource;
    EnumerableSet.AddressSet internal _allowedSources;

    /// @dev token => Σ amounts of Queued requests (solvency).
    ///      address(0) = native RBTC. Exposed via the `totalEscrowed(address)`
    ///      view (not a public auto-getter so the interface signature is exact).
    mapping(address => uint256) internal _totalEscrowed;

    /// @notice The single registered native pusher (Zero `ActivePool`), Owner-set.
    ///         NOTE: `receive()` is now UNCONDITIONAL and no longer reads
    ///         this slot — the pusher is no longer a `receive()`-time gate. The
    ///         field + setter are RETAINED (unchanged ABI/packing, so `__gap`
    ///         stays 32) as documented provenance of the intended native source;
    ///         `_allowedSource` still gates the record CALLER at ingress.
    address public nativePusher;

    /// @notice F1 floor enforced PER-REQUEST at ingress. Packs with
    ///         nativePusher + securityPerimeterPaused.
    uint32 public minimumDelaySeconds;

    /// @notice While true, the queue pays nobody through the user-facing legs:
    ///         `executeExit`, `executeExits` and `recoverStuckExit` revert
    ///         `QueuePaused` for every caller — originator, owner, receiver, and
    ///         anyone delivering a contract-owned request. Users therefore have no path
    ///         of their own while it holds.
    ///         What stays live: ingress (the four `record*` functions and
    ///         `receive`), so withdrawals keep escrowing; the block levers; the
    ///         Admin-or-Owner `resolveToProtocol`, which still needs a
    ///         blacklisted originator or owner and a matching active route; and
    ///         the Owner's `resolveByOwner`, which reaches only requests with a
    ///         blacklisted party, paused or not. Owner configuration and
    ///         `sweepSurplus` are unaffected.
    ///         Packs with nativePusher (address) + minimumDelaySeconds (uint32).
    bool public securityPerimeterPaused;

    /// @notice Canonical WRBTC address. Set at initialize; used only to
    ///         guard the `unwrapOnDelivery` flag and to unwrap at delivery. A
    ///         full own slot (slot 318 in the layout note above), so __gap is
    ///         50 − 18 = 32. Re-derive via `forge inspect` before deployment.
    address public wrbtc;

    // aderyn-ignore-next-line(unused-state-variable)
    uint256[32] private __gap;

    /// @notice Max page size for the paginated `getActive` / `blockedAccounts`
    ///         views. Public so paging is
    ///         self-describing on-chain — a caller can read the cap instead of
    ///         hard-coding 500 and discovering the clamp empirically.
    uint256 public constant MAX_GET_ACTIVE_PAGE = 500;

    // ─── Modifiers ──────────────────────────────────────────────────────

    modifier onlyAdminOrOwner() {
        if (msg.sender != admin && msg.sender != owner()) revert NotAdminOrOwner(msg.sender);
        _;
    }

    modifier onlyAllowedSource() {
        if (!_allowedSource[msg.sender]) revert UnregisteredSource(msg.sender);
        _;
    }

    // ─── Construction / initialization ──────────────────────────────────

    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the proxy. Deployer becomes the initial Owner; the
    ///         bootstrap flow then `transferOwnership` → the Owner.
    /// @param owner_ Owner principal (0 or msg.sender ⇒ deployer stays owner).
    /// @param admin_ Fast guardian; non-zero. MAY equal the owner (
    ///        deliberate: launch shape is admin = owner, both held by one
    ///        Safe; the split becomes a real authority bound only when
    ///        ownership later moves to Bitocracy).
    /// @param wrbtc_ Canonical WRBTC token. Must be non-zero.
    /// @param minimumDelaySeconds_ Per-request delay floor.
    /// @param initialAllowedSources Hooked source contracts.
    function initialize(
        address owner_,
        address admin_,
        address wrbtc_,
        uint32 minimumDelaySeconds_,
        address[] calldata initialAllowedSources
    ) external initializer {
        __Ownable_init();
        __Ownable2Step_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        if (wrbtc_ == address(0) || admin_ == address(0)) revert ZeroAddress();
        wrbtc = wrbtc_;

        admin = admin_;

        minimumDelaySeconds = minimumDelaySeconds_;

        for (uint256 i = 0; i < initialAllowedSources.length; ++i) {
            address src = initialAllowedSources[i];
            if (src == address(0)) revert ZeroAddress();
            if (_allowedSources.add(src)) {
                _allowedSource[src] = true;
                emit AllowedSourceSet(src, true);
            }
        }

        if (owner_ != address(0) && owner_ != msg.sender) {
            _transferOwnership(owner_);
        }
    }

    // ─── Ingress ──────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    function recordERC20Exit(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver,
        bool unwrapOnDelivery
    ) external nonReentrant onlyAllowedSource returns (uint256 id) {
        //  guard: the delivery-time unwrap can only be set on WRBTC escrow.
        if (unwrapOnDelivery && token != wrbtc) revert UnwrapNonWrbtc();
        _validateIngress(token, amount, delaySeconds, effOrig, effOwner, receiver, unwrapOnDelivery);

        // ERC20 pull with receipt proof: measure before/after so a
        // fee-on-transfer/rebasing token cannot silently mis-escrow.
        uint256 before = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = IERC20(token).balanceOf(address(this)) - before;
        if (received != amount) revert ReceivedAmountMismatch(token, received, amount);

        id = _record(
            token, amount, delaySeconds, surfaceId, subProduct, effOrig, effOwner, receiver, unwrapOnDelivery
        );
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Measured-delta path (0.5.x): the source pushes `amount` and records
    ///      in the SAME outer tx. We measure the current non-backing surplus
    ///      `delta = balanceOf − totalEscrowed` and require `delta >= amount`:
    ///      the record CONSUMES exactly `amount` into
    ///      totalEscrowed; any excess (pre-existing dust, a force-sent/donated
    ///      1-wei, another source's surplus) stays as non-backing surplus for
    ///      sweepSurplus and is NEVER mis-credited. Because push and record are
    ///      atomic in one outer tx, there is no interleaved-push residual to
    ///      protect against, and a donation only RAISES the surplus, so
    ///      `>= amount` still passes.
    function recordReceivedERC20Exit(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external nonReentrant onlyAllowedSource returns (uint256 id) {
        _validateIngress(token, amount, delaySeconds, effOrig, effOwner, receiver, false);

        // Non-backing surplus = (current backing balance) − (already-escrowed).
        // Require it covers `amount` (delta >= amount). Revert only when
        // the push under-delivered (delta < amount ⇒ ReceivedAmountMismatch).
        // Excess over `amount` is left as sweepable surplus (never mis-credited).
        uint256 backing = IERC20(token).balanceOf(address(this));
        uint256 escrowed = _totalEscrowed[token];
        uint256 delta = backing > escrowed ? backing - escrowed : 0;
        if (delta < amount) revert ReceivedAmountMismatch(token, delta, amount);

        id = _record(token, amount, delaySeconds, surfaceId, subProduct, effOrig, effOwner, receiver, false);
    }

    /// @inheritdoc IExitDelayQueue
    function recordNativeExit(
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external payable nonReentrant onlyAllowedSource returns (uint256 id) {
        if (msg.value != amount) revert AmountMismatch(msg.value, amount);
        _validateIngress(address(0), amount, delaySeconds, effOrig, effOwner, receiver, false);
        id = _record(
            address(0), amount, delaySeconds, surfaceId, subProduct, effOrig, effOwner, receiver, false
        );
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Native measured-receipt (Zero): `ActivePool.sendETH(queue, amount)`
    ///      pushes value (via `receive()`) BEFORE this record in the same outer
    ///      tx; a record revert rolls the push back (fail-closed). Same
    ///       rule as the ERC20 measured path: require the non-backing
    ///      surplus `delta >= amount` and credit exactly `amount`. The
    ///      `receive()` gate cannot stop a `selfdestruct` force-send, which is
    ///      exactly why crediting must tolerate surplus (`>= amount`) rather than
    ///      require an exact balance — a force-sent 1-wei must not
    ///      permanently brick every subsequent Zero exit record.
    function recordReceivedNativeExit(
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external nonReentrant onlyAllowedSource returns (uint256 id) {
        _validateIngress(address(0), amount, delaySeconds, effOrig, effOwner, receiver, false);
        uint256 backing = address(this).balance;
        uint256 escrowed = _totalEscrowed[address(0)];
        uint256 delta = backing > escrowed ? backing - escrowed : 0;
        if (delta < amount) revert ReceivedAmountMismatch(address(0), delta, amount);
        id = _record(
            address(0), amount, delaySeconds, surfaceId, subProduct, effOrig, effOwner, receiver, false
        );
    }

    /// @notice UNCONDITIONAL native-RBTC sink. Accepts
    ///         native from ANYONE with **no storage reads and no sender gate**.
    ///
    ///         Why unconditional: the real Rootstock WRBTC `withdraw()` returns
    ///         native via a 2300-gas `transfer` stipend. Any storage-slot sender
    ///         check here (SLOAD ≥ 2100 cold under EIP-2929/Paris) exceeds that
    ///         stipend, so a sender-gated `receive()` would `OutOfGas`-brick every
    ///         `unwrapOnDelivery` (native `burnToBTC`) payout after unlock —
    ///         pinned by `ExitDelayQueueUnwrapStipend`. Accepting unconditionally
    ///         is safe because the measured-receipt ingress paths already
    ///         neutralize stray or donated native: they credit EXACTLY `amount`
    ///         when the non-backing surplus is `>= amount` and never mis-credit,
    ///         so unsolicited RBTC — including a `selfdestruct` force-send, which
    ///         no sender gate could stop either — only accrues as
    ///         `sweepSurplus`-able surplus. The queue does not need to assert
    ///         "only ActivePool pays in native": the measured-receipt credit is
    ///         defense enough against stray native on its own.
    receive() external payable virtual {}

    // ─── Ingress helpers ────────────────────────────────────────────────

    function _validateIngress(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        address effOrig,
        address effOwner,
        address receiver,
        bool unwrapOnDelivery
    ) internal view {
        if (amount == 0) revert ZeroAmount();
        // AmountTooLarge: the record* ABI takes `amount` as uint128
        // deliberately (keeps ExitRequest word-1 packing). The uint256→
        // uint128 narrowing therefore happens in the CALLER (the Perimeter hook /
        // 0.5.x product host), which MUST `require(userAmount <= type(uint128).max)
        // else AmountTooLarge` BEFORE narrowing — that check is the live
        // queue-boundary guard, in the caller's pragma, against silent truncation
        // (IExitDelayQueue NatSpec). The queue re-asserting it on an already-
        // uint128 arg would be a compile-time tautology, so the guard is kept at
        // the boundary where a uint256 actually exists, not duplicated as dead code
        // here. We still reject a below-floor delay and zero-address parties.
        if (delaySeconds < minimumDelaySeconds) revert DelayBelowFloor(delaySeconds, minimumDelaySeconds);
        if (effOrig == address(0) || effOwner == address(0) || receiver == address(0)) revert ZeroAddress();
        // A receiver delivery cannot actually pay. Paying this queue sends the
        // money straight back in; WRBTC credits native RBTC to its sender - this
        // queue - as wrapped tokens. Either way delivery would mark the request
        // Executed while the money stayed here as surplus. WRBTC paid as a token,
        // without unwrapping, sends no native RBTC and is not refused.
        if (receiver == address(this)) revert InvalidReceiver(receiver);
        if (receiver == wrbtc && (token == address(0) || unwrapOnDelivery)) revert InvalidReceiver(receiver);
    }

    function _record(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver,
        bool unwrapOnDelivery
    ) internal returns (uint256 id) {
        id = ++lastRequestId;

        // Write field-by-field into storage to keep the stack shallow (a struct
        // literal with 11 members + the 9-arg event blows the 0.8.20 stack
        // without via-ir; this repo pins non-via-ir to match the deployed
        // Perimeter bytecode profile).
        ExitRequest storage r = _requests[id];
        r.amount = amount;
        r.createdAt = uint64(block.timestamp);
        r.unlockAt = uint64(block.timestamp + delaySeconds);
        r.originator = effOrig;
        r.owner = effOwner;
        r.receiver = receiver;
        r.token = token;
        r.surfaceId = surfaceId;
        r.subProduct = subProduct;
        r.status = ExitStatus.Queued;
        r.unwrapOnDelivery = unwrapOnDelivery;

        // Triple-key insert; EnumerableSet dedups when any of the three coincide.
        _activeByParty[effOrig].add(id);
        _activeByParty[effOwner].add(id);
        _activeByParty[receiver].add(id);

        _totalEscrowed[token] += amount;

        emit ExitQueued(id, effOrig, effOwner, receiver, token, amount, r.unlockAt, surfaceId, subProduct);
    }

    // ─── Execution ───────────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    /// @dev Pays the request's immutable `receiver`. A reverting receiver rolls
    ///      the whole call back (fail-closed) — the request stays Queued and
    ///      the rightful parties retry via `executeExit` (once the recipient is
    ///      fixed) or `recoverStuckExit` (redirect leg). No redirect here.
    function executeExit(uint256 requestId) external nonReentrant {
        _executeOne(requestId);
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Strict array order; atomic (any revert rolls the whole batch back).
    ///      A duplicate id flips to Executed on the first pass, then
    ///      hits AlreadyTerminal on the second — never double-pays. Always pays
    ///      the immutable receiver (no redirect in the batch path).
    function executeExits(uint256[] calldata ids) external nonReentrant {
        if (ids.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < ids.length; ++i) {
            _executeOne(ids[i]);
        }
    }

    /// @dev Shared execution core — always pays the immutable `receiver`.
    ///      Who may deliver: the originator, the owner or the receiver; and,
    ///      when the owner is a contract, anyone — a contract owner cannot
    ///      press the button itself, and delivery goes only to the receiver
    ///      fixed at escrow time, so widening the executor set adds no
    ///      destination. Block gate covers the executor and
    ///      `{originator, owner, receiver}`. CEI: terminal status + escrow
    ///      decrement + set removal ALL before the external transfer
    ///      (`nonReentrant`).
    function _executeOne(uint256 requestId) internal {
        if (securityPerimeterPaused) revert QueuePaused();
        ExitRequest storage r = _requests[requestId];
        if (r.status == ExitStatus.None) revert UnknownRequest(requestId);
        if (r.status != ExitStatus.Queued) revert AlreadyTerminal(requestId);
        if (block.timestamp < r.unlockAt) revert NotUnlocked(requestId, r.unlockAt);
        bool party = msg.sender == r.originator || msg.sender == r.owner || msg.sender == r.receiver;
        if (!party && r.owner.code.length == 0) revert NotExecutor(msg.sender);

        _requireNotBlocked(r.originator);
        _requireNotBlocked(r.owner);
        _requireNotBlocked(r.receiver);
        // The executor last: for a party this repeats a check above; for
        // anyone else it is the only one that names them.
        if (!party) _requireNotBlocked(msg.sender);

        address token = r.token;
        uint128 amount = r.amount;
        address receiver = r.receiver;
        bool unwrap = r.unwrapOnDelivery;

        r.status = ExitStatus.Executed;
        _removeActive(requestId, r.originator, r.owner, receiver);
        _totalEscrowed[token] -= amount;

        emit ExitExecuted(requestId, receiver, token, amount);
        _payout(token, receiver, amount, unwrap);
        _requireSolventAfterPayout(token, unwrap);
    }

    // ─── Stuck-exit recovery — verify-by-attempting redirect leg ──

    /// @inheritdoc IExitDelayQueue
    /// @dev A bouncing honest recipient is not a perimeter-specific problem (the
    ///      same withdrawal would bounce without the delay), so recovery is
    ///      SELF-SERVICE by the `{originator, owner, receiver}` set — no
    ///      Admin/Owner path, no stored failure flag, and the stored request is
    ///      NEVER re-targeted (`altReceiver` is a payout-time destination only).
    ///
    ///      VERIFY-BY-ATTEMPTING: after CEI (status → Executed, escrow decremented,
    ///      sets pruned), the STORED-receiver payout is attempted FIRST. If it
    ///      SUCCEEDS, that is the payout and `altReceiver` is unused. A failed
    ///      attempt, including a receiver out-of-gas, falls through to
    ///      `altReceiver`; if `altReceiver` also fails, the whole
    ///      call reverts and the funds stay Queued (CEI rollback).
    ///
    ///      ALL-FOUR-ACTOR block gate: none of `{originator, owner, STORED
    ///      receiver, altReceiver}` may be Frozen/Blacklisted. Gating the STORED
    ///      receiver means a blocked/hacked original receiver refuses recovery
    ///      entirely (this leg can never move its funds) and falls to Leg-3
    ///      instead of reaching a receiver-only dead end. `altReceiver` is
    ///      guarded: not 0/this/token/wrbtc.
    function recoverStuckExit(uint256 id, address altReceiver) external nonReentrant {
        if (securityPerimeterPaused) revert QueuePaused();
        ExitRequest storage r = _requests[id];
        if (r.status == ExitStatus.None) revert UnknownRequest(id);
        if (r.status != ExitStatus.Queued) revert AlreadyTerminal(id);
        if (block.timestamp < r.unlockAt) revert NotUnlocked(id, r.unlockAt);
        address token = r.token;
        address receiver = r.receiver;
        // The three parties to the request may recover it; a receiver that
        // cannot accept the payout but can act may point it elsewhere itself.
        if (msg.sender != r.originator && msg.sender != r.owner && msg.sender != receiver) {
            revert NotExecutor(msg.sender);
        }

        // altReceiver guard: a payout-time destination, never the zero
        // address, this contract (would trap escrow), the escrowed token, or WRBTC
        // (a wrapped-token destination would silently swallow an unwrap payout).
        if (
            altReceiver == address(0) || altReceiver == address(this) || altReceiver == token
                || altReceiver == wrbtc
        ) revert InvalidAltReceiver(altReceiver);

        // All-four-actor block gate: originator, owner, the STORED receiver,
        // and altReceiver must all be unblocked. Gating the STORED receiver means a
        // blocked/hacked original receiver refuses recovery here (→ Leg-3).
        _requireNotBlocked(r.originator);
        _requireNotBlocked(r.owner);
        _requireNotBlocked(receiver);
        _requireNotBlocked(altReceiver);

        // CEI: terminal status + escrow decrement + set removal BEFORE
        // any external transfer, so a failed attempt or reentry cannot double-spend.
        uint128 amount = r.amount;
        bool unwrap = r.unwrapOnDelivery;

        r.status = ExitStatus.Executed;
        _removeActive(id, r.originator, r.owner, receiver);
        _totalEscrowed[token] -= amount;

        // Attempt the STORED-receiver payout first. A successful attempt never
        // uses altReceiver; a failed attempt, including out-of-gas, falls through
        // to altReceiver — tracked by an explicit
        // bool, NOT an address compare, so a request whose stored receiver equals
        // altReceiver is paid exactly ONCE.
        address paid;
        if (_tryPayout(token, receiver, amount, unwrap)) {
            paid = receiver;
        } else {
            // Original bounced — pay altReceiver; if THIS also fails, the whole call
            // reverts (CEI rollback leaves the request Queued).
            _payout(token, altReceiver, amount, unwrap);
            paid = altReceiver;
        }
        // Outside the try/catch above on purpose: a solvency failure must end
        // the call, not be mistaken for the stored receiver bouncing.
        _requireSolventAfterPayout(token, unwrap);
        emit ExitExecuted(id, paid, token, amount);
    }

    /// @dev Catchable single-payout attempt for `recoverStuckExit`. Routes the
    ///      transfer through an EXTERNAL self-call so a reverting recipient is
    ///      caught (Solidity cannot catch a low-level revert inline) and the leg
    ///      can fall through to `altReceiver`. Returns false on a bounce.
    ///      Self-only (`msg.sender == address(this)`); NOT `nonReentrant` — it runs
    ///      inside `recoverStuckExit`'s guard, and CEI already made the state safe.
    ///
    ///      The attempt is given the gas the transaction carries: the caller's
    ///      gas limit is the budget. An underfunded attempt can redirect a
    ///      receiver that would accept payment with more gas. The EVM forwards
    ///      at most 63/64 of what remains, so a
    ///      receiver that consumes everything it is given still leaves the
    ///      1/64 that pays `altReceiver`, provided the caller supplied enough
    ///      for both; a caller who did not sees the whole call revert.
    function _tryPayout(address token, address to, uint128 amount, bool unwrap) internal returns (bool) {
        try this.payoutExternal(token, to, amount, unwrap) {
            return true;
        } catch {
            return false;
        }
    }

    /// @notice Internal payout trampoline — only callable by the contract itself
    ///         (via `_tryPayout`). Reverts on a bouncing recipient so the caller's
    ///         try/catch can fall through. Not part of the external ABI surface for
    ///         any other caller (the `SelfOnly` guard makes a direct call revert).
    function payoutExternal(address token, address to, uint128 amount, bool unwrap) external {
        if (msg.sender != address(this)) revert SelfOnly();
        _payout(token, to, amount, unwrap);
    }

    // ─── Block model ──────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    function freezeFromRequest(uint256 requestId, bool freezeReceiver, bytes32 reasonHash)
        external
        onlyAdminOrOwner
    {
        _blockFromRequest(requestId, freezeReceiver, reasonHash, BlockState.Frozen);
    }

    /// @inheritdoc IExitDelayQueue
    function blacklistFromRequest(uint256 requestId, bool freezeReceiver, bytes32 reasonHash)
        external
        onlyAdminOrOwner
    {
        _blockFromRequest(requestId, freezeReceiver, reasonHash, BlockState.Blacklisted);
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Batch by-request-id. Resolves each
    ///      request's `{originator, owner}` (+ `receiver` if `freezeReceiver`) and
    ///      blocks all in ONE tx. Whole-batch ATOMIC: one unknown id reverts the
    ///      whole batch (like `executeExits`). Last-write-wins trigger/reason per
    ///       The emergency speed lever: block every owner + delegate behind a
    ///      set of known-malicious requests in a single Admin-multisig call.
    function freezeFromRequest(uint256[] calldata requestIds, bool freezeReceiver, bytes32 reasonHash)
        external
        onlyAdminOrOwner
    {
        if (requestIds.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < requestIds.length; ++i) {
            _blockFromRequest(requestIds[i], freezeReceiver, reasonHash, BlockState.Frozen);
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Batch by-request-id blacklist. Same atomicity + last-write-
    ///      wins semantics as the batch freeze above; a Frozen→Blacklisted
    ///      escalation within a batch is handled by `_setBlock`.
    function blacklistFromRequest(uint256[] calldata requestIds, bool freezeReceiver, bytes32 reasonHash)
        external
        onlyAdminOrOwner
    {
        if (requestIds.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < requestIds.length; ++i) {
            _blockFromRequest(requestIds[i], freezeReceiver, reasonHash, BlockState.Blacklisted);
        }
    }

    function _blockFromRequest(uint256 requestId, bool freezeReceiver, bytes32 reasonHash, BlockState to)
        internal
    {
        ExitRequest storage r = _requests[requestId];
        if (r.status == ExitStatus.None) revert UnknownRequest(requestId);
        // originator always; owner too iff distinct; receiver only if flagged.
        _setBlock(r.originator, to, requestId, reasonHash);
        if (r.owner != r.originator) _setBlock(r.owner, to, requestId, reasonHash);
        if (freezeReceiver) _setBlock(r.receiver, to, requestId, reasonHash);
    }

    /// @inheritdoc IExitDelayQueue
    function freeze(address a) external onlyAdminOrOwner {
        _setBlock(a, BlockState.Frozen, 0, bytes32(0));
    }

    /// @inheritdoc IExitDelayQueue
    function blacklist(address a) external onlyAdminOrOwner {
        _setBlock(a, BlockState.Blacklisted, 0, bytes32(0));
    }

    /// @inheritdoc IExitDelayQueue
    function unfreeze(address a) external onlyAdminOrOwner {
        _clearBlock(a, BlockState.Frozen);
    }

    /// @inheritdoc IExitDelayQueue
    function unblacklist(address a) external onlyAdminOrOwner {
        _clearBlock(a, BlockState.Blacklisted);
    }

    /// @inheritdoc IExitDelayQueue
    function downgradeToFrozen(address a) external onlyAdminOrOwner {
        _downgradeToFrozen(a);
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev EmptyIds guard: an empty array is a caller mistake, not a
    ///      silent no-op — for consistency with the by-id batch variants.
    function freeze(address[] calldata a) external onlyAdminOrOwner {
        if (a.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < a.length; ++i) {
            _setBlock(a[i], BlockState.Frozen, 0, bytes32(0));
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev EmptyIds guard.
    function blacklist(address[] calldata a) external onlyAdminOrOwner {
        if (a.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < a.length; ++i) {
            _setBlock(a[i], BlockState.Blacklisted, 0, bytes32(0));
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev EmptyIds guard.
    function unfreeze(address[] calldata a) external onlyAdminOrOwner {
        if (a.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < a.length; ++i) {
            _clearBlock(a[i], BlockState.Frozen);
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev EmptyIds guard.
    function unblacklist(address[] calldata a) external onlyAdminOrOwner {
        if (a.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < a.length; ++i) {
            _clearBlock(a[i], BlockState.Blacklisted);
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev EmptyIds guard. Atomic like every other batch here: one address that
    ///      is not Blacklisted refuses the whole call.
    function downgradeToFrozen(address[] calldata a) external onlyAdminOrOwner {
        if (a.length == 0) revert EmptyIds();
        for (uint256 i = 0; i < a.length; ++i) {
            _downgradeToFrozen(a[i]);
        }
    }

    /// @dev Set (or escalate) a block. Frozen→Blacklisted is atomic (no unfreeze
    ///      first). Re-block on an already-`to` state is a state no-op.
    ///
    ///      Evidence rule. `_blockTrigger` is the only on-chain link from a
    ///      blocked address back to the request that explains it, and the flat
    ///      levers (`freeze(address)` / `blacklist(address)` and their batches)
    ///      carry none — they pass triggerId 0 and reason 0. So the trigger is
    ///      written only by a call that carries evidence, or by the first block on
    ///      a previously-unblocked address. A responder re-running a flat sweep
    ///      over addresses already blocked by request id therefore cannot erase
    ///      what the by-request pass recorded.
    ///
    ///      The event announces the trigger that HOLDS after the call, not the one
    ///      the call passed, so `blockTrigger` is reconstructible from the log
    ///      alone.
    ///
    ///      No Blacklisted → Frozen downgrade here: a blacklist is the strongest
    ///      state and is weakened only by the explicit `downgradeToFrozen` or by
    ///      `unblacklist`. An evidence-carrying freeze over a blacklisted address
    ///      holds that state and records its evidence — which keeps the by-request
    ///      emergency lever unconditional on a known id. An evidence-FREE freeze
    ///      there would change nothing and record nothing, so it reverts rather
    ///      than returning a success an operator reads as "now frozen".
    function _setBlock(address a, BlockState to, uint256 triggerId, bytes32 reasonHash) internal {
        if (a == address(0)) revert ZeroAddress();
        BlockState from = _blockState[a];
        bool carriesEvidence = triggerId != 0 || reasonHash != bytes32(0);

        if (to == BlockState.Frozen && from == BlockState.Blacklisted) {
            if (!carriesEvidence) revert AlreadyBlacklisted(a);
            _blockTrigger[a] = triggerId;
            emit AccountBlocked(a, from, triggerId, reasonHash);
            return;
        }
        if (from == BlockState.None) {
            _blockedAccounts.add(a);
        }
        _blockState[a] = to;
        uint256 trigger = _blockTrigger[a];
        if (carriesEvidence || from == BlockState.None) {
            trigger = triggerId;
            _blockTrigger[a] = triggerId;
        }
        emit AccountBlocked(a, to, trigger, reasonHash);
    }

    /// @dev The one call that weakens a block without unblocking first. Only
    ///      Blacklisted → Frozen: every other starting state is a caller mistake
    ///      (`unfreeze` clears a freeze, `blacklist` escalates one). The trigger is
    ///      kept and re-announced — a downgrade says the address is still under
    ///      investigation, so the evidence behind it still stands.
    function _downgradeToFrozen(address a) internal {
        if (a == address(0)) revert ZeroAddress();
        if (_blockState[a] != BlockState.Blacklisted) revert NotBlacklisted(a);
        _blockState[a] = BlockState.Frozen;
        emit AccountBlocked(a, BlockState.Frozen, _blockTrigger[a], bytes32(0));
    }

    /// @dev Clear a block. `expected` selects which removal fn ran: unfreeze
    ///      requires Frozen, unblacklist requires Blacklisted (wrong-removal
    ///      reverts — footgun guard). Absent (`None`) always reverts.
    function _clearBlock(address a, BlockState expected) internal {
        BlockState from = _blockState[a];
        if (expected == BlockState.Frozen) {
            if (from != BlockState.Frozen) revert NotFrozen(a);
        } else {
            // expected == Blacklisted
            if (from != BlockState.Blacklisted) revert NotBlacklisted(a);
        }
        _blockState[a] = BlockState.None;
        _blockTrigger[a] = 0;
        _blockedAccounts.remove(a);
        emit AccountUnblocked(a, from);
    }

    function _requireNotBlocked(address a) internal view {
        BlockState s = _blockState[a];
        if (s != BlockState.None) revert ActorBlocked(a, s);
    }

    // ─── Pause ───────────────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    function setSecurityPerimeterPaused(bool p) external onlyAdminOrOwner {
        securityPerimeterPaused = p;
        emit SecurityPerimeterPausedSet(p);
    }

    // ─── Recovery ────────────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    /// @dev Leg-2: recover once `isBlacklisted(originator) || isBlacklisted(owner)`
    ///      (OR predicate); exact provenance match to an active route; a
    ///      mixed batch reverts wholesale.
    function resolveToProtocol(uint256[] calldata ids, bytes32 routeId)
        external
        nonReentrant
        onlyAdminOrOwner
    {
        if (ids.length == 0) revert EmptyIds();
        RecoveryRoute storage route = _recoveryRoutes[routeId];
        if (!route.active) revert RouteInactive(routeId);
        for (uint256 i = 0; i < ids.length; ++i) {
            uint256 id = ids[i];
            ExitRequest storage r = _requests[id];
            if (r.status == ExitStatus.None) revert UnknownRequest(id);
            if (r.status != ExitStatus.Queued) revert AlreadyTerminal(id);

            // OR-blacklist authorization over source parties; receiver-only
            // block never authorizes Leg-2.
            bool authorized = _blockState[r.originator] == BlockState.Blacklisted
                || _blockState[r.owner] == BlockState.Blacklisted;
            if (!authorized) revert SourceNotBlacklisted(r.originator);

            // Exact provenance: surface, subProduct, token must match.
            if (r.surfaceId != route.surfaceId || r.subProduct != route.subProduct || r.token != route.token)
            {
                revert RouteProvenanceMismatch(id, routeId);
            }

            address token = r.token;
            uint128 amount = r.amount;
            r.status = ExitStatus.ResolvedToProtocol;
            _removeActive(id, r.originator, r.owner, r.receiver);
            _totalEscrowed[token] -= amount;

            emit ExitResolvedToProtocol(id, routeId, route.destination, amount);
            // topUpPool routes are a plain token top-up to the pool
            // (destination == subProduct); both branches use the same primitive.
            _payout(token, route.destination, amount, false);
            _requireSolventAfterPayout(token, false);
        }
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Leg-3: the Owner's lever, reaching only a request with a blacklisted
    ///      party. Neither a pause nor the delay window admits a request here:
    ///      a hold keeps the money in place, and only the determination that a
    ///      party is blacklisted releases it to a destination of the Owner's
    ///      choosing. Everything else stays with the parties' own levers.
    function resolveByOwner(uint256[] calldata ids, address destination) external nonReentrant onlyOwner {
        if (ids.length == 0) revert EmptyIds();
        // Same destination guard as recoverStuckExit's altReceiver: never the
        // zero address, this contract (would trap the escrow), or WRBTC (a
        // wrapped-token destination silently swallows an unwrap payout). The
        // per-request `destination == token` case is rejected inside the loop.
        if (destination == address(0) || destination == address(this) || destination == wrbtc) {
            revert InvalidDestination(destination);
        }
        for (uint256 i = 0; i < ids.length; ++i) {
            uint256 id = ids[i];
            ExitRequest storage r = _requests[id];
            if (r.status == ExitStatus.None) revert UnknownRequest(id);
            if (r.status != ExitStatus.Queued) revert AlreadyTerminal(id);

            // A blacklisted party — originator, owner or receiver — is the only
            // thing that admits a request. A frozen party keeps it held but in
            // place; a bouncing recipient is the parties' own matter, handled
            // self-service via recoverStuckExit(id, altReceiver).
            bool resolvable = _blockState[r.originator] == BlockState.Blacklisted
                || _blockState[r.owner] == BlockState.Blacklisted
                || _blockState[r.receiver] == BlockState.Blacklisted;
            if (!resolvable) revert NotResolvableByOwner(id);

            address token = r.token;
            if (destination == token) revert InvalidDestination(destination);
            uint128 amount = r.amount;
            r.status = ExitStatus.ResolvedByOwner;
            _removeActive(id, r.originator, r.owner, r.receiver);
            _totalEscrowed[token] -= amount;

            emit ExitResolvedByOwner(id, destination, amount);
            _payout(token, destination, amount, false);
            _requireSolventAfterPayout(token, false);
        }
    }

    /// @inheritdoc IExitDelayQueue
    function setRecoveryRoute(RecoveryRoute calldata route) external onlyOwner returns (bytes32 routeId) {
        // Destination guard, same as the resolve legs: never the zero address,
        // this contract (would trap escrow), the escrowed token, or WRBTC (a
        // wrapped-token destination swallows an unwrap payout). A topUpPool route
        // is pinned tighter still, to route.subProduct, below.
        if (
            route.destination == address(0) || route.destination == address(this)
                || route.destination == route.token || route.destination == wrbtc
        ) revert InvalidDestination(route.destination);
        // topUpPool routes restricted on-chain to feasible surfaces and
        // to non-native tokens (a native request can never be Leg-2a).
        if (route.topUpPool) {
            if (!_topUpFeasible[route.surfaceId]) revert TopUpInfeasibleSurface(route.surfaceId);
            if (route.token == address(0)) revert TopUpInfeasibleSurface(route.surfaceId);
            // A top-up route means exactly one thing: restore the pool the exit
            // came from. Without this, a route registered as `topUpPool` could
            // name any destination, and a Leg-2 recovery would carry a blocked
            // user's escrow there under the top-up label.
            if (route.destination != route.subProduct) {
                revert TopUpDestinationMismatch(route.destination, route.subProduct);
            }
        }
        routeId = keccak256(abi.encode(route.surfaceId, route.subProduct, route.token, route.destination));
        _recoveryRoutes[routeId] = route;
        _recoveryRouteIds.add(routeId);
        emit RecoveryRouteSet(
            routeId, route.surfaceId, route.subProduct, route.token, route.destination, route.topUpPool
        );
    }

    /// @inheritdoc IExitDelayQueue
    function removeRecoveryRoute(bytes32 routeId) external onlyOwner {
        delete _recoveryRoutes[routeId];
        _recoveryRouteIds.remove(routeId);
        emit RecoveryRouteRemoved(routeId);
    }

    /// @inheritdoc IExitDelayQueue
    function setTopUpFeasible(bytes32 surfaceId, bool feasible) external onlyOwner {
        _topUpFeasible[surfaceId] = feasible;
        emit TopUpFeasibleSet(surfaceId, feasible);
    }

    // ─── Config ──────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    function addAllowedSource(address src) external onlyOwner {
        if (src == address(0)) revert ZeroAddress();
        if (_allowedSources.add(src)) {
            _allowedSource[src] = true;
            emit AllowedSourceSet(src, true);
        }
    }

    /// @inheritdoc IExitDelayQueue
    function removeAllowedSource(address src) external onlyOwner {
        if (_allowedSources.remove(src)) {
            _allowedSource[src] = false;
            emit AllowedSourceSet(src, false);
        }
    }

    /// @inheritdoc IExitDelayQueue
    function setNativePusher(address pusher) external onlyOwner {
        nativePusher = pusher;
        emit NativePusherSet(pusher);
    }

    /// @inheritdoc IExitDelayQueue
    /// @notice Rotate the Admin guardian. Non-zero; MAY equal the Owner.
    function setAdmin(address newAdmin) external onlyOwner {
        if (newAdmin == address(0)) revert ZeroAddress();
        admin = newAdmin;
        emit AdminSet(newAdmin);
    }

    /// @inheritdoc IExitDelayQueue
    function setMinimumDelaySeconds(uint32 s) external onlyOwner {
        minimumDelaySeconds = s;
        emit MinimumDelaySet(s);
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Moves EXACTLY the non-backing surplus (balanceOf − totalEscrowed);
    ///      provably never touches escrowed backing via the post-sweep solvency
    ///      require, which uses a strict `<` so a post-sweep balance exactly
    ///      equal to `escrowed` still passes.
    function sweepSurplus(address token, address to) external nonReentrant onlyOwner {
        if (to == address(0)) revert SweepToZero();
        uint256 escrowed = _totalEscrowed[token];
        if (token == address(0)) {
            uint256 bal = address(this).balance;
            uint256 surplus = bal > escrowed ? bal - escrowed : 0;
            emit SurplusSwept(token, to, surplus);
            if (surplus > 0) Address.sendValue(payable(to), surplus);
            if (address(this).balance < escrowed) revert SolvencyViolated();
        } else {
            uint256 bal = IERC20(token).balanceOf(address(this));
            uint256 surplus = bal > escrowed ? bal - escrowed : 0;
            emit SurplusSwept(token, to, surplus);
            if (surplus > 0) IERC20(token).safeTransfer(to, surplus);
            if (IERC20(token).balanceOf(address(this)) < escrowed) revert SolvencyViolated();
        }
    }

    // ─── Payout primitive ───────────────────────────────────────────────

    /// @dev ERC20 safeTransfer / native sendValue / WRBTC-unwrap-then-sendValue.
    ///      No fail-open: a reverting receiver rolls the whole call back
    ///      (status already terminal → held until Leg-3 redirects).
    ///
    ///      LIMIT OF THE REMEDY CLAIM. All four disposal legs — execute, recover,
    ///      resolve-to-protocol, resolve-by-owner — end here. Every reachable Queued
    ///      state has a remedy within this contract's own state machine, but not
    ///      beyond it: if an escrowed ERC20 later refuses to move this contract's
    ///      balance (an upgradeable token adding a blocklist, a pause, a
    ///      migration), all four revert and the escrow is unreachable by anyone,
    ///      the Owner included. That is a property of holding third-party custody,
    ///      not something this contract can guard against; it is stated here so it
    ///      is not inherited unnoticed. None of the launch underlyings is known to
    ///      carry a blocklist.
    function _payout(address token, address to, uint128 amount, bool unwrap) internal {
        if (token == address(0)) {
            Address.sendValue(payable(to), amount);
        } else if (unwrap) {
            // WRBTC-escrowed: unwrap to native, then send native.
            IWRBTC(token).withdraw(amount);
            Address.sendValue(payable(to), amount);
        } else {
            IERC20(token).safeTransfer(to, amount);
        }
    }

    /// @dev Every request still queued must remain fully backed after value
    ///      leaves. A successful `safeTransfer` proves only that the token did
    ///      not revert: a token that charges the SENDER on transfer — including
    ///      an upgradeable one that only starts doing so after funds are
    ///      escrowed — moves more than `amount` out while `_totalEscrowed` drops
    ///      by exactly `amount`, leaving later exits short. `sweepSurplus`
    ///      already enforces this after its own transfer; the payout paths are
    ///      the other way value leaves, and must hold the same invariant.
    ///
    ///      Asserted by the CALLER, after the payout, and never inside `_payout`
    ///      itself. `recoverStuckExit` attempts the stored receiver inside a
    ///      try/catch whose bare `catch` reads ANY revert as that receiver
    ///      bouncing: a solvency failure raised in there would be taken for a
    ///      bounce and redirect the funds to the caller-selected alternate
    ///      receiver, bypassing the immutable one and hiding the alarm. Raised
    ///      out here it cannot be caught.
    function _requireSolvent(address token) internal view {
        uint256 balance = token == address(0) ? address(this).balance : IERC20(token).balanceOf(address(this));
        if (balance < _totalEscrowed[token]) revert SolvencyViolated();
    }

    /// @dev Solvency for whichever balances a payout of `token` could move. The
    ///      unwrap path spends WRBTC and sends native, so it touches both.
    function _requireSolventAfterPayout(address token, bool unwrap) internal view {
        _requireSolvent(token);
        if (unwrap && token != address(0)) _requireSolvent(address(0));
    }

    // ─── Active-index maintenance ───────────────────────────────────────

    /// @dev Remove an id from every recorded party's set; skip a set already
    ///      cleared for an earlier-checked address that coincides with it.
    function _removeActive(uint256 id, address originator, address owner_, address receiver) internal {
        _activeByParty[originator].remove(id);
        if (owner_ != originator) _activeByParty[owner_].remove(id);
        if (receiver != originator && receiver != owner_) _activeByParty[receiver].remove(id);
    }

    // ─── Views ───────────────────────────────────────────────────

    /// @inheritdoc IExitDelayQueue
    function getRequest(uint256 id) external view returns (ExitRequest memory) {
        return _requests[id];
    }

    /// @inheritdoc IExitDelayQueue
    /// @dev Best-effort over a mutating set: a concurrent removal can
    ///      skip/repeat; the ExitQueued/ExitExecuted events are the authoritative
    ///      reconstruction source. `nextCursor == 0` signals end.
    function getActive(address party, uint256 cursor, uint256 n)
        external
        view
        returns (uint256[] memory ids, uint256 nextCursor)
    {
        if (n > MAX_GET_ACTIVE_PAGE) n = MAX_GET_ACTIVE_PAGE;
        EnumerableSet.UintSet storage set = _activeByParty[party];
        uint256 len = set.length();
        if (cursor >= len || n == 0) {
            return (new uint256[](0), 0);
        }
        uint256 end = cursor + n;
        if (end > len) end = len;
        ids = new uint256[](end - cursor);
        for (uint256 i = cursor; i < end; ++i) {
            ids[i - cursor] = set.at(i);
        }
        nextCursor = end >= len ? 0 : end;
    }

    /// @inheritdoc IExitDelayQueue
    function blockStateOf(address a) external view returns (BlockState) {
        return _blockState[a];
    }

    /// @inheritdoc IExitDelayQueue
    function blockedAccounts(uint256 offset, uint256 limit)
        external
        view
        returns (address[] memory page, uint256 total)
    {
        // Return the FULL blocked-set size `total` alongside the clamped `page`:
        // a monitor/sanctions integrator paging
        // this view knows the exact range ("showing offset..offset+page.length of
        // total") and can never silently undercount past the 500 cap. `total` is
        // the true EnumerableSet length regardless of offset/limit.
        //
        // Page clamp/cap (retained): cap the page size at
        // MAX_GET_ACTIVE_PAGE and derive `end` from a bounded `limit` so
        // `offset + limit` can never overflow-revert (a griefy caller passing a
        // near-max offset/limit).
        uint256 len = _blockedAccounts.length();
        total = len;
        if (limit > MAX_GET_ACTIVE_PAGE) limit = MAX_GET_ACTIVE_PAGE;
        if (offset >= len || limit == 0) return (new address[](0), total);
        uint256 end = offset + limit;
        if (end > len) end = len;
        page = new address[](end - offset);
        for (uint256 i = offset; i < end; ++i) {
            page[i - offset] = _blockedAccounts.at(i);
        }
    }

    /// @inheritdoc IExitDelayQueue
    function blockTrigger(address a) external view returns (uint256) {
        return _blockTrigger[a];
    }

    /// @inheritdoc IExitDelayQueue
    function totalEscrowed(address token) external view returns (uint256) {
        return _totalEscrowed[token];
    }

    /// @inheritdoc IExitDelayQueue
    function getRecoveryRoute(bytes32 routeId) external view returns (RecoveryRoute memory) {
        return _recoveryRoutes[routeId];
    }

    /// @inheritdoc IExitDelayQueue
    function allowedSources() external view returns (address[] memory) {
        return _allowedSources.values();
    }

    /// @notice Enumerate registered recovery route ids (owner tooling).
    function recoveryRouteIds() external view returns (bytes32[] memory) {
        return _recoveryRouteIds.values();
    }

    /// @notice Whether a topUpPool route may be registered for `surfaceId`.
    function topUpFeasible(bytes32 surfaceId) external view returns (bool) {
        return _topUpFeasible[surfaceId];
    }

    /// @notice Whether `src` is a registered ingress source.
    function isAllowedSource(address src) external view returns (bool) {
        return _allowedSource[src];
    }

    // ─── Upgrade authorization (UUPS) ───────────────────────────────────

    // aderyn-ignore-next-line(centralization-risk)
    function _authorizeUpgrade(address newImplementation) internal view override onlyOwner {
        if (newImplementation == address(0)) revert UpgradeImplZero();
    }

    /// @dev Disabled: an ownerless custody contract would lock escrowed funds
    ///      forever (no execute-side auth changes, but no upgrade / no config /
    ///      no recovery-config). The 2-step transfer is the only admin move.
    function renounceOwnership() public pure override {
        revert OwnershipCannotBeRenounced();
    }

    // `admin == owner` is a supported shape and nothing here enforces a
    // separation: at launch one Safe holds both roles. The
    // consequence is accepted — while the roles coincide the Leg-2/Leg-3
    // authority split and its bounds are vacuous, and they become real only
    // once ownership moves to Bitocracy while the guardian stays put.
}

src/ExitFeeController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import {IExitFeeController} from "./interfaces/IExitFeeController.sol";

/// @title  ExitFeeController
/// @notice Owner-controlled resolver for Perimeter fee policy. Three
///         RatePolicy tiers per surface: actor → sub-product → surface.
///         Most-specific *active* entry wins; the surface itself gates the
///         surface (if its `active` flag is false, overrides do not apply).
///         All quote calls are view-only; the controller never moves tokens.
///         UUPS upgradeable; only the owner can authorize a new impl.
//
// The `payable` flag aderyn flags comes from UUPSUpgradeable.upgradeToAndCall;
// it forwards msg.value to the new impl's initializer if any. The function is
// owner-gated by _authorizeUpgrade below, so the only way the gas token could reach
// this contract is if the Owner deliberately attaches value to an upgrade
// call. The controller itself has no payable user surface and no `receive()`.
// aderyn-ignore-next-line(contract-locks-ether)
contract ExitFeeController is IExitFeeController, Initializable, UUPSUpgradeable, Ownable2StepUpgradeable {
    /// @notice Hard ceiling on any rate (100.00%).
    // 10_000 is more readable than `1e4` in bps context (MAX_BPS == 100.00%).
    // aderyn-ignore-next-line(large-numeric-literal)
    uint16 public constant MAX_BPS = 10_000;

    // ─── Surface identifiers ────────────────────────────────────────────
    //
    // A `surfaceId` is an opaque `bytes32` naming an operation kind. The
    // controller stores it as-is and never inspects or decodes it -- the
    // contract is product/asset-agnostic. The off-chain naming convention
    // is `keccak256("<SURFACE_NAME>")`; nothing on-chain enforces or depends
    // on it. Adding a surface is therefore an owner-only
    // `setSurfacePolicy(newId, policy)` call -- never a contract upgrade.

    // ─── Own storage ────────────────────────────────────────────────────
    // Verified via `forge inspect ExitFeeController storageLayout`. The
    // contract's "own" slot 0 sits at proxy slot 251, after the inherited
    // OZ namespaces:
    //
    //   0          Initializable (_initialized + _initializing packed)
    //   1   .. 50  Initializable.__gap
    //   51  .. 100 UUPSUpgradeable.__gap
    //   101 .. 150 ContextUpgradeable.__gap
    //   151        OwnableUpgradeable._owner
    //   152 .. 200 OwnableUpgradeable.__gap
    //   201        Ownable2StepUpgradeable._pendingOwner
    //   202 .. 250 Ownable2StepUpgradeable.__gap
    //   251        ExitFeeController.exitFeeEnabled (1 byte) +
    //              ExitFeeController.feeReceiver    (20 bytes) -- PACKED.
    //   252        _surfacePolicy           mapping head
    //   253        _subProductPolicy        mapping head
    //   254        _actorPolicy             mapping head
    //   255        _subProductKeys          mapping head (enumeration index)
    //   256        _actorKeys               mapping head (enumeration index)
    //
    //   257        admin (20 bytes, offset 0) -- alone; the remaining
    //              12 bytes of the slot are intentionally unused.
    //
    //   258        _surfaceBypass           mapping head
    //   259        _subProductBypass        mapping head
    //   260        _actorBypass             mapping head
    //   261        _surfaceBypassKeys._values  (Bytes32Set array head)   ┐ 2 slots
    //   262        _surfaceBypassKeys._indexes (mapping head)            ┘
    //   263        _subProductBypassKeys    mapping head (enumeration index)
    //   264        _actorBypassKeys         mapping head (enumeration index)
    //   265        _bypassSurfaceIds._values  (Bytes32Set array head)    ┐ 2 slots
    //   266        _bypassSurfaceIds._indexes (mapping head)             ┘
    //   267        securityPerimeterEnabled (1 byte) + globalDelaySeconds
    //              (4 bytes) -- PACKED; 27 bytes of the slot are unused.
    //   268 .. 300 __gap[33] -- preserves the OZ-style 50-slot namespace
    //                           (50 - 17 own slots used).
    //
    // Own slots: 251 + 252..256 + 257 + 258..267 = 17, so __gap = 50 - 17 = 33
    // and the namespace ends at slot 300.
    //
    // Upgrades that add storage to THIS contract MUST consume from __gap and
    // reduce its length by exactly the number of slots added. They MUST NOT
    // reorder, insert, or change the type of any preceding slot. In
    // particular, nothing may be declared before `admin`, and nothing may be
    // packed into the free bytes of its slot.

    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.Bytes32Set;

    /// @notice Global enablement flag. When false, every `quoteExitFee`
    ///         call returns `INACTIVE` regardless of per-surface configuration.
    ///         The single runtime kill switch.
    bool public exitFeeEnabled;

    /// @notice Destination for every fee leg. Product hooks read this from
    ///         the quote payload; the controller itself never moves tokens.
    address public feeReceiver;

    /// @dev Surface tier -- the policy gate + default rate per operation kind.
    ///
    ///      Key: `surfaceId` (bytes32) -- opaque operation-kind identifier.
    ///      Value: `RatePolicy` ({active, rateBps}).
    ///
    ///      The surface tier acts as the gate: if `active == false`, the whole
    ///      surface is off and the sub-product / actor overrides below are
    ///      ignored for that surface.
    mapping(bytes32 => RatePolicy) internal _surfacePolicy;

    /// @dev Sub-product override tier (one level finer than surface).
    ///
    ///      Outer key: `surfaceId` (bytes32) -- as above.
    ///      Inner key: `subProduct` (address) -- per-instance address whose
    ///      meaning is fixed by the surface convention (lending = iToken proxy,
    ///      AMM = converter address). Non-zero only -- `_writeSubProductPolicy`
    ///      reverts on `address(0)`.
    ///      Value: `RatePolicy` ({active, rateBps}).
    ///
    ///      Surfaces with no per-instance dimension call `quoteExitFee` with
    ///      `subProduct = address(0)` as a sentinel. `_resolvePolicy` sees the
    ///      zero argument and skips this map entirely, falling through to the
    ///      surface tier -- so the map is never consulted on those paths.
    ///
    ///      Wins over the surface tier when active. Only consulted if the
    ///      surface gate is on.
    mapping(bytes32 => mapping(address => RatePolicy)) internal _subProductPolicy;

    /// @dev Actor override tier (most specific).
    ///
    ///      Outer key: `surfaceId` (bytes32) -- as above.
    ///      Inner key: `actor` (address) -- whoever initiated the exit (always
    ///      `msg.sender` from the product hook -- never `tx.origin`). Non-zero
    ///      only -- `_writeActorPolicy` reverts on `address(0)`.
    ///      Value: `RatePolicy` ({active, rateBps}).
    ///
    ///      Wins over sub-product and surface when active. The common shape for
    ///      an exemption is `(active = true, rateBps = 0)`.
    mapping(bytes32 => mapping(address => RatePolicy)) internal _actorPolicy;

    /// @dev Enumeration indexes -- every (surfaceId, address) pair that
    ///      has been written via setSubProductPolicy / setActorPolicy
    ///      (singular or batch) is recorded here. Used by external
    ///      read-only inspectors and off-chain tooling to list configured
    ///      overrides without log scans. Entries are NOT auto-cleared on
    ///      soft retire (setSubProductPolicy with `(false, 0)`); use
    ///      removeSubProductPolicy / removeActorPolicy for hard removal.
    mapping(bytes32 => EnumerableSet.AddressSet) internal _subProductKeys;
    mapping(bytes32 => EnumerableSet.AddressSet) internal _actorKeys;

    /// @notice Fast operational guardian. A SINGLE stored address checked by
    ///         `onlyAdminOrOwner` -- NOT an OZ AccessControl role (the
    ///         controller stays single-Owner for configuration). It authorizes
    ///         the perimeter kill switch and the operational levers
    ///         `setExitFeeEnabled` and `setFeeReceiver`; policy setters,
    ///         removals, `setAdmin` itself, and UUPS upgrades stay `onlyOwner`.
    ///         MAY equal the owner -- nothing requires the two authorities to
    ///         be distinct. Unset (`address(0)`) until the owner appoints one;
    ///         while unset, `onlyAdminOrOwner` admits only the owner.
    /// @dev    Occupies slot 257 at offset 0, alone. Its position is fixed:
    ///         nothing may be declared before it, and nothing may be packed
    ///         into the free bytes beside it.
    address public admin;

    // ─── Delay policy state ─────────────────────────────────────────────

    /// @dev Surface-tier delay bypass. Key: `surfaceId`. Value:
    ///      `DelayBypassPolicy {active, bypass}`. Mirrors `_surfacePolicy`'s
    ///      shape but is INDEPENDENT of it — the delay resolver never
    ///      reads the fee `surfacePolicy.active`.
    mapping(bytes32 => IExitFeeController.DelayBypassPolicy) internal _surfaceBypass;

    /// @dev Sub-product-tier delay bypass. Outer key `surfaceId`, inner key
    ///      `subProduct` (non-zero). Wins over the surface tier when active.
    mapping(bytes32 => mapping(address => IExitFeeController.DelayBypassPolicy)) internal _subProductBypass;

    /// @dev Actor-tier delay bypass (most specific). Outer key `surfaceId`,
    ///      inner key `actor` (non-zero) — evaluated on `effOrig` ONLY (there is
    ///      NO global actor bypass). Wins over sub-product and surface.
    mapping(bytes32 => mapping(address => IExitFeeController.DelayBypassPolicy)) internal _actorBypass;

    /// @dev Enumeration index for the SURFACE-tier bypass. A single
    ///      flat `Bytes32Set` of every `surfaceId` with a configured surface bypass
    ///      — surface bypasses are keyed by `surfaceId` alone and are NOT scoped by
    ///      a parent surface, so `surfaceBypassKeys()` takes NO argument. Backed on
    ///      chain so `InspectController` / monitoring can dump every surface bypass
    ///      (no unenumerable zero-delay state). Retains soft-retired entries
    ///      (`active=false`); `removeSurfaceBypass` hard-removes.
    EnumerableSet.Bytes32Set internal _surfaceBypassKeys;

    /// @dev Enumeration indexes for the sub-product / actor bypass tiers (mirror
    ///      `_subProductKeys` / `_actorKeys`). Entries are retained on
    ///      soft-retire (`active=false`); use `removeSubProductBypass` /
    ///      `removeActorBypass` for hard removal. Consumed by `InspectController`.
    mapping(bytes32 => EnumerableSet.AddressSet) internal _subProductBypassKeys;
    mapping(bytes32 => EnumerableSet.AddressSet) internal _actorBypassKeys;

    /// @dev ANY-TIER-TOUCHED master surface-id set for delay bypasses.
    ///      Every bypass WRITER — `_writeSurfaceBypass` (via
    ///      `setSurfaceBypass`), `_writeSubProductBypass`, `_writeActorBypass` —
    ///      records its `surfaceId` here, so a surface that carries ONLY a
    ///      sub-product- or actor-tier bypass (the most common exemption shape,
    ///       actor tier) is discoverable even though it was never passed to
    ///      `setSurfaceBypass`. This is the root-cause fix: the per-tier key-sets
    ///      (`_surfaceBypassKeys` / `_subProductBypassKeys` / `_actorBypassKeys`)
    ///      only tell you WHICH keys exist UNDER a known surfaceId — they cannot
    ///      by themselves enumerate the surfaceIds. `bypassSurfaceIds()` closes
    ///      that gap so NO zero-delay / identity config is invisible to
    ///      `InspectController`. Entries are NEVER dropped (soft-retire retention),
    ///      so a `removeSurfaceBypass` while sub/actor entries remain live does not
    ///      remove the id from discovery — the inspector still probes every tier.
    EnumerableSet.Bytes32Set internal _bypassSurfaceIds;

    /// @notice Global kill switch for the DELAY perimeter. Independent of
    ///         `exitFeeEnabled`: turning fees off does NOT disable the
    ///         perimeter, and a fee-inactive surface can still be delay-active.
    ///         When false, `quoteExitDelayFor` short-circuits to
    ///         `(0, raw, owner)` without consulting the bypass tiers or the
    ///         queue.
    bool public securityPerimeterEnabled;

    /// @notice One delay for EVERY surface (uint32 gives ~136 years of head
    ///         room). There is no per-surface delay *duration* -- only the
    ///         per-tier bypass toggles above exempt a surface, sub-product or
    ///         actor. The `>= queue.minimumDelaySeconds` relationship is a
    ///         liveness invariant enforced PER-REQUEST in the queue, not a
    ///         cross-contract setter guard here: the controller never reads or
    ///         calls the queue.
    uint32 public globalDelaySeconds;

    // aderyn-ignore-next-line(unused-state-variable)
    uint256[33] private __gap;

    // ─── Custom errors ──────────────────────────────────────────────────

    error RateExceedsMaxBps(uint16 rateBps);
    error FeeReceiverZero();
    error SubProductZero();
    error ActorZero();
    error LengthMismatch();
    error OwnershipCannotBeRenounced();
    error UpgradeImplZero();
    error DelayZero();
    error DelayUnset();

    // ─── Custom errors (admin role) ─────────────────────────────────────
    error NotAdminOrOwner(address caller); // onlyAdminOrOwner gate
    error AdminZero(); //                     setAdmin(address(0))

    // ─── Modifiers ──────────────────────────────────────────────────────

    /// @dev The `Admin` guardian OR the `Ownable2Step` owner. Gates the
    ///      perimeter kill switch and — since the core
    ///      merge — the fee levers `setExitFeeEnabled` /
    ///      `setFeeReceiver`. All other setters are `onlyOwner`.
    modifier onlyAdminOrOwner() {
        if (msg.sender != admin && msg.sender != owner()) revert NotAdminOrOwner(msg.sender);
        _;
    }

    // ─── Construction / initialization ──────────────────────────────────

    constructor() {
        _disableInitializers();
    }

    /// @notice Initialize the proxy. `__Ownable_init` makes the caller the
    ///         initial owner; `newOwner_` decides whether ownership moves
    ///         on immediately or stays with the caller.
    /// @param  newOwner_ Address to take ownership.
    ///         - `address(0)` or `msg.sender`: the caller stays owner, so
    ///           it can configure the proxy and hand ownership off later.
    ///         - Any other address: ownership transfers immediately.
    function initialize(address newOwner_) external initializer {
        __Ownable_init();
        __Ownable2Step_init();
        __UUPSUpgradeable_init();
        if (newOwner_ != address(0) && newOwner_ != msg.sender) {
            _transferOwnership(newOwner_);
        }
    }

    // ─── Upgrade authorization (UUPS) ───────────────────────────────────

    /// @dev Only the owner can authorize an upgrade, and the new impl must
    ///      be non-zero. Storage-layout compatibility and impl verification
    ///      are the owner's responsibility off-chain; this function is only
    ///      the on-chain access gate.
    // aderyn-ignore-next-line(centralization-risk)
    function _authorizeUpgrade(address newImplementation) internal view override onlyOwner {
        if (newImplementation == address(0)) revert UpgradeImplZero();
    }

    // ─── Disable renounceOwnership ──────────────────────────────────────

    /// @notice Disabled. Reverts with `OwnershipCannotBeRenounced`. Use
    ///         `transferOwnership` + `acceptOwnership` to rotate the owner.
    /// @dev Prevents permanent loss of admin -- without an owner, no rate
    ///      updates, no emergency disable, and no UUPS upgrades are
    ///      possible.
    function renounceOwnership() public pure override {
        revert OwnershipCannotBeRenounced();
    }

    // `admin == owner` is a supported shape and nothing here enforces a
    // separation: at launch one Safe holds both roles. The queue
    // says the same about its own pair of roles.

    /// @notice Appoint (or rotate) the operational guardian checked by
    ///         `onlyAdminOrOwner`. Owner-only. `address(0)` is rejected --
    ///         clearing the guardian would silently drop the fast incident
    ///         path; to disable it, rotate to a held-but-inert address
    ///         instead. MAY equal the owner.
    /// @param  newAdmin Non-zero address.
    // aderyn-ignore-next-line(centralization-risk)
    function setAdmin(address newAdmin) external onlyOwner {
        if (newAdmin == address(0)) revert AdminZero();
        admin = newAdmin;
        emit AdminSet(newAdmin);
    }

    // ─── Admin: global state ────────────────────────────────────────────

    /// @notice Flip the global kill switch. While `false`, every
    ///         `quoteExitFee` returns `INACTIVE` and product hooks no-op.
    ///         All other configuration is preserved across flips.
    ///         Admin-or-owner (both directions) for fast incident response.
    /// @param  enabled Target state for the global switch.
    // aderyn-ignore-next-line(centralization-risk)
    function setExitFeeEnabled(bool enabled) external onlyAdminOrOwner {
        exitFeeEnabled = enabled;
        emit ExitFeeEnabledSet(enabled);
    }

    /// @notice Set the global fee destination (typically the ExitFeeVault
    ///         proxy). Required before the system can charge: with the
    ///         receiver unset, quotes return `DISABLED` even when enabled.
    ///         Admin-or-owner so the fee leg can be re-pointed (e.g. to a
    ///         replacement vault) without needing an Owner-only action.
    /// @param  newReceiver Non-zero address that receives every fee leg.
    // aderyn-ignore-next-line(centralization-risk)
    function setFeeReceiver(address newReceiver) external onlyAdminOrOwner {
        if (newReceiver == address(0)) revert FeeReceiverZero();
        feeReceiver = newReceiver;
        emit FeeReceiverSet(newReceiver);
    }

    // ─── Admin: delay global state ───────────────

    /// @notice Flip the DELAY perimeter kill switch. `onlyAdminOrOwner`
    ///         (the fee levers joined this gate in) — both
    ///         directions, for sub-minute incident response. Independent of
    ///         `exitFeeEnabled`:
    ///         disabling fees does NOT disable the perimeter and vice-versa.
    ///         Accepted residual: a rogue Admin can DISABLE the perimeter (a
    ///         protocol-wide fail-OPEN delay removal) — the deliberate tradeoff.
    /// @param  enabled Target state for the perimeter.
    // aderyn-ignore-next-line(centralization-risk)
    function setSecurityPerimeterEnabled(bool enabled) external onlyAdminOrOwner {
        // Switching on with no delay length set would leave the switch reading
        // on while every exit paid out immediately. Switching off is never
        // blocked: it is the kill switch.
        if (enabled && globalDelaySeconds == 0) revert DelayUnset();
        securityPerimeterEnabled = enabled;
        emit SecurityPerimeterEnabledSet(enabled);
    }

    /// @notice Set the single global delay applied whenever a delay is imposed.
    ///         Owner-only. The `>= queue.minimumDelaySeconds` floor
    ///         is a documented liveness invariant enforced PER-REQUEST in the
    ///         queue and by a deploy-script assertion — NOT a
    ///         cross-contract setter guard, so the controller never reads or
    ///         calls the queue (kill-switch queue-independence). A value
    ///         below the floor would self-brick every non-bypassed exit
    ///         (fail-closed) but can NEVER rush a request below the floor.
    /// @param  seconds_ Delay in seconds (uint32). Zero is refused: a zero
    ///         length would switch the delay off for every non-bypassed exit
    ///         while `securityPerimeterEnabled` still read true. The delay is
    ///         switched off with `setSecurityPerimeterEnabled(false)`, never
    ///         by its length.
    function setGlobalDelaySeconds(uint32 seconds_) external onlyOwner {
        if (seconds_ == 0) revert DelayZero();
        globalDelaySeconds = seconds_;
        emit GlobalDelaySet(seconds_);
    }

    // ─── Admin: policy setters ──────────────────────────────────────────
    //
    // `surfaceId` is an opaque operation-kind identifier. The off-chain
    // naming convention is `keccak256("<SURFACE_NAME>")`; the controller
    // stores the bytes32 as-is and never inspects the name.

    /// @notice Configure (or update) the surface tier for `surfaceId`.
    ///         The surface acts as the gate: with `policy.active == false`
    ///         the whole surface is off and sub-product / actor overrides
    ///         are ignored. Overwriting is idempotent.
    /// @param  surfaceId Opaque operation-kind identifier;
    ///         `keccak256("<SURFACE_NAME>")` by convention.
    /// @param  policy Active flag + rate in basis points (`rateBps <= MAX_BPS`).
    function setSurfacePolicy(bytes32 surfaceId, RatePolicy calldata policy) external onlyOwner {
        if (policy.rateBps > MAX_BPS) revert RateExceedsMaxBps(policy.rateBps);
        _surfacePolicy[surfaceId] = policy;
        emit SurfacePolicySet(surfaceId, policy.active, policy.rateBps);
    }

    /// @notice Configure (or update) a sub-product override under
    ///         `surfaceId`. Wins over the surface tier when its `active`
    ///         flag is true (and the surface gate is on). Records the
    ///         address in the enumeration index for off-chain inspection.
    /// @param  surfaceId  See `setSurfacePolicy`.
    /// @param  subProduct Per-instance address; meaning fixed by surface
    ///         (lending = iToken, AMM = converter, etc.). Non-zero.
    /// @param  policy     Active flag + rate (`rateBps <= MAX_BPS`).
    function setSubProductPolicy(bytes32 surfaceId, address subProduct, RatePolicy calldata policy)
        external
        onlyOwner
    {
        _writeSubProductPolicy(surfaceId, subProduct, policy);
    }

    /// @notice Batch variant of `setSubProductPolicy`. Reverts on length
    ///         mismatch or any per-entry validation failure (zero address,
    ///         rate above ceiling); a revert mid-batch undoes the whole
    ///         batch.
    /// @param  surfaceId   See `setSurfacePolicy`.
    /// @param  subProducts Sub-product addresses, same order as `policies`.
    /// @param  policies    Per-address policies, same order as `subProducts`.
    function setSubProductPolicies(
        bytes32 surfaceId,
        address[] calldata subProducts,
        RatePolicy[] calldata policies
    ) external onlyOwner {
        uint256 len = subProducts.length;
        if (len != policies.length) revert LengthMismatch();
        for (uint256 i = 0; i < len; ++i) {
            _writeSubProductPolicy(surfaceId, subProducts[i], policies[i]);
        }
    }

    /// @notice Configure (or update) an actor override under `surfaceId`.
    ///         The most-specific tier: wins over sub-product and surface
    ///         when active. Use `(active=true, rateBps=0)` for an
    ///         exemption.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @param  actor     Address whose exits are policy-keyed. Non-zero.
    /// @param  policy    Active flag + rate (`rateBps <= MAX_BPS`).
    function setActorPolicy(bytes32 surfaceId, address actor, RatePolicy calldata policy)
        external
        onlyOwner
    {
        _writeActorPolicy(surfaceId, actor, policy);
    }

    /// @notice Batch variant of `setActorPolicy`. Same revert semantics
    ///         as `setSubProductPolicies`.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @param  actors    Actor addresses, same order as `policies`.
    /// @param  policies  Per-address policies, same order as `actors`.
    function setActorPolicies(bytes32 surfaceId, address[] calldata actors, RatePolicy[] calldata policies)
        external
        onlyOwner
    {
        uint256 len = actors.length;
        if (len != policies.length) revert LengthMismatch();
        for (uint256 i = 0; i < len; ++i) {
            _writeActorPolicy(surfaceId, actors[i], policies[i]);
        }
    }

    function _writeSubProductPolicy(bytes32 surfaceId, address subProduct, RatePolicy calldata policy)
        internal
    {
        if (subProduct == address(0)) revert SubProductZero();
        if (policy.rateBps > MAX_BPS) revert RateExceedsMaxBps(policy.rateBps);
        _subProductPolicy[surfaceId][subProduct] = policy;
        // EnumerableSet.add returns false if already present; idempotent here.
        // aderyn-ignore-next-line(unchecked-return)
        _subProductKeys[surfaceId].add(subProduct);
        emit SubProductPolicySet(surfaceId, subProduct, policy.active, policy.rateBps);
    }

    function _writeActorPolicy(bytes32 surfaceId, address actor, RatePolicy calldata policy) internal {
        if (actor == address(0)) revert ActorZero();
        if (policy.rateBps > MAX_BPS) revert RateExceedsMaxBps(policy.rateBps);
        _actorPolicy[surfaceId][actor] = policy;
        // aderyn-ignore-next-line(unchecked-return)
        _actorKeys[surfaceId].add(actor);
        emit ActorPolicySet(surfaceId, actor, policy.active, policy.rateBps);
    }

    // ─── Admin: policy removal ──────────────────────────────────────────
    //
    // Hard-removes a sub-product or actor override: clears the stored
    // RatePolicy AND drops the address from the enumeration index.
    // Idempotent: a remove call for an address that is not currently in
    // the index is a successful no-op (no event emitted, no revert), so a
    // batched retire cannot fail because an earlier step already removed
    // the entry.
    //
    // To temporarily disable an override while keeping it visible in the
    // inspector, use setSubProductPolicy / setActorPolicy with
    // RatePolicy(false, 0) instead (soft retire). To remove it
    // permanently, use these.

    /// @notice Hard-remove a sub-product override: clears its `RatePolicy`
    ///         and drops it from the enumeration index. Idempotent --
    ///         a remove for an address that is not currently in the
    ///         index is a successful no-op (no event, no revert).
    /// @param  surfaceId  See `setSurfacePolicy`.
    /// @param  subProduct Sub-product address to remove. Non-zero.
    function removeSubProductPolicy(bytes32 surfaceId, address subProduct) external onlyOwner {
        _removeSubProductPolicy(surfaceId, subProduct);
    }

    /// @notice Batch variant of `removeSubProductPolicy`. Each entry is
    ///         independently idempotent; the batch reverts only on a zero
    ///         address.
    /// @param  surfaceId   See `setSurfacePolicy`.
    /// @param  subProducts Sub-product addresses to remove.
    function removeSubProductPolicies(bytes32 surfaceId, address[] calldata subProducts) external onlyOwner {
        uint256 len = subProducts.length;
        for (uint256 i = 0; i < len; ++i) {
            _removeSubProductPolicy(surfaceId, subProducts[i]);
        }
    }

    /// @notice Hard-remove an actor override. Same idempotent semantics
    ///         as `removeSubProductPolicy`.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @param  actor     Actor address to remove. Non-zero.
    function removeActorPolicy(bytes32 surfaceId, address actor) external onlyOwner {
        _removeActorPolicy(surfaceId, actor);
    }

    /// @notice Batch variant of `removeActorPolicy`. Each entry
    ///         independently idempotent; batch reverts only on a zero
    ///         address.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @param  actors    Actor addresses to remove.
    function removeActorPolicies(bytes32 surfaceId, address[] calldata actors) external onlyOwner {
        uint256 len = actors.length;
        for (uint256 i = 0; i < len; ++i) {
            _removeActorPolicy(surfaceId, actors[i]);
        }
    }

    function _removeSubProductPolicy(bytes32 surfaceId, address subProduct) internal {
        if (subProduct == address(0)) revert SubProductZero();
        // EnumerableSet.remove returns true iff the element was present.
        // Gating the cleanup on that lets us emit only on real removals
        // (audit trail) while keeping the call idempotent.
        if (_subProductKeys[surfaceId].remove(subProduct)) {
            delete _subProductPolicy[surfaceId][subProduct];
            emit SubProductPolicyRemoved(surfaceId, subProduct);
        }
    }

    function _removeActorPolicy(bytes32 surfaceId, address actor) internal {
        if (actor == address(0)) revert ActorZero();
        if (_actorKeys[surfaceId].remove(actor)) {
            delete _actorPolicy[surfaceId][actor];
            emit ActorPolicyRemoved(surfaceId, actor);
        }
    }

    // ─── Admin: delay bypass tiers ────────────────────
    //
    // Mirrors the fee-tier setters but on `DelayBypassPolicy`. A
    // `{active:true, bypass:true}` entry EXEMPTS the surface/subProduct/actor
    // (d = 0, instant); a `{active:true, bypass:false}` entry FORCES the global
    // delay (overriding a broader bypass). `{active:false}` falls through. The
    // enumeration keys retain soft-retired entries; use the removers for hard
    // removal. Precedence and the truth table live in `_resolveDelay` below.

    /// @notice Configure (or update) the surface-tier delay bypass for
    ///         `surfaceId`. Overwriting is idempotent.
    function setSurfaceBypass(bytes32 surfaceId, IExitFeeController.DelayBypassPolicy calldata policy)
        external
        onlyOwner
    {
        _writeSurfaceBypass(surfaceId, policy);
    }

    function _writeSurfaceBypass(bytes32 surfaceId, IExitFeeController.DelayBypassPolicy calldata policy)
        internal
    {
        _surfaceBypass[surfaceId] = policy;
        // Per-tier enumeration index. Idempotent: add returns
        // false if already present. Retained on soft-retire (`active=false`).
        // aderyn-ignore-next-line(unchecked-return)
        _surfaceBypassKeys.add(surfaceId);
        // ANY-TIER-TOUCHED master set: record the surfaceId so the
        // inspector discovers it regardless of which tier configured it.
        // aderyn-ignore-next-line(unchecked-return)
        _bypassSurfaceIds.add(surfaceId);
        emit SurfaceBypassSet(surfaceId, policy.active, policy.bypass);
    }

    /// @notice Hard-remove a surface-tier delay bypass: clears the stored policy
    ///         and drops the surfaceId from the enumeration index. Idempotent --
    ///         a remove for a surfaceId not currently in the index is a successful
    ///         no-op (no event, no revert). To temporarily disable while keeping it
    ///         visible in the inspector, use `setSurfaceBypass(id, {false, false})`.
    function removeSurfaceBypass(bytes32 surfaceId) external onlyOwner {
        if (_surfaceBypassKeys.remove(surfaceId)) {
            delete _surfaceBypass[surfaceId];
            emit SurfaceBypassRemoved(surfaceId);
        }
    }

    /// @notice Configure (or update) a sub-product-tier delay bypass. Records
    ///         the address in the enumeration index. `subProduct` non-zero.
    function setSubProductBypass(
        bytes32 surfaceId,
        address subProduct,
        IExitFeeController.DelayBypassPolicy calldata policy
    ) external onlyOwner {
        _writeSubProductBypass(surfaceId, subProduct, policy);
    }

    /// @notice Batch variant of `setSubProductBypass`. Reverts on length
    ///         mismatch or a zero address; a revert mid-batch undoes the batch.
    function setSubProductBypasses(
        bytes32 surfaceId,
        address[] calldata subProducts,
        IExitFeeController.DelayBypassPolicy[] calldata policies
    ) external onlyOwner {
        uint256 len = subProducts.length;
        if (len != policies.length) revert LengthMismatch();
        for (uint256 i = 0; i < len; ++i) {
            _writeSubProductBypass(surfaceId, subProducts[i], policies[i]);
        }
    }

    /// @notice Configure (or update) an actor-tier delay bypass (most specific;
    ///         evaluated on `effOrig`). `actor` non-zero.
    function setActorBypass(
        bytes32 surfaceId,
        address actor,
        IExitFeeController.DelayBypassPolicy calldata policy
    ) external onlyOwner {
        _writeActorBypass(surfaceId, actor, policy);
    }

    /// @notice Batch variant of `setActorBypass`. Same revert semantics as
    ///         `setSubProductBypasses`.
    function setActorBypasses(
        bytes32 surfaceId,
        address[] calldata actors,
        IExitFeeController.DelayBypassPolicy[] calldata policies
    ) external onlyOwner {
        uint256 len = actors.length;
        if (len != policies.length) revert LengthMismatch();
        for (uint256 i = 0; i < len; ++i) {
            _writeActorBypass(surfaceId, actors[i], policies[i]);
        }
    }

    function _writeSubProductBypass(
        bytes32 surfaceId,
        address subProduct,
        IExitFeeController.DelayBypassPolicy calldata policy
    ) internal {
        if (subProduct == address(0)) revert SubProductZero();
        _subProductBypass[surfaceId][subProduct] = policy;
        // aderyn-ignore-next-line(unchecked-return)
        _subProductBypassKeys[surfaceId].add(subProduct);
        // ANY-TIER-TOUCHED master set: a sub-product-only bypass
        // under an arbitrary surfaceId is otherwise undiscoverable — record it.
        // aderyn-ignore-next-line(unchecked-return)
        _bypassSurfaceIds.add(surfaceId);
        emit SubProductBypassSet(surfaceId, subProduct, policy.active, policy.bypass);
    }

    function _writeActorBypass(
        bytes32 surfaceId,
        address actor,
        IExitFeeController.DelayBypassPolicy calldata policy
    ) internal {
        if (actor == address(0)) revert ActorZero();
        _actorBypass[surfaceId][actor] = policy;
        // aderyn-ignore-next-line(unchecked-return)
        _actorBypassKeys[surfaceId].add(actor);
        // ANY-TIER-TOUCHED master set: the actor tier is the MOST
        // COMMON exemption shape — an actor-only bypass with no prior
        // setSurfaceBypass MUST still surface the id to the inspector.
        // aderyn-ignore-next-line(unchecked-return)
        _bypassSurfaceIds.add(surfaceId);
        emit ActorBypassSet(surfaceId, actor, policy.active, policy.bypass);
    }

    /// @notice Hard-remove a sub-product-tier delay bypass: clears the stored
    ///         policy and drops it from the enumeration index. Idempotent.
    function removeSubProductBypass(bytes32 surfaceId, address subProduct) external onlyOwner {
        _removeSubProductBypass(surfaceId, subProduct);
    }

    /// @notice Batch variant of `removeSubProductBypass`.
    function removeSubProductBypasses(bytes32 surfaceId, address[] calldata subProducts) external onlyOwner {
        uint256 len = subProducts.length;
        for (uint256 i = 0; i < len; ++i) {
            _removeSubProductBypass(surfaceId, subProducts[i]);
        }
    }

    /// @notice Hard-remove an actor-tier delay bypass. Idempotent.
    function removeActorBypass(bytes32 surfaceId, address actor) external onlyOwner {
        _removeActorBypass(surfaceId, actor);
    }

    /// @notice Batch variant of `removeActorBypass`.
    function removeActorBypasses(bytes32 surfaceId, address[] calldata actors) external onlyOwner {
        uint256 len = actors.length;
        for (uint256 i = 0; i < len; ++i) {
            _removeActorBypass(surfaceId, actors[i]);
        }
    }

    /// @notice Withdraw an actor-tier exemption on `surfaceId` in one call.
    ///         The fee entry is written inactive, restoring the sub-product
    ///         or surface policy; the delay entry is active with no bypass, so the
    ///         delay applies whatever a wider tier says. Writing the delay entry
    ///         inactive instead would fall through to that wider tier and leave
    ///         the actor exempt while its own row read as withdrawn.
    // aderyn-ignore-next-line(centralization-risk)
    function revokeExemption(bytes32 surfaceId, address actor) external onlyOwner {
        if (actor == address(0)) revert ActorZero();
        _actorPolicy[surfaceId][actor] = RatePolicy({active: false, rateBps: 0});
        // aderyn-ignore-next-line(unchecked-return)
        _actorKeys[surfaceId].add(actor);
        emit ActorPolicySet(surfaceId, actor, false, 0);
        _actorBypass[surfaceId][actor] = IExitFeeController.DelayBypassPolicy({active: true, bypass: false});
        // aderyn-ignore-next-line(unchecked-return)
        _actorBypassKeys[surfaceId].add(actor);
        // aderyn-ignore-next-line(unchecked-return)
        _bypassSurfaceIds.add(surfaceId);
        emit ActorBypassSet(surfaceId, actor, true, false);
    }

    /// @notice Grant an actor-tier exemption on `surfaceId` in one call: the
    ///         fee entry is written {active: true, rateBps: 0} and the delay
    ///         entry {active: true, bypass: true} together, so there is no
    ///         confirmation round in which only one half is live. Mirrors
    ///         `revokeExemption`'s two-write atomicity in the grant direction.
    // aderyn-ignore-next-line(centralization-risk)
    function grantExemption(bytes32 surfaceId, address actor) external onlyOwner {
        if (actor == address(0)) revert ActorZero();
        _actorPolicy[surfaceId][actor] = RatePolicy({active: true, rateBps: 0});
        // aderyn-ignore-next-line(unchecked-return)
        _actorKeys[surfaceId].add(actor);
        emit ActorPolicySet(surfaceId, actor, true, 0);
        _actorBypass[surfaceId][actor] = IExitFeeController.DelayBypassPolicy({active: true, bypass: true});
        // aderyn-ignore-next-line(unchecked-return)
        _actorBypassKeys[surfaceId].add(actor);
        // aderyn-ignore-next-line(unchecked-return)
        _bypassSurfaceIds.add(surfaceId);
        emit ActorBypassSet(surfaceId, actor, true, true);
    }

    function _removeSubProductBypass(bytes32 surfaceId, address subProduct) internal {
        if (subProduct == address(0)) revert SubProductZero();
        if (_subProductBypassKeys[surfaceId].remove(subProduct)) {
            delete _subProductBypass[surfaceId][subProduct];
            emit SubProductBypassRemoved(surfaceId, subProduct);
        }
    }

    function _removeActorBypass(bytes32 surfaceId, address actor) internal {
        if (actor == address(0)) revert ActorZero();
        if (_actorBypassKeys[surfaceId].remove(actor)) {
            delete _actorBypass[surfaceId][actor];
            emit ActorBypassRemoved(surfaceId, actor);
        }
    }

    // ─── Policy views ───────────────────────────────────────────────────

    /// @notice Surface tier (gate + default rate) for `surfaceId`. Returns
    ///         the zero-initialised `RatePolicy` if never configured.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @return The stored `RatePolicy` for the surface tier.
    function surfacePolicy(bytes32 surfaceId) external view returns (RatePolicy memory) {
        return _surfacePolicy[surfaceId];
    }

    /// @notice Sub-product override for `(surfaceId, subProduct)`. Returns
    ///         a zero-initialised `RatePolicy` if never configured.
    /// @param  surfaceId  See `setSurfacePolicy`.
    /// @param  subProduct Sub-product address whose override is being read.
    /// @return The stored `RatePolicy` for that sub-product.
    function subProductPolicy(bytes32 surfaceId, address subProduct)
        external
        view
        returns (RatePolicy memory)
    {
        return _subProductPolicy[surfaceId][subProduct];
    }

    /// @notice Actor override for `(surfaceId, actor)`. Returns a
    ///         zero-initialised `RatePolicy` if never configured.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @param  actor     Actor address whose override is being read.
    /// @return The stored `RatePolicy` for that actor.
    function actorPolicy(bytes32 surfaceId, address actor) external view returns (RatePolicy memory) {
        return _actorPolicy[surfaceId][actor];
    }

    /// @notice Every sub-product address ever configured under `surfaceId`
    ///         (via setSubProductPolicy or the batch variant). Entries are
    ///         not removed when a policy is set inactive -- pair each
    ///         address with `subProductPolicy(surfaceId, addr)` to see the
    ///         live state. Use `removeSubProductPolicy(...)` for hard
    ///         removal. Intended for off-chain inspection tooling.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @return Snapshot of every configured sub-product address.
    function subProductKeys(bytes32 surfaceId) external view returns (address[] memory) {
        return _subProductKeys[surfaceId].values();
    }

    /// @notice Every actor address ever configured under `surfaceId`
    ///         (via setActorPolicy or the batch variant). Same retention
    ///         semantics as `subProductKeys`.
    /// @param  surfaceId See `setSurfacePolicy`.
    /// @return Snapshot of every configured actor address.
    function actorKeys(bytes32 surfaceId) external view returns (address[] memory) {
        return _actorKeys[surfaceId].values();
    }

    // ─── Delay views ──────────────────────────────────

    /// @notice Surface-tier delay bypass for `surfaceId`. Zero-initialised if
    ///         never configured (`{active:false, bypass:false}`).
    function surfaceBypass(bytes32 surfaceId)
        external
        view
        returns (IExitFeeController.DelayBypassPolicy memory)
    {
        return _surfaceBypass[surfaceId];
    }

    /// @notice Sub-product-tier delay bypass for `(surfaceId, subProduct)`.
    function subProductBypass(bytes32 surfaceId, address subProduct)
        external
        view
        returns (IExitFeeController.DelayBypassPolicy memory)
    {
        return _subProductBypass[surfaceId][subProduct];
    }

    /// @notice Actor-tier delay bypass for `(surfaceId, actor)`.
    function actorBypass(bytes32 surfaceId, address actor)
        external
        view
        returns (IExitFeeController.DelayBypassPolicy memory)
    {
        return _actorBypass[surfaceId][actor];
    }

    /// @notice Every surfaceId configured in the surface-tier delay-bypass index.
    ///         Takes NO argument — surface bypasses are keyed by
    ///         `surfaceId` alone, NOT scoped by a parent surface. Entries are not
    ///         removed when a bypass is set inactive; pair each id with
    ///         `surfaceBypass(id)` to see the live state, or use
    ///         `removeSurfaceBypass(id)` for hard removal. Intended for
    ///         `InspectController` / monitoring so there is no unenumerable
    ///         zero-delay state.
    /// @return Snapshot of every configured surface-bypass surfaceId.
    function surfaceBypassKeys() external view returns (bytes32[] memory) {
        return _surfaceBypassKeys.values();
    }

    /// @notice Every sub-product configured under `surfaceId` in the delay
    ///         bypass index. Same retention semantics as `subProductKeys`.
    function subProductBypassKeys(bytes32 surfaceId) external view returns (address[] memory) {
        return _subProductBypassKeys[surfaceId].values();
    }

    /// @notice Every actor configured under `surfaceId` in the delay bypass
    ///         index. Same retention semantics as `actorKeys`.
    function actorBypassKeys(bytes32 surfaceId) external view returns (address[] memory) {
        return _actorBypassKeys[surfaceId].values();
    }

    /// @notice ANY-TIER-TOUCHED master set: EVERY surfaceId that has a bypass
    ///         entry at ANY tier — surface, sub-product, OR actor.
    ///         This is the discovery driver for `InspectController`: unlike
    ///         `surfaceBypassKeys()` (surface-tier writes only), this records the
    ///         surfaceId from `setSurfaceBypass`, `setSubProductBypass`, AND
    ///         `setActorBypass`, so a surface carrying ONLY a sub-product- or
    ///         actor-tier bypass (the most common exemption shape) is never missed.
    ///         Retention-only: entries are never dropped, so a `removeSurfaceBypass`
    ///         while sub/actor entries remain live keeps the id in discovery — the
    ///         inspector re-probes every tier per id and shows the live state.
    /// @return Snapshot of every surfaceId touched by any bypass tier.
    function bypassSurfaceIds() external view returns (bytes32[] memory) {
        return _bypassSurfaceIds.values();
    }

    // ─── Quote ──────────────────────────────────────────────────────────

    /// @inheritdoc IExitFeeController
    function quoteExitFee(bytes32 surfaceId, address subProduct, address actor, uint256 grossAmount)
        external
        view
        returns (ExitFeeQuote memory quote)
    {
        // Always echo the configured receiver and gross even on off-state
        // paths so the product can show "configured but turned off" without
        // a second call.
        quote.feeReceiver = feeReceiver;
        quote.netAmount = grossAmount;

        if (!exitFeeEnabled) {
            quote.reason = uint8(SkipReason.INACTIVE);
            return quote;
        }
        if (feeReceiver == address(0)) {
            quote.reason = uint8(SkipReason.DISABLED);
            return quote;
        }

        RatePolicy memory policy = _resolvePolicy(surfaceId, subProduct, actor);

        if (!policy.active) {
            // Surface inactive OR all tiers fell through without an active
            // policy. Either way: nothing to charge.
            quote.reason = uint8(SkipReason.DISABLED);
            return quote;
        }

        // Defensive overflow guard on the multiplication below, checked against
        // the rate that resolved rather than the ceiling: a gross that
        // multiplies safely at this rate must quote a fee, not report
        // INVALID_QUOTE and let the fee leg be skipped. A zero rate cannot
        // overflow and needs no guard. If it trips, INVALID_QUOTE lets the
        // product log it instead of silently charging the wrong amount.
        if (policy.rateBps != 0 && grossAmount > type(uint256).max / policy.rateBps) {
            quote.reason = uint8(SkipReason.INVALID_QUOTE);
            return quote;
        }
        uint256 fee = (grossAmount * uint256(policy.rateBps)) / MAX_BPS;
        if (fee > grossAmount) {
            quote.reason = uint8(SkipReason.INVALID_QUOTE);
            return quote;
        }

        // `active` reflects POLICY state, not fee amount. Dust (fee==0 from
        // rounding) and explicit exemption (rateBps==0) both return
        // active=true with feeAmount=0. The product's hook keys on
        // `quote.active && quote.feeAmount > 0` to decide the fee leg.
        quote.active = true;
        quote.rateBps = policy.rateBps;
        quote.feeAmount = fee;
        quote.netAmount = grossAmount - fee;
        quote.reason = uint8(SkipReason.NONE);
    }

    // ─── Policy resolution ──────────────────────────────────────────────

    /// @dev Resolution order: surface-gate → actor → sub-product → surface.
    ///      The SURFACE gate is checked first: if its `active` flag is
    ///      false, the whole surface is off and overrides are ignored.
    ///      When the gate is on, the most-specific *active* entry wins.
    ///      Inactive override entries fall through to the next tier.
    function _resolvePolicy(bytes32 surfaceId, address subProduct, address actor)
        internal
        view
        returns (RatePolicy memory)
    {
        RatePolicy memory surface = _surfacePolicy[surfaceId];
        if (!surface.active) {
            // Surface gate off -- caller checks `policy.active` and reports DISABLED.
            return surface;
        }

        // Actor tier (top).
        RatePolicy memory p = _actorPolicy[surfaceId][actor];
        if (p.active) return p;

        // Sub-product tier. address(0) means "no per-instance dimension"
        // (e.g. Zero) -- in that case we skip the map lookup so a sibling
        // sub-product's policy can't leak into the address(0) path.
        if (subProduct != address(0)) {
            p = _subProductPolicy[surfaceId][subProduct];
            if (p.active) return p;
        }

        // Surface fallback (always active here, since we checked above).
        return surface;
    }

    // ─── Delay quote + resolution ─────────────────────

    /// @inheritdoc IExitFeeController
    function quoteExitDelayFor(
        address rawOriginator,
        address owner_,
        address, /* receiver: fixed by the hook, never consulted here */
        bytes32 surfaceId,
        address subProduct
    ) external view returns (uint32 d, address effOrig, address effOwner) {
        // KILL-SWITCH SHORT-CIRCUIT FIRST: a disabled perimeter pays direct
        // WITHOUT consulting the bypass tiers or the queue — the liveness
        // escape. The hook must ignore the identities and pay direct whenever
        // d == 0, so nothing records.
        if (!securityPerimeterEnabled) {
            return (0, rawOriginator, owner_);
        }

        // The recorded identities are the real ones: the caller that
        // withdraws and the owner of what it withdraws. The quote is made on
        // the originator so the quote and the record share ONE identity.
        effOrig = rawOriginator;
        effOwner = owner_;
        d = _resolveDelay(surfaceId, subProduct, effOrig);
    }

    /// @inheritdoc IExitFeeController
    function quoteExitDelay(bytes32 surfaceId, address subProduct, address effectiveActor_)
        external
        view
        returns (uint32)
    {
        // Handles the disabled-perimeter case identically (returns 0 when the
        // perimeter is off) so an off-chain caller of the inner view never gets
        // a non-zero delay while the perimeter is disabled. The actor is the
        // address the bypass tier is looked up on: the originator, as in
        // `quoteExitDelayFor`.
        if (!securityPerimeterEnabled) return 0;
        return _resolveDelay(surfaceId, subProduct, effectiveActor_);
    }

    /// @dev The 3-tier delay resolver (truth table). Evaluated on
    ///      the EFFECTIVE originator. Precedence mirrors the fee resolver —
    ///      actor > subProduct > surface, most-specific-*active*-wins — but the
    ///      SOLE gate is `securityPerimeterEnabled` (checked by the callers
    ///      above): the delay resolver is INDEPENDENT of the fee
    ///      `surfacePolicy.active` and `exitFeeEnabled`. A `{active:false}` tier
    ///      falls through; an `{active:true}` tier decides — `bypass ? 0 :
    ///      globalDelaySeconds`. With no active bypass tier the default is
    ///      `globalDelaySeconds` (delayed). An active `{bypass:false}` tier at a
    ///      more-specific level overrides a broader bypass.
    function _resolveDelay(bytes32 surfaceId, address subProduct, address effOrig)
        internal
        view
        returns (uint32)
    {
        // Actor tier (most specific). No global actor bypass — always keyed
        // [surfaceId][effOrig].
        IExitFeeController.DelayBypassPolicy memory a = _actorBypass[surfaceId][effOrig];
        if (a.active) return a.bypass ? 0 : globalDelaySeconds;

        // Sub-product tier. address(0) means "no per-instance dimension" (e.g.
        // Zero) — skip the lookup so a sibling sub-product cannot leak in.
        if (subProduct != address(0)) {
            IExitFeeController.DelayBypassPolicy memory s = _subProductBypass[surfaceId][subProduct];
            if (s.active) return s.bypass ? 0 : globalDelaySeconds;
        }

        // Surface tier.
        IExitFeeController.DelayBypassPolicy memory f = _surfaceBypass[surfaceId];
        if (f.active) return f.bypass ? 0 : globalDelaySeconds;

        // No active bypass tier: default is the global delay (delayed).
        return globalDelaySeconds;
    }
}

