// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title  IExitDelayQueue
/// @notice External ABI + type/event/error catalog for `ExitDelayQueue`, the
///         per-request escrow that holds the *user* leg of an exit for a
///         configurable delay so a detected theft can be blocked (frozen or
///         blacklisted) and routed to recovery before the funds leave.
///
///         This interface mirrors `ExitDelayQueue`'s complete queue-specific
///         operational function catalog and its event and error catalog,
///         other than the `SelfOnly`-guarded `payoutExternal` self-call
///         trampoline, which is not part of the ABI a caller is meant to use.
///         Two other classes of ABI member are deliberately left out as a
///         named carve-out, not an oversight: one-time proxy setup
///         (`initialize`) and the inherited ownership/upgrade administration
///         (`owner`, `pendingOwner`, `transferOwnership`, `acceptOwnership`,
///         `renounceOwnership`, `upgradeToAndCall`, `upgradeTo`,
///         `proxiableUUID`, from `OwnableUpgradeable`, `Ownable2StepUpgradeable`
///         and `UUPSUpgradeable`), which a caller consumes through those
///         base contracts' own interfaces, not this one. The types mirror the
///         queue's own struct and enum declarations.
///
///         Types (enums/structs) are declared here so cross-pragma callers
///         and off-chain tooling share one source of truth. The queue itself
///         is 0.8.20 UUPS; the four `record*` ingress fns are consumed from
///         0.5.x / 0.6.x product hosts via a minimal interface stub.
interface IExitDelayQueue {
    // ─── Types ───────────────────────────────────────────────────

    /// @notice Per-request lifecycle. `None` is the zero value (never stored
    ///         for a live id); the three terminal states are mutually
    ///         exclusive and a request leaves `Queued` at most once.
    enum ExitStatus {
        None, //               0 — never recorded
        Queued, //             1 — escrowed, awaiting execute / recovery
        Executed, //           2 — paid to receiver (terminal)
        ResolvedToProtocol, // 3 — Leg-2 recovery-away (terminal)
        ResolvedByOwner //     4 — Leg-3 Owner resolution (terminal)

    }

    /// @notice Per-address block state. `Frozen` = temporary (investigating);
    ///         `Blacklisted` = confirmed hack. Execution treats both as
    ///         "blocked"; recovery-away distinguishes them.
    enum BlockState {
        None, //        0
        Frozen, //      1 — temporary, cleared by unfreeze
        Blacklisted // 2 — confirmed, cleared only by unblacklist

    }

    /// @notice An immutable exit request. Every field except `status` is
    ///         frozen at record time. Packed into 7 words.
    struct ExitRequest {
        // word 1 (128 + 64 + 64 = 256 bits):
        uint128 amount; //    narrowed from the uint256 Perimeter amount at record
        uint64 createdAt; //  creation timestamp; readable through getRequest
        uint64 unlockAt; //   COMPUTED by the queue = createdAt + delaySeconds
        // words 2-5:
        address originator; // withdrawal caller the hook saw — block key + executor
        address owner; //      position owner — MANDATORY block key + executor
        address receiver; //   immutable payout destination — checked on release; may recover and may deliver
        address token; //      address(0) = native RBTC
        // word 6:
        bytes32 surfaceId; //  provenance: recovery-route key
        // word 7 (160 + 8 + 8 = 176 bits):
        address subProduct; // provenance: iToken / converter / address(0)
        ExitStatus status; //  uint8
        bool unwrapOnDelivery; //  when true, the queue holds WRBTC and executeExit unwraps it to native RBTC
    }

    /// @notice A pre-approved Leg-2 recovery route. `routeId` is
    ///         `keccak256(abi.encode(surfaceId, subProduct, token, destination))`.
    struct RecoveryRoute {
        bool active;
        bytes32 surfaceId;
        address subProduct;
        address token;
        address destination;
        bool topUpPool; // 2a: plain top-up of the originating pool (destination == subProduct)
    }

    // ─── Events ──────────────────────────────────────────────────

    event ExitQueued(
        uint256 indexed id,
        address indexed originator,
        address indexed owner,
        address receiver,
        address token,
        uint128 amount,
        uint64 unlockAt,
        bytes32 surfaceId,
        address subProduct
    );
    event ExitExecuted(uint256 indexed id, address indexed receiver, address token, uint128 amount);
    event ExitResolvedToProtocol(
        uint256 indexed id, bytes32 indexed routeId, address destination, uint128 amount
    );
    event ExitResolvedByOwner(uint256 indexed id, address indexed destination, uint128 amount);
    event AccountBlocked(
        address indexed account, BlockState state, uint256 indexed triggerRequestId, bytes32 reasonHash
    );
    event AccountUnblocked(address indexed account, BlockState fromState);
    event RecoveryRouteSet(
        bytes32 indexed routeId,
        bytes32 surfaceId,
        address subProduct,
        address token,
        address destination,
        bool topUpPool
    );
    event RecoveryRouteRemoved(bytes32 indexed routeId);
    event AllowedSourceSet(address indexed source, bool allowed);
    event TopUpFeasibleSet(bytes32 indexed surfaceId, bool feasible);
    event MinimumDelaySet(uint32 seconds_);
    event SecurityPerimeterPausedSet(bool paused);
    event NativePusherSet(address indexed pusher);
    event SurplusSwept(address indexed token, address indexed to, uint256 amount);
    event AdminSet(address indexed admin);

    // ─── Custom errors ───────────────────────────────────────────

    error UnregisteredSource(address caller); //  onlyAllowedSource — DISTINCT record-path halt selector
    error ActorBlocked(address actor, BlockState state); // execution-gate revert (event: AccountBlocked)
    error NotExecutor(address caller); //         delivery: msg.sender ∉ {originator, owner, receiver} and the owner has no code; recovery: ∉ {originator, owner, receiver}
    error NotUnlocked(uint256 id, uint64 unlockAt);
    error QueuePaused();
    error AlreadyTerminal(uint256 id); //         status != Queued at a transition (also duplicate-batch-id)
    error UnknownRequest(uint256 id);
    error DelayBelowFloor(uint32 delay, uint32 floor);
    error AmountTooLarge(uint256 amount); //      uint256→uint128 narrowing guard
    error AmountMismatch(uint256 msgValue, uint256 amount); // native value-carrying
    error ReceivedAmountMismatch(address token, uint256 have, uint256 want); // pull / measured-delta proof
    error ZeroAmount();
    error RouteInactive(bytes32 routeId);
    error RouteProvenanceMismatch(uint256 id, bytes32 routeId);
    error TopUpInfeasibleSurface(bytes32 surfaceId); // setRecoveryRoute topUpPool guard
    error TopUpDestinationMismatch(address destination, address subProduct); // top-up must pay its own pool
    error SourceNotBlacklisted(address src); //   Leg-2 OR-predicate not satisfied
    error NotBlacklisted(address a); //           unblacklist / downgradeToFrozen on a non-Blacklisted address
    error NotFrozen(address a); //                unfreeze on a non-Frozen address
    error AlreadyBlacklisted(address a); //       evidence-free freeze over a Blacklisted address
    error NotResolvableByOwner(uint256 id); //    Leg-3: no blacklisted party on the request
    error UnwrapNonWrbtc(); //                    unwrapOnDelivery set on a non-WRBTC token (guard)
    error InvalidAltReceiver(address altReceiver); // recoverStuckExit altReceiver ∈ {0,this,token,wrbtc}
    error InvalidReceiver(address receiver); //   ingress: the queue itself, or WRBTC when delivery sends native RBTC
    error SelfOnly(); //                          payoutExternal trampoline is self-call-only
    error ZeroAddress();
    error EmptyIds();
    error SweepToZero();
    error SolvencyViolated(); //                  post-transfer balance < totalEscrowed
    error NotAdminOrOwner(address caller); //     onlyAdminOrOwner
    error OwnershipCannotBeRenounced(); //        renounceOwnership disabled
    error UpgradeImplZero(); //                   UUPS _authorizeUpgrade guard
    error InvalidDestination(address destination); // resolveByOwner / setRecoveryRoute destination guard

    // ─── Ingress ──────────────────────────────────────────

    /// @dev CALLER-SIDE NARROWING PRECONDITION. Every
    ///      `record*` takes `amount` as a **`uint128`**, deliberately NOT widened
    ///      to `uint256`. The Perimeter hook computes the user leg as a `uint256` and
    ///      MUST narrow it (`uint128(userAmount)`) at the call site; that narrowing
    ///      is the caller's responsibility and MUST be preceded by the caller's own
    ///      `require(userAmount <= type(uint128).max)` (`AmountTooLarge`) so a value
    ///      that would silently truncate is rejected UPSTREAM, before any escrow
    ///      accounting. The queue itself CANNOT re-assert this on an
    ///      already-`uint128` argument — the `AmountTooLarge` error is declared for
    ///      that CALLER-side hook boundary, not re-checked here. Keeping
    ///      the ABI at `uint128` also packs `amount` into `ExitRequest` word 1
    ///       — widening would cost a whole extra storage word per request.

    function recordERC20Exit(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver,
        bool unwrapOnDelivery
    ) external returns (uint256 id);

    function recordReceivedERC20Exit(
        address token,
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external returns (uint256 id);

    function recordNativeExit(
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external payable returns (uint256 id);

    function recordReceivedNativeExit(
        uint128 amount,
        uint32 delaySeconds,
        bytes32 surfaceId,
        address subProduct,
        address effOrig,
        address effOwner,
        address receiver
    ) external returns (uint256 id);

    // ─── Execution ───────────────────────────────────────────────

    /// @notice Pay an unlocked request to its recorded receiver. Who may call:
    ///         the request's originator, owner or receiver, always; ANYONE, when
    ///         the recorded owner has code at the moment of this call (a contract,
    ///         or a wallet that has delegated to code), because a contract owner
    ///         cannot press the button itself. The owner's code is read when delivery is called,
    ///         not when the request was recorded. Whoever calls, the money goes
    ///         only to the recorded receiver, and the call reverts while the
    ///         originator, the owner or the receiver is frozen or blacklisted. A
    ///         caller who is not a party must not be frozen or blacklisted either.
    ///         Blocking whoever presses deliver does not hold a contract-owned
    ///         request — block a recorded party to hold it. Reverts while the
    ///         queue is paused or the request is still locked.
    function executeExit(uint256 requestId) external;

    /// @notice `executeExit` for several ids in one call, with the same rule
    ///         applied to each id: parties always, anyone when that request's
    ///         owner has code, never a blocked caller. Atomic: one id that fails
    ///         reverts the whole batch. Blocking whoever presses deliver does not
    ///         hold a contract-owned request — block a recorded party to hold it.
    function executeExits(uint256[] calldata ids) external;

    /// @notice Verify-by-attempting stuck-exit recovery. Callable by the
    ///         request's originator, its owner, or its recorded receiver,
    ///         whether or not the owner has code. Unlike delivery, this call is
    ///         never widened to anyone when the owner has code: delivery pays
    ///         only the recorded receiver, while this call names a destination,
    ///         so opening it that way would let a stranger take a contract-owned
    ///         request whose receiver refuses payment.
    ///         Requires the request Queued, unlocked, and the queue not paused.
    ///
    ///         Attempts the STORED-receiver payout FIRST; pays `altReceiver` ONLY if
    ///         the stored-receiver attempt fails, including out-of-gas. There is
    ///         NO stored failure flag. If
    ///         `altReceiver` also fails, the whole call reverts (funds stay Queued).
    ///
    ///         Block gate covers ALL FOUR actors — `{originator, owner, STORED
    ///         receiver, altReceiver}`: a blocked/hacked original receiver refuses
    ///         recovery entirely (→ Leg-3), preserving the blacklist trap and
    ///         leaving no receiver-only dead end. `altReceiver` is guarded: reverts
    ///         if it is `0`, this contract, the request token, or WRBTC. The stored
    ///         request is NEVER re-targeted (`altReceiver` is a payout-time
    ///         destination only), so request immutability and the block gate still
    ///         hold.
    ///
    ///         GAS: the caller's gas limit is the budget for the stored-receiver
    ///         attempt. An underfunded attempt can redirect a receiver that would
    ///         accept payment with more gas. The EVM keeps 1/64 back from
    ///         the attempt, which is what pays `altReceiver` when the receiver
    ///         consumes everything — so supply enough for both legs.
    function recoverStuckExit(uint256 id, address altReceiver) external;

    // ─── Block model ─────────────────────────────────────────────

    function freezeFromRequest(uint256 requestId, bool freezeReceiver, bytes32 reasonHash) external;
    function blacklistFromRequest(uint256 requestId, bool freezeReceiver, bytes32 reasonHash) external;

    // Batch by-request-id — whole-batch atomic (one bad
    // id reverts all, like executeExits); last-write-wins trigger/reason per
    // address when the same address is blocked by more than one id in the batch.
    function freezeFromRequest(uint256[] calldata requestIds, bool freezeReceiver, bytes32 reasonHash)
        external;
    function blacklistFromRequest(uint256[] calldata requestIds, bool freezeReceiver, bytes32 reasonHash)
        external;

    /// @notice Flat block levers. They carry no evidence, so a `freeze` over an
    ///         address that is already Blacklisted would change nothing and record
    ///         nothing: it reverts `AlreadyBlacklisted` rather than answering with
    ///         a success that reads as "this address is now frozen". The
    ///         by-request levers above carry a trigger and a reason, so they stay
    ///         unconditional on a known id — over a Blacklisted party they hold the
    ///         stronger state, record the new evidence, and announce Blacklisted.
    function freeze(address a) external;
    function blacklist(address a) external;
    function unfreeze(address a) external;
    function unblacklist(address a) external;

    /// @notice Move a Blacklisted address down to Frozen in one call — the
    ///         remedy for an address blacklisted in haste that should only be held
    ///         while it is investigated. There is no window in which the address is
    ///         unblocked, unlike unblacklist-then-freeze. Reverts `NotBlacklisted`
    ///         on any other state; the recorded trigger is kept, because a
    ///         downgrade means "still under investigation", not "exonerated".
    function downgradeToFrozen(address a) external;

    // Batch by-address: each reverts `EmptyIds()` on
    // an empty array, for API consistency with the by-id batch variants
    // (`executeExits` / batch `freezeFromRequest` / `resolveToProtocol` /
    // `resolveByOwner`) — an empty batch is a caller mistake, never a silent no-op.
    function freeze(address[] calldata a) external;
    function blacklist(address[] calldata a) external;
    function unfreeze(address[] calldata a) external;
    function unblacklist(address[] calldata a) external;
    function downgradeToFrozen(address[] calldata a) external;

    // ─── Pause ───────────────────────────────────────────────────

    /// @notice Pause or resume the queue. Admin or Owner.
    ///         A pause stops `executeExit`, `executeExits` and `recoverStuckExit`
    ///         for every caller — the originator, the owner, and anyone
    ///         delivering a contract-owned request — so while it holds users have
    ///         no path of their own to their money.
    ///         It does not stop ingress: the four `record*` functions keep
    ///         escrowing new withdrawals. It does not stop the block levers, the
    ///         Admin-or-Owner `resolveToProtocol` (still bound to a blacklisted
    ///         originator or owner and a matching active route), or the Owner's
    ///         `resolveByOwner`, which reaches only requests with a blacklisted
    ///         party whether or not the queue is paused.
    function setSecurityPerimeterPaused(bool p) external;

    // ─── Recovery ────────────────────────────────────────────────

    function resolveToProtocol(uint256[] calldata ids, bytes32 routeId) external;
    function resolveByOwner(uint256[] calldata ids, address destination) external;

    function setRecoveryRoute(RecoveryRoute calldata route) external returns (bytes32 routeId);
    function removeRecoveryRoute(bytes32 routeId) external;
    function setTopUpFeasible(bytes32 surfaceId, bool feasible) external;

    // ─── Config ──────────────────────────────────────────

    function addAllowedSource(address src) external;
    function removeAllowedSource(address src) external;
    function setNativePusher(address pusher) external;
    function setAdmin(address newAdmin) external;
    function setMinimumDelaySeconds(uint32 s) external;
    function sweepSurplus(address token, address to) external;

    // ─── Views ───────────────────────────────────────────────────

    // `payoutExternal` is deliberately not declared here: it is the
    // `SelfOnly`-guarded self-call trampoline `recoverStuckExit` uses for its
    // catchable payout attempt, not a member of the external ABI a
    // caller or client is meant to use.

    function getRequest(uint256 id) external view returns (ExitRequest memory);
    function getActive(address party, uint256 cursor, uint256 n)
        external
        view
        returns (uint256[] memory ids, uint256 nextCursor);
    function blockStateOf(address a) external view returns (BlockState);

    /// @notice The fast operational guardian checked by `onlyAdminOrOwner`.
    function admin() external view returns (address);

    /// @notice Monotonic id source; the first recorded id is 1.
    function lastRequestId() external view returns (uint256);

    /// @notice The registered native pusher recorded as ingress provenance.
    function nativePusher() external view returns (address);

    /// @notice The per-request delay floor enforced at ingress.
    function minimumDelaySeconds() external view returns (uint32);

    /// @notice Whether the queue currently pays nobody through the
    ///         user-facing legs.
    function securityPerimeterPaused() external view returns (bool);

    /// @notice The canonical WRBTC address used to guard and unwrap
    ///         `unwrapOnDelivery` requests.
    function wrbtc() external view returns (address);

    /// @notice Enumerate registered recovery route ids.
    function recoveryRouteIds() external view returns (bytes32[] memory);

    /// @notice Whether a topUpPool route may be registered for `surfaceId`.
    function topUpFeasible(bytes32 surfaceId) external view returns (bool);

    /// @notice Whether `src` is a registered ingress source.
    function isAllowedSource(address src) external view returns (bool);

    /// @notice Paginate the blocked set (Frozen ∪ Blacklisted).
    /// @param offset First index into the blocked set to return.
    /// @param limit  Requested page size; clamped to `MAX_GET_ACTIVE_PAGE` (500).
    /// @return page  The clamped slice `[offset, offset + page.length)` of the
    ///               blocked set (empty when `offset >= total` or `limit == 0`).
    /// @return total The FULL blocked-set size (EnumerableSet length), independent
    ///               of `offset`/`limit` — so a caller/monitor knows the whole
    ///               range ("showing offset..offset+page.length of total") and
    ///               never silently undercounts past the 500-entry page cap.
    function blockedAccounts(uint256 offset, uint256 limit)
        external
        view
        returns (address[] memory page, uint256 total);
    function blockTrigger(address a) external view returns (uint256);

    function totalEscrowed(address token) external view returns (uint256);
    function getRecoveryRoute(bytes32 routeId) external view returns (RecoveryRoute memory);
    function allowedSources() external view returns (address[] memory);

    /// @notice Max page size for the paginated `getActive` / `blockedAccounts`
    ///         views. Public constant, so paging is
    ///         self-describing on-chain (500).
    function MAX_GET_ACTIVE_PAGE() external view returns (uint256);
}

src/interfaces/IExitDelayQueueHost.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title  IExitDelayQueueHost — the queue-pointer surface a product host exposes
/// @notice Minimal interface for the `setExitDelayQueue` pointer.
///         Each product storage host — the `sovrynProtocol` singleton (lending +
///         loan/margin) and the Zero `BorrowerOperations` proxy — holds its OWN
///         queue address in a NEW EIP-1967-style unstructured slot
///         `keccak256("sovryn.perimeterExitDelayQueue") - 1`, set by `setExitDelayQueue`
///         (gated by the SAME host admin as `setExitFeeController`, Owner/Timelock,
///         and rotatable) and read back via `exitDelayQueue()`.
///
/// @dev    The host CONTRACTS live in the product repos (Sovryn-smart-contracts-perimeter
///         / zero-contracts-perimeter) on the 0.5.x / 0.6.x pragmas; this 0.8.20 stub
///         exists ONLY so the perimeter deploy/wire script (05) can call the pointer
///         setter and read it back over the cross-pragma ABI when the host addresses
///         are supplied. It intentionally declares nothing else — the queue itself
///         is never a host and never implements this.
interface IExitDelayQueueHost {
    /// @notice Point this host's exit-delay reroute at `queue` (wire/rotate).
    ///         Owner/Timelock-gated on the host; a no-op in perimeter (hosts are external).
    function setExitDelayQueue(address queue) external;

    /// @notice The host's current queue pointer (0 = reroute unwired ⇒ direct pay).
    function exitDelayQueue() external view returns (address);
}

src/interfaces/IExitFeeController.sol.content:
// SPDX-License-Identifier: MIT
// Range pragma is intentional: this one file must compile under Solidity
// 0.5.17, 0.6.11, and 0.8.20 -- the three compilers that consume it.
// aderyn-ignore-next-line(unspecific-solidity-pragma)
pragma solidity >=0.5.17 <0.9.0;
// `pragma experimental ABIEncoderV2;` is required for the 0.5.17 leg — that
// compiler needs the directive to emit/decode struct returns (ExitFeeQuote)
// across the ABI boundary. The modern `pragma abicoder v2;` was only added
// in 0.7.4 and is incompatible with 0.5.x, so the experimental pragma is the
// only spelling that works across all three target compilers. On 0.6+/0.8+
// the experimental pragma is accepted (silently on 0.6.x; with a deprecation
// notice on 0.8.x that does NOT enable the historical encoder bugs — those
// bugs were fixed long before 0.6.0). This is a pure interface (no
// implementation, no storage), so there is no exposure to encoder-bug
// surface area beyond the ABI itself. Removing it would mean shipping one
// interface file per pragma, which is exactly the drift this file avoids.
// aderyn-ignore-next-line(experimental-encoder)
pragma experimental ABIEncoderV2;

/// @title  IExitFeeController
/// @notice Cross-pragma interface for the ExitFee (Perimeter) controller. One
///         file for every consumer on 0.5.17, 0.6.11, and 0.8.20. Consumers
///         on 0.4.26 use the structurally-different variant in `v0_4/`,
///         which must stay ABI-identical to this file.
interface IExitFeeController {
    // ─── Types ────────────────────────────────────────────────────────────

    /// @notice Reason a `ExitFeeSkipped` event was emitted instead of an
    ///         `ExitFeeApplied`. NONE covers honest paths (positive charge,
    ///         dust, or actor-exemption); the rest cover off-state outcomes.
    enum SkipReason {
        NONE, // Controller computed an honest quote (charge / dust / zero-rate).
        INACTIVE, // exitFeeEnabled == false.
        DISABLED, // feeReceiver == address(0), OR surface gate off.
        INVALID_QUOTE, // Defensive: overflow or fee > gross.
        CONTROLLER_REVERT, // Set by the product's local _safeQuote on staticcall failure.
        VAULT_REVERT // Set by the product hook when the fee transfer itself failed.

    }

    /// @notice A single rate-policy entry. Lives at each of the three tiers
    ///         (actor → sub-product → surface).
    struct RatePolicy {
        bool active;
        uint16 rateBps;
    }

    /// @notice A single delay-bypass entry (the DELAY feature). Lives
    ///         at each of the three bypass tiers (actor → sub-product → surface),
    ///         mirroring `RatePolicy`'s shape.
    ///
    ///         `active == false` ⇒ the tier is not configured; resolution falls
    ///         through to the next-broader tier. `active == true` ⇒ this tier
    ///         decides: `bypass == true` exempts the exit (`d = 0`, instant),
    ///         `bypass == false` FORCES the global delay (overriding a broader
    ///         bypass). It is a bypass/exemption toggle only — there is NO
    ///         per-instance delay *duration* (a single `globalDelaySeconds`
    ///         applies whenever a delay is imposed).
    struct DelayBypassPolicy {
        bool active;
        bool bypass;
    }

    /// @notice Quote returned by `quoteExitFee`. `reason` carries the precise
    ///         off-state code; `active` is the resolved policy state (true iff
    ///         a RatePolicy.active entry was used and reason ∈ {NONE}).
    struct ExitFeeQuote {
        bool active;
        uint16 rateBps;
        uint256 feeAmount;
        uint256 netAmount;
        address feeReceiver;
        uint8 reason;
    }

    // ─── Events ───────────────────────────────────────────────────────────

    event ExitFeeEnabledSet(bool enabled);
    event FeeReceiverSet(address indexed feeReceiver);
    event SurfacePolicySet(bytes32 indexed surfaceId, bool active, uint16 rateBps);
    event SubProductPolicySet(
        bytes32 indexed surfaceId, address indexed subProduct, bool active, uint16 rateBps
    );
    event ActorPolicySet(bytes32 indexed surfaceId, address indexed actor, bool active, uint16 rateBps);
    event SubProductPolicyRemoved(bytes32 indexed surfaceId, address indexed subProduct);
    event ActorPolicyRemoved(bytes32 indexed surfaceId, address indexed actor);

    // ─── Events (delay extension) ─────────────────────────────────────

    event AdminSet(address indexed admin);
    event SecurityPerimeterEnabledSet(bool enabled);
    event GlobalDelaySet(uint32 seconds_);
    event SurfaceBypassSet(bytes32 indexed surfaceId, bool active, bool bypass);
    event SurfaceBypassRemoved(bytes32 indexed surfaceId);
    event SubProductBypassSet(
        bytes32 indexed surfaceId, address indexed subProduct, bool active, bool bypass
    );
    event ActorBypassSet(bytes32 indexed surfaceId, address indexed actor, bool active, bool bypass);
    event SubProductBypassRemoved(bytes32 indexed surfaceId, address indexed subProduct);
    event ActorBypassRemoved(bytes32 indexed surfaceId, address indexed actor);

    // ─── Quote ────────────────────────────────────────────────────────────

    /// @notice Resolve the fee policy for `(surfaceId, subProduct, actor)` and
    ///         compute the fee on `grossAmount`. Reads only; never reverts on
    ///         policy lookups (returns active=false with a SkipReason instead).
    ///         May revert only on internal arithmetic invariants (caught by
    ///         the product's local _safeQuote helper as CONTROLLER_REVERT).
    function quoteExitFee(bytes32 surfaceId, address subProduct, address actor, uint256 grossAmount)
        external
        view
        returns (ExitFeeQuote memory);

    // ─── Delay quote (hook entry) ─────────────────────────────────────

    /// @notice The delay hook's SINGLE hot-path entry. Short-circuits
    ///         the kill switch FIRST: when `securityPerimeterEnabled == false` it
    ///         returns `(0, rawOriginator, owner)` WITHOUT consulting the bypass
    ///         tiers or the escrow queue (the liveness escape). Otherwise it
    ///         quotes the delay on the originator and returns the originator and
    ///         owner unchanged, so the quote and the record share ONE identity.
    ///         The hook MUST ignore `effOrig`/`effOwner` and pay direct whenever
    ///         `d == 0`.
    /// @param  rawOriginator The withdrawal caller.
    /// @param  owner         The position owner (iToken holder / borrower / trove).
    /// @param  receiver      The immutable payout destination (not consulted).
    /// @param  surfaceId     Operation-kind identifier (see fee tiers).
    /// @param  subProduct    Per-instance address (iToken / converter / 0).
    /// @return d       Delay seconds to escrow for (0 ⇒ off / inactive / bypassed).
    /// @return effOrig The originator, unchanged.
    /// @return effOwner The owner, unchanged.
    function quoteExitDelayFor(
        address rawOriginator,
        address owner,
        address receiver,
        bytes32 surfaceId,
        address subProduct
    ) external view returns (uint32 d, address effOrig, address effOwner);

    /// @notice Inner per-actor delay view (off / inactive / bypass ⇒ 0, else
    ///         `globalDelaySeconds`), evaluated on the actor passed — the
    ///         originator, as `quoteExitDelayFor` does.
    ///         Handles the disabled-perimeter case identically (returns 0 when
    ///         the perimeter is off). Hot-path callers use `quoteExitDelayFor`;
    ///         this is for off-chain quoting and the inner resolver.
    /// @param  surfaceId       Operation-kind identifier.
    /// @param  subProduct      Per-instance address (iToken / converter / 0).
    /// @param  effectiveActor  The actor to resolve for.
    /// @return The delay seconds resolved by the 3-tier bypass resolver.
    function quoteExitDelay(bytes32 surfaceId, address subProduct, address effectiveActor)
        external
        view
        returns (uint32);

    // ─── State views ──────────────────────────────────────────────────────

    function exitFeeEnabled() external view returns (bool);
    function feeReceiver() external view returns (address);
    function surfacePolicy(bytes32 surfaceId) external view returns (RatePolicy memory);
    function subProductPolicy(bytes32 surfaceId, address subProduct)
        external
        view
        returns (RatePolicy memory);
    function actorPolicy(bytes32 surfaceId, address actor) external view returns (RatePolicy memory);
    function subProductKeys(bytes32 surfaceId) external view returns (address[] memory);
    function actorKeys(bytes32 surfaceId) external view returns (address[] memory);

    // ─── State views (delay extension) ──────────────────────────────────────

    function admin() external view returns (address);
    function securityPerimeterEnabled() external view returns (bool);
    function globalDelaySeconds() external view returns (uint32);
    function surfaceBypass(bytes32 surfaceId) external view returns (DelayBypassPolicy memory);
    function subProductBypass(bytes32 surfaceId, address subProduct)
        external
        view
        returns (DelayBypassPolicy memory);
    function actorBypass(bytes32 surfaceId, address actor) external view returns (DelayBypassPolicy memory);

    /// @notice Every surfaceId ever configured in the surface-tier delay-bypass
    ///         index. NOTE: this getter takes NO argument — surface
    ///         bypasses are keyed by `surfaceId` alone and are NOT scoped by a
    ///         parent surface. Backed by an `EnumerableSet.Bytes32Set` so
    ///         `InspectController` / monitoring can dump every surface bypass with
    ///         no unenumerable zero-delay state. Same soft-retire retention as the
    ///         other key-sets: entries persist on `{active:false}`; use
    ///         `removeSurfaceBypass` for hard removal.
    function surfaceBypassKeys() external view returns (bytes32[] memory);
    function subProductBypassKeys(bytes32 surfaceId) external view returns (address[] memory);
    function actorBypassKeys(bytes32 surfaceId) external view returns (address[] memory);

    /// @notice ANY-TIER-TOUCHED master set: every surfaceId that
    ///         carries a delay-bypass entry at ANY tier — surface, sub-product, OR
    ///         actor. Recorded from all three writers, so a surface with ONLY a
    ///         sub-product- or actor-tier bypass (the most common exemption shape)
    ///         is enumerable even though it was never passed to
    ///         `setSurfaceBypass`. This is the discovery driver `InspectController`
    ///         uses so NO zero-delay config under an arbitrary surfaceId is
    ///         invisible. Retention-only (entries never dropped).
    function bypassSurfaceIds() external view returns (bytes32[] memory);

    // ─── Admin ────────────────────────────────────────────────────────────

    /// @notice `onlyAdminOrOwner`:
    ///         the fee kill switch and receiver re-point are operational
    ///         levers shared with the Admin guardian. Every other setter in
    ///         this section is Owner-only.
    function setExitFeeEnabled(bool enabled) external;
    function setFeeReceiver(address newReceiver) external;
    function setSurfacePolicy(bytes32 surfaceId, RatePolicy calldata policy) external;
    function setSubProductPolicy(bytes32 surfaceId, address subProduct, RatePolicy calldata policy)
        external;
    function setSubProductPolicies(
        bytes32 surfaceId,
        address[] calldata subProducts,
        RatePolicy[] calldata policies
    ) external;
    function setActorPolicy(bytes32 surfaceId, address actor, RatePolicy calldata policy) external;
    function setActorPolicies(bytes32 surfaceId, address[] calldata actors, RatePolicy[] calldata policies)
        external;
    function removeSubProductPolicy(bytes32 surfaceId, address subProduct) external;
    function removeSubProductPolicies(bytes32 surfaceId, address[] calldata subProducts) external;
    function removeActorPolicy(bytes32 surfaceId, address actor) external;
    function removeActorPolicies(bytes32 surfaceId, address[] calldata actors) external;

    // ─── Admin (delay extension) ────────────────────────────────────────────

    /// @notice Rotate the fast operational guardian (`Admin`). Owner-only.
    ///         MAY equal the Owner -- nothing requires the two to be distinct.
    ///         The only delay principal on the controller; there is no OZ
    ///         AccessControl role.
    function setAdmin(address newAdmin) external;

    /// @notice Flip the global delay kill switch. `onlyAdminOrOwner` in both
    ///         directions, for sub-minute incident response. Independent of
    ///         `exitFeeEnabled`.
    function setSecurityPerimeterEnabled(bool enabled) external;

    /// @notice Set the single global delay applied whenever a delay is imposed.
    ///         Owner-only. The `>= minimumDelaySeconds` floor is a liveness
    ///         invariant enforced PER-REQUEST in the queue, not here -- the
    ///         controller never reads or calls the queue.
    function setGlobalDelaySeconds(uint32 seconds_) external;

    function setSurfaceBypass(bytes32 surfaceId, DelayBypassPolicy calldata policy) external;

    /// @notice Hard-remove a surface-tier delay bypass: clears the stored policy
    ///         and drops the surfaceId from the enumeration index. Idempotent.
    function removeSurfaceBypass(bytes32 surfaceId) external;

    function setSubProductBypass(bytes32 surfaceId, address subProduct, DelayBypassPolicy calldata policy)
        external;

    function setSubProductBypasses(
        bytes32 surfaceId,
        address[] calldata subProducts,
        DelayBypassPolicy[] calldata policies
    ) external;

    function setActorBypass(bytes32 surfaceId, address actor, DelayBypassPolicy calldata policy) external;

    function setActorBypasses(
        bytes32 surfaceId,
        address[] calldata actors,
        DelayBypassPolicy[] calldata policies
    ) external;

    function removeSubProductBypass(bytes32 surfaceId, address subProduct) external;

    function removeSubProductBypasses(bytes32 surfaceId, address[] calldata subProducts) external;

    function removeActorBypass(bytes32 surfaceId, address actor) external;

    function removeActorBypasses(bytes32 surfaceId, address[] calldata actors) external;

    /// @notice Withdraw an actor-tier exemption in one call: the fee entry
    ///         inactive (sub-product or surface policy applies), the delay entry active with no
    ///         bypass (delayed whatever a wider tier says). Owner-only.
    function revokeExemption(bytes32 surfaceId, address actor) external;

    /// @notice Grant an actor-tier exemption in one call: the fee entry
    ///         {active: true, rateBps: 0}, the delay entry {active: true,
    ///         bypass: true} — both halves together, never one without the
    ///         other. Owner-only.
    function grantExemption(bytes32 surfaceId, address actor) external;
}

src/interfaces/IExitFeeControllerHost.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title  IExitFeeControllerHost — the controller-pointer surface a product host exposes
/// @notice Minimal interface for the `exitFeeController` pointer read.
///         Each product storage host — the `sovrynProtocol` singleton (lending +
///         loan/margin) and the Zero `BorrowerOperations` proxy — holds its OWN
///         controller address in a NEW EIP-1967-style unstructured slot
///         `keccak256("sovryn.perimeterExitFeeController") - 1`, set by `setExitFeeController`
///         (gated by the SAME host admin as `setExitDelayQueue`, Owner/Timelock,
///         and rotatable) and read back via `exitFeeController()`.
///
/// @dev    The host CONTRACTS live in the product repos (Sovryn-smart-contracts-perimeter
///         / zero-contracts-perimeter) on the 0.5.x / 0.6.x pragmas; this 0.8.20 stub
///         exists ONLY so the perimeter go-live gate (06) can read the pointer back
///         over the cross-pragma ABI when the host addresses are supplied. It
///         intentionally declares nothing else — the controller itself is never a
///         host and never implements this.
interface IExitFeeControllerHost {
    /// @notice The host's current controller pointer (0 = unwired ⇒ fee/delay
    ///         quote is skipped, exit pays direct).
    function exitFeeController() external view returns (address);
}

src/interfaces/IExitFeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

/// @title  IExitFeeVault
/// @notice Passive holder for collected ExitFee balances. Consumed only by
///         the controller's own 0.8.20 tests and the deploy/sweep scripts —
///         the home repos don't import this file. ERC20 and native RBTC are
///         both supported via separate `sweep*` paths; the vault itself never
///         pulls — it only releases on admin-signed sweep calls.
interface IExitFeeVault {
    event Swept(address indexed asset, address indexed to, uint256 amount);
    event RBTCSwept(address indexed to, uint256 amount);
    event DefaultRecipientSet(address indexed previous, address indexed current);
    event AdminSet(address indexed admin);

    /// @notice Appoint (or rotate) the operational guardian admitted by the
    ///         vault's `onlyAdminOrOwner` gate. Owner-only; reverts on
    ///         `address(0)`. May equal the owner.
    /// @param  newAdmin Non-zero address.
    function setAdmin(address newAdmin) external;

    /// @notice Set (or rotate) the default sweep recipient used by the
    ///         no-recipient sweep overloads. Reverts on `address(0)`.
    ///         Caller must be the admin or the owner.
    /// @param  newRecipient Non-zero address.
    function setDefaultRecipient(address newRecipient) external;

    /// @notice Sweep an ERC20 balance to `to`. Caller must be the admin or
    ///         the contract owner. With UUPS there is no separate
    ///         proxy-admin role -- ownership IS the authority for upgrades;
    ///         sweeps additionally admit the operational admin.
    function sweepERC20(address asset, address to, uint256 amount) external;

    /// @notice Sweep an ERC20 balance to `defaultRecipient`. Reverts with
    ///         `DefaultRecipientUnset` if the default has not been set.
    ///         Otherwise behaves like the 3-arg overload.
    function sweepERC20(address asset, uint256 amount) external;

    /// @notice Sweep native RBTC to `to`. Caller must be the admin or the
    ///         contract owner.
    function sweepRBTC(address payable to, uint256 amount) external;

    /// @notice Sweep native RBTC to `defaultRecipient`. Reverts with
    ///         `DefaultRecipientUnset` if the default has not been set.
    ///         Otherwise behaves like the 2-arg overload.
    function sweepRBTC(uint256 amount) external;
}

test/invariant/ExitDelayQueue.invariant..content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Test} from "forge-std/Test.sol";
import {ERC1967Proxy} from "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

import {ExitDelayQueue} from "../../src/ExitDelayQueue.sol";
import {IExitDelayQueue} from "../../src/interfaces/IExitDelayQueue.sol";
import {ExitDelayQueueHandler, InvMockERC20} from "./ExitDelayQueueHandler.sol";

/// @dev Minimal native-backed WRBTC for the invariant run (unused by the
///      handler's ingress but required by initialize()).
contract InvWRBTC {
    function withdraw(uint256) external {}
    receive() external payable {}
}

/// @notice Stateful invariant suite for `ExitDelayQueue` covering its
///         invariants. The handler (owner + source + pusher) fuzzes ingress,
///         execution, blocks, recovery, pause, sweep and time. Assertions read
///         ghost accounting + on-chain state.
contract ExitDelayQueueInvariant is Test {
    ExitDelayQueue queue;
    InvMockERC20 token;
    InvWRBTC wrbtc;
    ExitDelayQueueHandler handler;

    address constant ADMIN = address(0xAD);

    function setUp() public {
        wrbtc = new InvWRBTC();
        token = new InvMockERC20();

        ExitDelayQueue impl = new ExitDelayQueue();
        // The handler will be the owner; deploy with the test as temp owner then
        // hand off. Sources include the handler; admin is a distinct dummy.
        address[] memory sources = new address[](0);
        bytes memory init = abi.encodeWithSelector(
            ExitDelayQueue.initialize.selector, address(this), ADMIN, address(wrbtc), uint32(1 hours), sources
        );
        ERC1967Proxy proxy = new ERC1967Proxy(address(impl), init);
        queue = ExitDelayQueue(payable(address(proxy)));

        handler = new ExitDelayQueueHandler(queue, token, address(wrbtc));

        // Wire the handler as an allowed source + native pusher, then transfer
        // ownership to it so it can also exercise owner/admin-gated fns.
        queue.addAllowedSource(address(handler));
        queue.setNativePusher(address(handler));
        queue.transferOwnership(address(handler));
        vm.prank(address(handler));
        queue.acceptOwnership();

        // Leg-2 routes matching the handler's own ingress provenance, so the
        // recovery-away action is reachable from the first step of every run.
        handler.setUpRoutes();

        // target only the handler
        targetContract(address(handler));

        bytes4[] memory selectors = new bytes4[](22);
        selectors[0] = handler.recordErc20.selector;
        selectors[1] = handler.recordNative.selector;
        selectors[2] = handler.execute.selector;
        selectors[3] = handler.freeze.selector;
        selectors[4] = handler.blacklist.selector;
        selectors[5] = handler.unfreeze.selector;
        selectors[6] = handler.unblacklist.selector;
        selectors[7] = handler.pause.selector;
        selectors[8] = handler.resolveByOwner.selector;
        selectors[9] = handler.sweep.selector;
        selectors[10] = handler.warp.selector;
        //  coverage: measured-delta ingress + donation/force-send surplus.
        selectors[11] = handler.recordReceivedErc20.selector;
        selectors[12] = handler.recordReceivedNative.selector;
        selectors[13] = handler.donateErc20.selector;
        selectors[14] = handler.donateNative.selector;
        //  (C3): fuzz floor raises/lowers so the creation-time invariant is
        // exercised against live short requests without falsely tripping.
        selectors[15] = handler.setMinDelay.selector;
        // Gate-5 stuck-exit recovery: recoverStuckExit(id, altReceiver) must never
        // break solvency / double-spend, whichever branch it takes (stored-receiver
        // pay, altReceiver pay on a bounce, or whole-call revert on block/lock/pause).
        selectors[16] = handler.recoverStuck.selector;
        // Operator levers the release depends on: blocking by request id (with
        // and without the receiver), batch release, route registration and
        // recovery-away along a route.
        selectors[17] = handler.freezeByRequest.selector;
        selectors[18] = handler.blacklistByRequest.selector;
        selectors[19] = handler.executeMany.selector;
        selectors[20] = handler.addRoute.selector;
        selectors[21] = handler.resolveByRoute.selector;
        targetSelector(FuzzSelector({addr: address(handler), selectors: selectors}));
    }

    // Per-token solvency — totalEscrowed == Σ Queued amounts, and
    // ≤ backing balance. Ghost sum tracks Σ Queued.
    function invariant_solvency_erc20() public view {
        assertEq(queue.totalEscrowed(address(token)), handler.ghostQueuedErc20());
        assertLe(queue.totalEscrowed(address(token)), token.balanceOf(address(queue)));
    }

    function invariant_solvency_native() public view {
        assertEq(queue.totalEscrowed(address(0)), handler.ghostQueuedNative());
        assertLe(queue.totalEscrowed(address(0)), address(queue).balance);
    }

    //  ids monotonic and never reused (lastRequestId only grows; every
    // recorded id ≤ lastRequestId and unique by construction of ++lastRequestId).
    function invariant_id_monotonic() public view {
        assertEq(queue.lastRequestId(), handler.totalRecorded());
    }

    // A request leaves Queued at most once. Every id is in exactly
    // one of {Queued, terminal}; terminal count never exceeds recorded count.
    function invariant_no_double_terminal() public view {
        assertLe(handler.totalTerminal(), handler.totalRecorded());
    }

    // Delay floor holds at creation time, and active-index membership
    // biconditional (Queued ⇔ in set), across all live ids. Metadata recorded
    // at creation is pinned separately, in invariant_request_metadata_immutable
    // below.
    function invariant_status_and_index_consistency() public view {
        uint256 n = handler.liveIdCount();
        for (uint256 i = 0; i < n; ++i) {
            uint256 id = handler.liveIdAt(i);
            IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
            //  (creation-time, C3): every request satisfies
            // `unlockAt − createdAt ≥ the minimumDelaySeconds in effect at ITS OWN
            // createdAt` (the floor is enforced once, at record time). We check
            // against the handler's recorded floor-at-creation, NOT the current
            // live floor — a later setMinimumDelaySeconds raise applies only to NEW
            // requests and must never retroactively extend an already-Queued exit,
            // so asserting against the live floor would falsely trip after a raise.
            assertGe(uint256(r.unlockAt) - uint256(r.createdAt), uint256(handler.floorAtCreation(id)));
            // for each recorded party (originator, owner, receiver), id ∈ active
            // iff Queued.
            bool inSet = _inActive(r.originator, id);
            if (r.status == IExitDelayQueue.ExitStatus.Queued) {
                assertTrue(inSet, "queued id must be in originator active set");
                assertTrue(_inActive(r.owner, id), "queued id must be in owner active set");
                assertTrue(_inActive(r.receiver, id), "queued id must be in receiver active set");
            } else {
                assertFalse(inSet, "terminal id must NOT be in originator active set");
                assertFalse(_inActive(r.owner, id), "terminal id must NOT be in owner active set");
                assertFalse(_inActive(r.receiver, id), "terminal id must NOT be in receiver active set");
            }
        }
    }

    /// @notice A recorded request's originator, owner, receiver, token, amount,
    ///         surfaceId, subProduct, unwrapOnDelivery, createdAt and unlockAt
    ///         never change after the request is created — only `status` may
    ///         move. Checked against the handler's own snapshot, taken by
    ///         reading the request straight back off the queue in the same call
    ///         that recorded it, for every id the handler has ever recorded.
    function invariant_request_metadata_immutable() public view {
        uint256 n = handler.liveIdCount();
        for (uint256 i = 0; i < n; ++i) {
            uint256 id = handler.liveIdAt(i);
            IExitDelayQueue.ExitRequest memory live = queue.getRequest(id);
            IExitDelayQueue.ExitRequest memory recorded = handler.recordedAt(id);
            assertEq(live.originator, recorded.originator, "originator changed after record");
            assertEq(live.owner, recorded.owner, "owner changed after record");
            assertEq(live.receiver, recorded.receiver, "receiver changed after record");
            assertEq(live.token, recorded.token, "token changed after record");
            assertEq(uint256(live.amount), uint256(recorded.amount), "amount changed after record");
            assertEq(live.surfaceId, recorded.surfaceId, "surfaceId changed after record");
            assertEq(live.subProduct, recorded.subProduct, "subProduct changed after record");
            assertEq(live.unwrapOnDelivery, recorded.unwrapOnDelivery, "unwrapOnDelivery changed after record");
            assertEq(uint256(live.createdAt), uint256(recorded.createdAt), "createdAt changed after record");
            assertEq(uint256(live.unlockAt), uint256(recorded.unlockAt), "unlockAt changed after record");
        }
    }

    // ── operator levers ──────────────────────────────────────────

    /// @notice No payout ever reached a party the perimeter had blocked. Both
    ///         payout legs feed the same ledger: the handler snapshots
    ///         `blockStateOf` for originator, owner and receiver immediately
    ///         before every `executeExit`/`executeExits`, and for those three
    ///         plus `altReceiver` before every `recoverStuckExit` — the stricter
    ///         gate that leg carries. A payout taken while any of them was
    ///         Frozen or Blacklisted is recorded, not filtered out.
    function invariant_blocked_party_never_paid() public view {
        assertEq(handler.blockedPayouts(), 0, "a release paid out while a party was blocked");
        assertEq(handler.blockedPayoutValue(), 0, "value left the queue while a party was blocked");
        assertEq(handler.blockedPayoutParty(), address(0), "blocked party was paid");
        // Every credit in the ledger names one of the three known actors: the
        // stored receiver is immutable and the recovery leg's alternate is drawn
        // from the same set, so no payout can land outside it.
        uint256 credited;
        for (uint256 i = 0; i < 3; ++i) {
            credited += handler.paidTo(handler.actors(i));
        }
        assertEq(credited, handler.paidTotal(), "a release paid an address that is not a request party");
    }

    /// @notice A paused perimeter pays nobody, down either payout leg. The
    ///         handler snapshots `securityPerimeterPaused()` before each release
    ///         and each stuck-exit recovery, and counts any payout that still
    ///         went through.
    function invariant_pause_stops_payouts() public view {
        assertEq(handler.pausedPayouts(), 0, "a payout went through while the perimeter was paused");
    }

    /// @notice Recovery-away along a route only ever moved funds whose
    ///         originator or owner was Blacklisted, and every id it moved is
    ///         terminal in exactly that state.
    function invariant_route_resolution_requires_blacklist() public view {
        assertEq(
            handler.routeResolutionsWithoutBlacklist(),
            0,
            "a route resolved funds with no blacklisted source party"
        );
        assertEq(handler.unauthorizedRouteResolutionId(), 0, "unauthorized route resolution");
        uint256 n = handler.routeResolvedIdCount();
        for (uint256 i = 0; i < n; ++i) {
            uint256 id = handler.routeResolvedIdAt(i);
            assertTrue(handler.resolvedByRoute(id), "route ledger missing an id it resolved");
            assertEq(
                uint256(queue.getRequest(id).status),
                uint256(IExitDelayQueue.ExitStatus.ResolvedToProtocol),
                "route-resolved id is not ResolvedToProtocol"
            );
        }
    }

    /// @notice Blocking by request id blocks exactly that request's parties:
    ///         originator and owner always land at least as hard-blocked as
    ///         asked, the receiver lands blocked when and only when the caller
    ///         flagged it, and an unflagged receiver that is not itself a source
    ///         party is left untouched. Measured by the handler the moment the
    ///         call returns, because a later unfreeze may legitimately clear it.
    function invariant_by_request_block_matches_parties() public view {
        assertEq(handler.byRequestPartyMisses(), 0, "by-request block left a source party unblocked");
        assertEq(handler.byRequestReceiverMisses(), 0, "by-request block skipped a flagged receiver");
        assertEq(handler.byRequestReceiverLeaks(), 0, "by-request block touched an unflagged receiver");
    }

    // ── reachability ─────────────────────────────────────────────

    /// @notice Non-vacuity companion for the four operator-lever invariants.
    ///         Each of them is a "this never happened" assertion, which a
    ///         handler that never reaches the guarded path would satisfy for
    ///         free. This drives a short scripted campaign through the same
    ///         handler and proves every guarded path was entered: a release was
    ///         attempted under the pause, a release was attempted with a blocked
    ///         party, a two-id batch was released, the stuck-exit recovery leg
    ///         paid out, both by-request block variants ran, and both routes
    ///         resolved funds away. The guard counters are then still zero — the
    ///         invariants hold on a run that demonstrably reached them.
    function test_handler_reaches_operator_levers() public {
        // Four ERC20 exits and one native exit, all sharing originator/owner so
        // one caller can release a batch of them.
        handler.recordErc20(uint128(1e18), 0, 0, 0);
        handler.recordErc20(uint128(1e18), 0, 0, 0);
        handler.recordErc20(uint128(1e18), 0, 0, 0);
        handler.recordNative(uint128(1e18), 0, 0, 0);
        handler.recordErc20(uint128(1e18), 0, 0, 0);

        // Batch release of two ids in one call.
        handler.executeMany(0, 1);
        assertEq(handler.batchExecutions(), 1, "batch release never ran");
        assertEq(handler.batchExecutedIds(), 2, "batch release did not carry two ids");
        assertEq(handler.multiIdBatches(), 1, "no batch carried more than one id");
        assertGt(handler.executedPayouts(), 0, "no release was ever paid");

        // The second payout leg: stuck-exit recovery, which shares the pause
        // gate, carries a stricter block gate, and may pay an address the
        // request never named. It has to reach the same payout ledger.
        uint256 paidBefore = handler.paidTotal();
        handler.recoverStuck(4, 0);
        assertEq(handler.recoveredPayouts(), 1, "stuck-exit recovery never paid out");
        assertGt(handler.paidTotal(), paidBefore, "recovery payout never reached the ledger");

        // Recovery is also reachable through the request's receiver alone, not
        // only through the originator/owner pair every fixture above shares
        // (they all record with aSeed=bSeed=0, so orig==ownr for every one of
        // them). A purpose-built request with three distinct parties proves the
        // receiver path is exercised, not just allowed on paper.
        handler.recordErc20(uint128(1e18), 0, 0, 2); // orig=actors[0], owner=actors[2], receiver=actors[1]
        uint256 paidBeforeByReceiver = handler.paidTotal();
        handler.recoverStuck(5, 4); // liveIds[5]; caller = actors[4 % 3] = actors[1], the receiver
        assertEq(handler.recoveredPayouts(), 2, "receiver-only stuck-exit recovery never paid out");
        assertGt(handler.paidTotal(), paidBeforeByReceiver, "receiver recovery payout never reached the ledger");

        // Non-vacuity for the two single-authority recovery paths. The two
        // recoveries above all used a caller matching both originator AND
        // owner at once (or the receiver, proven separately), so they cannot
        // tell which of the originator check or the owner check is doing the
        // authorizing - removing either alone would still pass through the
        // surviving one. These two requests give originator and owner
        // distinct addresses and recover each with a caller that matches
        // only one of the two, so each call is authorized by exactly the
        // check it is meant to prove.
        handler.recordErc20(uint128(1e18), 0, 1, 0); // orig=actors[1], owner=actors[0], receiver=actors[2]
        uint256 paidBeforeByOriginator = handler.paidTotal();
        handler.recoverStuck(6, 4); // liveIds[6]; caller = actors[1], the originator - not the owner
        assertEq(handler.recoveredPayouts(), 3, "originator-only stuck-exit recovery never paid out");
        assertGt(
            handler.paidTotal(), paidBeforeByOriginator, "originator recovery payout never reached the ledger"
        );

        handler.recordErc20(uint128(1e18), 0, 2, 1); // orig=actors[2], owner=actors[1], receiver=actors[0]
        uint256 paidBeforeByOwner = handler.paidTotal();
        handler.recoverStuck(7, 4); // liveIds[7]; caller = actors[1], the owner - not the originator
        assertEq(handler.recoveredPayouts(), 4, "owner-only stuck-exit recovery never paid out");
        assertGt(handler.paidTotal(), paidBeforeByOwner, "owner recovery payout never reached the ledger");

        // A release attempted while the perimeter is paused.
        handler.pause(true);
        handler.execute(2, 0);
        assertGt(handler.executedWhilePausedAttempts(), 0, "no release was attempted under the pause");
        handler.pause(false);

        // A release attempted with a blocked party.
        handler.freeze(0);
        handler.execute(2, 0);
        assertGt(handler.executedWhileBlockedAttempts(), 0, "no release was attempted with a blocked party");
        handler.unfreeze(0);

        // Both by-request block variants, with and without the receiver. The
        // last call escalates a receiver the freeze above left merely Frozen, so
        // the receiver's "at least as hard-blocked as asked" floor is exercised
        // and not just its "blocked at all" state.
        handler.freezeByRequest(2, true);
        handler.blacklistByRequest(2, false);
        handler.blacklistByRequest(2, true);
        assertEq(handler.byRequestBlocks(), 3, "by-request blocking never ran");
        assertEq(handler.byRequestReceiverBlocks(), 2, "the receiver-catching variant never ran");

        // Recovery-away down both routes, now that a source party is blacklisted.
        handler.resolveByRoute(2);
        handler.resolveByRoute(3);
        assertEq(handler.routeResolutions(), 2, "route resolution never ran on both routes");

        // Re-registering a route is idempotent and stays reachable.
        handler.addRoute(0);
        handler.addRoute(1);
        assertEq(handler.routesRegistered(), 4, "route registration never ran");

        // …and every guard the four invariants pin still held throughout.
        invariant_blocked_party_never_paid();
        invariant_pause_stops_payouts();
        invariant_route_resolution_requires_blacklist();
        invariant_by_request_block_matches_parties();
        invariant_solvency_erc20();
        invariant_solvency_native();
        invariant_id_monotonic();
        invariant_no_double_terminal();
    }

    function _inActive(address party, uint256 id) internal view returns (bool) {
        // page through getActive (bounded live sets in the run)
        uint256 cursor = 0;
        for (uint256 guard = 0; guard < 50; ++guard) {
            (uint256[] memory ids, uint256 next) = queue.getActive(party, cursor, 100);
            for (uint256 j = 0; j < ids.length; ++j) {
                if (ids[j] == id) return true;
            }
            if (next == 0) break;
            cursor = next;
        }
        return false;
    }
}

test/invariant/ExitDelayQueueHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import {ExitDelayQueue} from "../../src/ExitDelayQueue.sol";
import {IExitDelayQueue} from "../../src/interfaces/IExitDelayQueue.sol";

contract InvMockERC20 is ERC20 {
    constructor() ERC20("Inv", "INV") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Force-sends native RBTC via selfdestruct — bypasses the queue's
///      `receive` gate, exactly the donation-grief vector the tolerates.
contract ForceSender {
    constructor(address payable target) payable {
        selfdestruct(target);
    }
}

/// @dev Stateful handler that drives the queue through its whole surface for the
///      forge invariant runner. It is itself an `_allowedSource` and the
///      `nativePusher`, so it can exercise every ingress variant. It tracks a
///      ghost sum of Queued amounts per token to check solvency and
///      records executed ids to check monotonicity / no-double-spend.
///      Bounded actor set keeps blocks meaningful.
contract ExitDelayQueueHandler is Test {
    ExitDelayQueue public queue;
    InvMockERC20 public token;
    address public wrbtc; // canonical WRBTC (native-backed mock in the test)

    // three fixed actors → freeze/execute interplay is meaningful
    address[3] public actors = [address(0xA1), address(0xA2), address(0xA3)];

    uint32 public constant MIN_DELAY = 1 hours;

    // ghost accounting
    uint256 public ghostQueuedErc20; // Σ Queued amounts, token
    uint256 public ghostQueuedNative; // Σ Queued amounts, native
    uint256 public totalRecorded; // # of record* calls that succeeded
    uint256 public totalTerminal; // # of terminal transitions

    // track live ids for targeted execute/resolve
    uint256[] public liveIds;

    /// @dev (creation-time, C3): the minimumDelaySeconds floor in effect at
    ///      each request's OWN createdAt. Recorded at the moment of a successful
    ///      record so the invariant can check `unlockAt − createdAt >= floor-at-its-
    ///      creation` — NOT the current live floor. A later setMinimumDelaySeconds
    ///      raise must apply only to NEW requests and never retroactively extend an
    ///      already-Queued exit; this ghost is what lets the invariant assert that.
    mapping(uint256 => uint32) public floorAtCreation;

    /// @dev Snapshot of a request exactly as `record*` left it: read straight
    ///      back off the queue in the same call that created it, before any
    ///      other action can run. Every field but `status` must read the same
    ///      value forever after — the invariant below checks the live request
    ///      against this snapshot for every id ever recorded.
    mapping(uint256 => IExitDelayQueue.ExitRequest) internal _recordedAt;

    /// @dev A public mapping of structs only auto-generates a tuple getter, so
    ///      this returns the whole snapshot the invariant needs to compare
    ///      field-by-field against the live request.
    function recordedAt(uint256 id) external view returns (IExitDelayQueue.ExitRequest memory) {
        return _recordedAt[id];
    }

    // ── provenance the ingress actions stamp on every request. The Leg-2
    //    recovery routes are registered from these exact values, so a route
    //    resolution is reachable from step one instead of being a dead action.
    bytes32 public constant ERC20_SURFACE = keccak256("S");
    bytes32 public constant NATIVE_SURFACE = keccak256("Z");
    address public constant ERC20_SUBPRODUCT = address(0xBEEF);
    address public constant NATIVE_ROUTE_DESTINATION = address(0x2EC0);
    bytes32 public constant BLOCK_REASON = keccak256("perimeter-incident");

    bytes32 public erc20RouteId;
    bytes32 public nativeRouteId;
    uint256 public routesRegistered;

    // ── payout ledger: what left the queue through a release, and the state
    //    the parties were in when it left.
    mapping(address => uint256) public paidTo; // sum released, per receiver
    uint256 public paidTotal;
    uint256 public executedPayouts; // requests released by execute/executeMany
    uint256 public recoveredPayouts; // requests paid out by recoverStuckExit
    uint256 public blockedPayouts; // released while a party was Frozen/Blacklisted
    uint256 public blockedPayoutValue;
    address public blockedPayoutParty; // first counterexample, for the failure message
    uint256 public pausedPayouts; // released while the perimeter pause was on

    // reachability counters — proof the guarded paths were actually driven
    uint256 public executedWhileBlockedAttempts;
    uint256 public executedWhilePausedAttempts;
    uint256 public batchExecutions; // successful executeExits calls
    uint256 public batchExecutedIds; // requests released through the batch path
    uint256 public multiIdBatches; // ...of which carried more than one id

    // ── Leg-2 route resolutions
    mapping(uint256 => bool) public resolvedByRoute;
    uint256[] internal routeResolvedIds;
    uint256 public routeResolutions;
    uint256 public routeResolutionsWithoutBlacklist;
    uint256 public unauthorizedRouteResolutionId; // first counterexample

    // ── by-request blocking
    uint256 public byRequestBlocks; // successful freeze/blacklistFromRequest calls
    uint256 public byRequestReceiverBlocks; // ...of which carried freezeReceiver
    uint256 public byRequestPartyMisses; // a source party left below the asked state
    uint256 public byRequestReceiverMisses; // a flagged receiver left unblocked
    uint256 public byRequestReceiverLeaks; // an unflagged receiver's state moved

    constructor(ExitDelayQueue q, InvMockERC20 t, address wrbtc_) {
        queue = q;
        token = t;
        wrbtc = wrbtc_;
        token.mint(address(this), type(uint128).max);
        vm.deal(address(this), type(uint128).max);
    }

    receive() external payable {}

    // ── ingress ──

    /// @dev Overflow-safe actor trio. The receiver index is
    ///      `(seed%3 + 1) % 3` — computed here off the caller's stack (keeping the
    ///      record* frames under the non-via-ir stack limit) and, crucially, on the
    ///      ALREADY-reduced `%3` value so a max seed can never 0x11-overflow the
    ///      way the prior `(seed+1)%3` did. `orig`/`ownr` use the raw `%3` seeds so
    ///      the freeze/execute interplay still spans the whole actor set.
    function _trio(uint256 aSeed, uint256 bSeed)
        internal
        view
        returns (address orig, address ownr, address recvA, address recvB)
    {
        orig = actors[aSeed % 3];
        ownr = actors[bSeed % 3];
        recvA = actors[(aSeed % 3 + 1) % 3];
        recvB = actors[(bSeed % 3 + 1) % 3];
    }

    function recordErc20(uint128 amount, uint32 extraDelay, uint256 aSeed, uint256 bSeed) external {
        amount = uint128(bound(amount, 1, 1e24));
        // Delay is bounded above the live floor so a floor RAISE (see setMinDelay)
        // never bricks ingress here; the request's floor-at-creation is captured
        // below regardless of the delay actually chosen.
        uint32 floor = queue.minimumDelaySeconds();
        uint32 d = floor + uint32(bound(extraDelay, 0, 10 days));
        (address orig, address ownr, address recv,) = _trio(aSeed, bSeed);
        token.approve(address(queue), amount);
        try queue.recordERC20Exit(
            address(token), amount, d, ERC20_SURFACE, ERC20_SUBPRODUCT, orig, ownr, recv, false
        ) returns (uint256 id) {
            liveIds.push(id);
            floorAtCreation[id] = floor;
            _recordedAt[id] = queue.getRequest(id);
            ghostQueuedErc20 += amount;
            totalRecorded++;
        } catch {}
    }

    function recordNative(uint128 amount, uint32 extraDelay, uint256 aSeed, uint256 bSeed) external {
        amount = uint128(bound(amount, 1, 1e21));
        uint32 floor = queue.minimumDelaySeconds();
        uint32 d = floor + uint32(bound(extraDelay, 0, 10 days));
        (address orig, address ownr,, address recv) = _trio(aSeed, bSeed);
        try queue.recordNativeExit{value: amount}(amount, d, NATIVE_SURFACE, address(0), orig, ownr, recv)
        returns (uint256 id) {
            liveIds.push(id);
            floorAtCreation[id] = floor;
            _recordedAt[id] = queue.getRequest(id);
            ghostQueuedNative += amount;
            totalRecorded++;
        } catch {}
    }

    // ── measured-delta ingress: push then record in one tx. Credit is
    //    exactly `amount` when the non-backing surplus delta >= amount, so a
    //    donation (see donate*) must NOT brick these and must NOT break solvency.

    function recordReceivedErc20(uint128 amount, uint32 extraDelay, uint256 aSeed, uint256 bSeed) external {
        amount = uint128(bound(amount, 1, 1e24));
        uint32 floor = queue.minimumDelaySeconds();
        uint32 d = floor + uint32(bound(extraDelay, 0, 10 days));
        (address orig, address ownr, address recv,) = _trio(aSeed, bSeed);
        token.transfer(address(queue), amount); // push in the same tx
        try queue.recordReceivedERC20Exit(
            address(token), amount, d, ERC20_SURFACE, ERC20_SUBPRODUCT, orig, ownr, recv
        ) returns (uint256 id) {
            liveIds.push(id);
            floorAtCreation[id] = floor;
            _recordedAt[id] = queue.getRequest(id);
            ghostQueuedErc20 += amount;
            totalRecorded++;
        } catch {}
    }

    function recordReceivedNative(uint128 amount, uint32 extraDelay, uint256 aSeed, uint256 bSeed) external {
        amount = uint128(bound(amount, 1, 1e21));
        uint32 floor = queue.minimumDelaySeconds();
        uint32 d = floor + uint32(bound(extraDelay, 0, 10 days));
        (address orig, address ownr,, address recv) = _trio(aSeed, bSeed);
        // The handler is the registered nativePusher, so this push clears receive().
        (bool ok,) = payable(address(queue)).call{value: amount}("");
        if (!ok) return;
        try queue.recordReceivedNativeExit(amount, d, NATIVE_SURFACE, address(0), orig, ownr, recv) returns (
            uint256 id
        ) {
            liveIds.push(id);
            floorAtCreation[id] = floor;
            _recordedAt[id] = queue.getRequest(id);
            ghostQueuedNative += amount;
            totalRecorded++;
        } catch {}
    }

    // ── donation / force-send: creates non-backing surplus. The measured-delta
    //    credit-exactly-amount rule must keep / intact and never let a
    //    donation get mis-credited into totalEscrowed (grief resistance).

    function donateErc20(uint128 amount) external {
        amount = uint128(bound(amount, 1, 1e18));
        token.transfer(address(queue), amount); // ghost NOT updated: pure surplus
    }

    function donateNative(uint128 amount) external {
        amount = uint128(bound(amount, 1, 1e18));
        // selfdestruct force-send bypasses the receive() gate entirely.
        new ForceSender{value: amount}(payable(address(queue)));
    }

    // ── execution ──

    function execute(uint256 idSeed, uint256 actorSeed) external {
        if (liveIds.length == 0) return;
        uint256 id = liveIds[idSeed % liveIds.length];
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (r.status != IExitDelayQueue.ExitStatus.Queued) return;
        // jump past unlock sometimes
        if (actorSeed % 2 == 0 && block.timestamp < r.unlockAt) {
            vm.warp(r.unlockAt);
        }
        // Snapshot the two release gates BEFORE the call: whether the perimeter
        // was paused, and whether any of the three parties was blocked. Neither
        // is changed by a release, so this is the state at execution time — the
        // state the payout ledger has to be judged against.
        bool paused = queue.securityPerimeterPaused();
        address blocked = _anyBlocked(r);
        if (paused) executedWhilePausedAttempts++;
        if (blocked != address(0)) executedWhileBlockedAttempts++;
        address caller = actors[actorSeed % 3];
        vm.prank(caller);
        try queue.executeExit(id) {
            _onPaid(r, paused, blocked);
        } catch {}
    }

    /// @dev Batch release. `executeExits` is atomic and every id in it is paid
    ///      by the same caller, so the second id joins only when the first id's
    ///      originator is a party to it too (originator, owner or receiver);
    ///      otherwise a one-element batch runs (still the batch entry point,
    ///      still the `EmptyIds` guard's other side). Ghost accounting is
    ///      applied once per request actually paid.
    function executeMany(uint256 seedA, uint256 seedB) external {
        if (liveIds.length == 0) return;
        uint256 idA = liveIds[seedA % liveIds.length];
        uint256 idB = liveIds[seedB % liveIds.length];
        IExitDelayQueue.ExitRequest memory a = queue.getRequest(idA);
        if (a.status != IExitDelayQueue.ExitStatus.Queued) return;
        IExitDelayQueue.ExitRequest memory b = queue.getRequest(idB);
        bool pair = idB != idA && b.status == IExitDelayQueue.ExitStatus.Queued
            && (b.originator == a.originator || b.owner == a.originator || b.receiver == a.originator);
        _warpPastUnlock(a.unlockAt, pair ? b.unlockAt : 0);
        uint256[] memory ids = new uint256[](pair ? 2 : 1);
        ids[0] = idA;
        if (pair) ids[1] = idB;
        _executeBatch(ids, a, b, pair);
    }

    /// @dev Split out of `executeMany` to keep both frames inside the stack limit.
    function _executeBatch(
        uint256[] memory ids,
        IExitDelayQueue.ExitRequest memory a,
        IExitDelayQueue.ExitRequest memory b,
        bool pair
    ) internal {
        bool paused = queue.securityPerimeterPaused();
        address blockedA = _anyBlocked(a);
        address blockedB = pair ? _anyBlocked(b) : address(0);
        if (paused) executedWhilePausedAttempts++;
        if (blockedA != address(0) || blockedB != address(0)) executedWhileBlockedAttempts++;
        vm.prank(a.originator);
        try queue.executeExits(ids) {
            batchExecutions++;
            batchExecutedIds += ids.length;
            if (ids.length > 1) multiIdBatches++;
            _onPaid(a, paused, blockedA);
            if (pair) _onPaid(b, paused, blockedB);
        } catch {}
    }

    function _warpPastUnlock(uint64 unlockA, uint64 unlockB) internal {
        uint64 unlockAt = unlockB > unlockA ? unlockB : unlockA;
        if (block.timestamp < unlockAt) vm.warp(unlockAt);
    }

    /// @dev The party that would have made this release illegal, or the zero
    ///      address when all three are clear. Mirrors the queue's own gate order.
    function _anyBlocked(IExitDelayQueue.ExitRequest memory r) internal view returns (address) {
        if (queue.blockStateOf(r.originator) != IExitDelayQueue.BlockState.None) return r.originator;
        if (queue.blockStateOf(r.owner) != IExitDelayQueue.BlockState.None) return r.owner;
        if (queue.blockStateOf(r.receiver) != IExitDelayQueue.BlockState.None) return r.receiver;
        return address(0);
    }

    /// @dev The party that would have made this recovery illegal. Recovery
    ///      carries a stricter gate than a plain release: `altReceiver` is a
    ///      fourth actor the queue also refuses to pay past.
    function _anyBlockedForRecovery(IExitDelayQueue.ExitRequest memory r, address alt)
        internal
        view
        returns (address)
    {
        address blocked = _anyBlocked(r);
        if (blocked != address(0)) return blocked;
        if (queue.blockStateOf(alt) != IExitDelayQueue.BlockState.None) return alt;
        return address(0);
    }

    /// @dev Balance of `who` in the asset the request escrows; address(0) is
    ///      native. Reading it either side of a payout is what names the actual
    ///      recipient without trusting which branch the queue took.
    function _balanceOf(address t, address who) internal view returns (uint256) {
        return t == address(0) ? who.balance : token.balanceOf(who);
    }

    /// @dev Ledger entry for a request a release actually paid out. Records where
    ///      the value went and, alongside it, the two conditions that were meant
    ///      to make the payout impossible.
    function _onPaid(IExitDelayQueue.ExitRequest memory r, bool paused, address blocked) internal {
        executedPayouts++;
        _onPaidTo(r, r.receiver, paused, blocked);
    }

    /// @dev Payout ledger keyed on the address the value actually reached, which
    ///      the recovery leg may choose at payout time.
    function _onPaidTo(IExitDelayQueue.ExitRequest memory r, address recipient, bool paused, address blocked)
        internal
    {
        paidTo[recipient] += r.amount;
        paidTotal += r.amount;
        if (paused) pausedPayouts++;
        if (blocked != address(0)) {
            blockedPayouts++;
            blockedPayoutValue += r.amount;
            if (blockedPayoutParty == address(0)) blockedPayoutParty = blocked;
        }
        _onTerminal(r);
    }

    // ── block model ──

    function freeze(uint256 actorSeed) external {
        address a = actors[actorSeed % 3];
        try queue.freeze(a) {} catch {}
    }

    function blacklist(uint256 actorSeed) external {
        address a = actors[actorSeed % 3];
        try queue.blacklist(a) {} catch {}
    }

    function unfreeze(uint256 actorSeed) external {
        address a = actors[actorSeed % 3];
        try queue.unfreeze(a) {} catch {}
    }

    function unblacklist(uint256 actorSeed) external {
        address a = actors[actorSeed % 3];
        try queue.unblacklist(a) {} catch {}
    }

    function pause(bool p) external {
        try queue.setSecurityPerimeterPaused(p) {} catch {}
    }

    /// @dev (C3): fuzz the per-request floor across a RANGE that spans both
    ///      below and (crucially) ABOVE the delays of already-Queued requests. A
    ///      raise here must NOT retroactively extend any live request's unlockAt —
    ///      the creation-time invariant checks each request against its own
    ///      floorAtCreation, never the live floor, so a raise while short requests
    ///      sit Queued must not trip invariant_status_and_index_consistency.
    function setMinDelay(uint32 newFloor) external {
        // Cap well above the max ingress delay (floor + 10 days) so raises that
        // exceed live requests' (unlockAt − createdAt) are reachable and exercised.
        newFloor = uint32(bound(newFloor, 0, 30 days));
        try queue.setMinimumDelaySeconds(newFloor) {} catch {}
    }

    // ── stuck-exit recovery — verify-by-attempting redirect leg ──

    /// @dev recoverStuckExit(id, altReceiver): callable by the request's originator,
    ///      its owner, or its recorded receiver, whether or not the owner has code —
    ///      never widened to anyone else the way delivery is. Attempts the STORED
    ///      receiver first and pays altReceiver only
    ///      on a genuine bounce (verify-by-attempting) — but ON SUCCESS (either
    ///      branch) it is a TERMINAL transition, so ghost accounting must decrement,
    ///      exactly like execute. On a block/lock/pause/terminal/guard it reverts and
    ///      is caught (no state change). altReceiver is one of the plain handler
    ///      actors (never 0/this/token/wrbtc), so the guard never trips here.
    ///
    ///      This is a SECOND payout leg, so a success goes through the same
    ///      payout ledger as a plain release: the pause and the four-actor block
    ///      gate are snapshotted before the call, and the recipient is read off
    ///      the balance the payout moved rather than assumed, because the leg
    ///      pays altReceiver when the stored receiver bounces. The invariant
    ///      properties: recovery never pays a blocked party, never pays under the
    ///      pause, and never breaks solvency or double-spends.
    function recoverStuck(uint256 idSeed, uint256 actorSeed) external {
        if (liveIds.length == 0) return;
        uint256 id = liveIds[idSeed % liveIds.length];
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (r.status != IExitDelayQueue.ExitStatus.Queued) return;
        if (actorSeed % 2 == 0 && block.timestamp < r.unlockAt) {
            vm.warp(r.unlockAt);
        }
        _recover(id, r, actors[actorSeed % 3], actors[(actorSeed / 3) % 3]);
    }

    /// @dev Split out of `recoverStuck` to keep both frames inside the stack
    ///      limit. Every read that could consume the prank is taken before it.
    function _recover(uint256 id, IExitDelayQueue.ExitRequest memory r, address caller, address alt)
        internal
    {
        bool paused = queue.securityPerimeterPaused();
        address blocked = _anyBlockedForRecovery(r, alt);
        uint256 balBefore = _balanceOf(r.token, r.receiver);
        vm.prank(caller);
        try queue.recoverStuckExit(id, alt) {
            recoveredPayouts++;
            _onPaidTo(r, _recipientOf(r, alt, balBefore), paused, blocked);
        } catch {}
    }

    /// @dev Whoever the payout actually credited: the stored receiver when its
    ///      balance moved by the request amount, otherwise the alternate.
    function _recipientOf(IExitDelayQueue.ExitRequest memory r, address alt, uint256 balBefore)
        internal
        view
        returns (address)
    {
        return _balanceOf(r.token, r.receiver) >= balBefore + r.amount ? r.receiver : alt;
    }

    // ── recovery ──

    function resolveByOwner(uint256 idSeed) external {
        if (liveIds.length == 0) return;
        uint256 id = liveIds[idSeed % liveIds.length];
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (r.status != IExitDelayQueue.ExitStatus.Queued) return;
        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        try queue.resolveByOwner(ids, address(0xD00D)) {
            _onTerminal(r);
        } catch {}
    }

    // ── blocking by request id ──

    /// @dev The emergency lever: name a request, block the parties behind it.
    ///      `freezeReceiver` decides whether the payout destination is caught
    ///      too. Both variants take the batch form, which is what an operator
    ///      calls. The handler is the queue owner and every party of a recorded
    ///      request is a non-zero actor, so a known id cannot revert here — the
    ///      call is made bare so that an unexpected revert fails the run.
    function freezeByRequest(uint256 idSeed, bool receiver) external {
        _blockByRequest(idSeed, receiver, false);
    }

    function blacklistByRequest(uint256 idSeed, bool receiver) external {
        _blockByRequest(idSeed, receiver, true);
    }

    function _blockByRequest(uint256 idSeed, bool receiver, bool confirmed) internal {
        if (liveIds.length == 0) return;
        uint256 id = liveIds[idSeed % liveIds.length];
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (r.status == IExitDelayQueue.ExitStatus.None) return;
        // The receiver's state before the call: with `freezeReceiver` false the
        // call must leave it exactly where it was.
        IExitDelayQueue.BlockState receiverBefore = queue.blockStateOf(r.receiver);
        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        if (confirmed) {
            queue.blacklistFromRequest(ids, receiver, BLOCK_REASON);
        } else {
            queue.freezeFromRequest(ids, receiver, BLOCK_REASON);
        }
        _recordByRequest(r, receiver, confirmed, receiverBefore);
    }

    /// @dev What the by-request lever promised, measured the moment it returned.
    ///      A later unfreeze may legitimately clear any of this, so the check has
    ///      to be taken here and carried in ghost state.
    function _recordByRequest(
        IExitDelayQueue.ExitRequest memory r,
        bool receiver,
        bool confirmed,
        IExitDelayQueue.BlockState receiverBefore
    ) internal {
        byRequestBlocks++;
        if (receiver) byRequestReceiverBlocks++;
        // Both source parties end at least as hard-blocked as asked. A freeze
        // over an already-blacklisted party holds the stronger state, which is
        // why this is a floor and not an equality.
        IExitDelayQueue.BlockState want =
            confirmed ? IExitDelayQueue.BlockState.Blacklisted : IExitDelayQueue.BlockState.Frozen;
        if (uint8(queue.blockStateOf(r.originator)) < uint8(want)) byRequestPartyMisses++;
        if (uint8(queue.blockStateOf(r.owner)) < uint8(want)) byRequestPartyMisses++;
        if (receiver) {
            // Same floor as the source parties, not merely "blocked at all": a
            // blacklist-by-request that only FROZE the receiver would otherwise
            // pass, and a freeze is clearable and does not authorize Leg-2.
            if (uint8(queue.blockStateOf(r.receiver)) < uint8(want)) byRequestReceiverMisses++;
        } else if (r.receiver != r.originator && r.receiver != r.owner) {
            // Unflagged and not a source party: the lever must not have touched it.
            if (queue.blockStateOf(r.receiver) != receiverBefore) byRequestReceiverLeaks++;
        }
    }

    // ── recovery routes (Leg-2) ──

    /// @notice Register the two routes that match this handler's own ingress
    ///         provenance. Called once by the invariant setUp after the handler
    ///         has accepted ownership; the queue calls below are made by the
    ///         handler itself, so they clear `onlyOwner` whoever calls this.
    function setUpRoutes() external {
        _registerErc20Route();
        _registerNativeRoute();
    }

    /// @dev A top-up route may only be registered on a surface the owner has
    ///      marked feasible, must carry a real token, and must pay the pool the
    ///      exit came from — hence `setTopUpFeasible` first and
    ///      `destination == subProduct`.
    function _registerErc20Route() internal {
        queue.setTopUpFeasible(ERC20_SURFACE, true);
        erc20RouteId = queue.setRecoveryRoute(
            IExitDelayQueue.RecoveryRoute({
                active: true,
                surfaceId: ERC20_SURFACE,
                subProduct: ERC20_SUBPRODUCT,
                token: address(token),
                destination: ERC20_SUBPRODUCT,
                topUpPool: true
            })
        );
        routesRegistered++;
    }

    /// @dev A native exit can never be a pool top-up, so this one is a plain
    ///      recovery-away route to a fixed destination.
    function _registerNativeRoute() internal {
        nativeRouteId = queue.setRecoveryRoute(
            IExitDelayQueue.RecoveryRoute({
                active: true,
                surfaceId: NATIVE_SURFACE,
                subProduct: address(0),
                token: address(0),
                destination: NATIVE_ROUTE_DESTINATION,
                topUpPool: false
            })
        );
        routesRegistered++;
    }

    /// @dev Re-registering a route is idempotent (the id is derived from the
    ///      route's own fields), so this action keeps both routes live across the
    ///      run and exercises the registration guards each time.
    function addRoute(uint256 tokenSeed) external {
        if (tokenSeed % 2 == 0) {
            _registerErc20Route();
        } else {
            _registerNativeRoute();
        }
    }

    /// @dev Leg-2 recovery-away. The blacklist state of the source parties is
    ///      read BEFORE the call and carried into ghost state exactly as observed
    ///      — the action never filters on it, so a resolution that went through
    ///      without one is recorded rather than skipped.
    function resolveByRoute(uint256 idSeed) external {
        if (liveIds.length == 0) return;
        uint256 id = _routeCandidate(idSeed);
        IExitDelayQueue.ExitRequest memory r = queue.getRequest(id);
        if (r.status != IExitDelayQueue.ExitStatus.Queued) return;
        bytes32 routeId = r.token == address(0) ? nativeRouteId : erc20RouteId;
        if (routeId == bytes32(0)) return;
        bool blacklisted = queue.blockStateOf(r.originator) == IExitDelayQueue.BlockState.Blacklisted
            || queue.blockStateOf(r.owner) == IExitDelayQueue.BlockState.Blacklisted;
        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        try queue.resolveToProtocol(ids, routeId) {
            resolvedByRoute[id] = true;
            routeResolvedIds.push(id);
            routeResolutions++;
            if (!blacklisted) {
                routeResolutionsWithoutBlacklist++;
                if (unauthorizedRouteResolutionId == 0) unauthorizedRouteResolutionId = id;
            }
            _onTerminal(r);
        } catch {}
    }

    /// @dev Prefer a Queued id whose Leg-2 authorization already holds so the
    ///      route path is reachable, and fall back to the plain seed pick — the
    ///      fallback is what would carry an unauthorized resolution through if
    ///      the queue ever stopped demanding a blacklist.
    function _routeCandidate(uint256 idSeed) internal view returns (uint256) {
        uint256 n = liveIds.length;
        // Reduce the seed BEFORE adding the scan offset: `(idSeed + i) % n` on a
        // raw seed overflows at the top of the uint256 range.
        uint256 base = idSeed % n;
        uint256 scan = n < 16 ? n : 16;
        for (uint256 i = 0; i < scan; ++i) {
            uint256 c = liveIds[(base + i) % n];
            IExitDelayQueue.ExitRequest memory r = queue.getRequest(c);
            if (r.status != IExitDelayQueue.ExitStatus.Queued) continue;
            if (
                queue.blockStateOf(r.originator) == IExitDelayQueue.BlockState.Blacklisted
                    || queue.blockStateOf(r.owner) == IExitDelayQueue.BlockState.Blacklisted
            ) return c;
        }
        return liveIds[base];
    }

    // ── sweep (surplus removal keeps equality-form solvency reachable) ──

    function sweep(bool native) external {
        try queue.sweepSurplus(native ? address(0) : address(token), address(0x5EE)) {} catch {}
    }

    function warp(uint32 dt) external {
        vm.warp(block.timestamp + bound(dt, 1, 5 days));
    }

    function _onTerminal(IExitDelayQueue.ExitRequest memory r) internal {
        totalTerminal++;
        if (r.token == address(0)) {
            ghostQueuedNative -= r.amount;
        } else {
            ghostQueuedErc20 -= r.amount;
        }
    }

    function liveIdCount() external view returns (uint256) {
        return liveIds.length;
    }

    function liveIdAt(uint256 i) external view returns (uint256) {
        return liveIds[i];
    }

    function routeResolvedIdCount() external view returns (uint256) {
        return routeResolvedIds.length;
    }

    function routeResolvedIdAt(uint256 i) external view returns (uint256) {
        return routeResolvedIds[i];
    }
}

