    // --- verify: by-request, both groups ---------------------------------

    /// @notice After a freeze that skipped the held group, verify must confirm
    ///         the clean request's receiver reached Frozen and the held
    ///         request's receiver was left alone - untouched by this batch.
    function test_verify_freeze_confirms_the_clean_group_and_leaves_the_held_group_alone() public {
        uint256 clean = _record(ORIG, OWNR, RCVR);
        uint256 held = _record(ORIG2, OWNR2, RCVR2);
        vm.prank(ADMIN);
        queue.freeze(ORIG2);

        vm.prank(ADMIN);
        queue.freezeFromRequest(_ids(clean), true, keccak256("drill"));

        script.dispatch("verify-freeze", _noAddrs(), _ids2(clean, held), "");

        assertEq(uint256(queue.blockStateOf(RCVR)), uint256(IExitDelayQueue.BlockState.Frozen));
        assertEq(uint256(queue.blockStateOf(RCVR2)), uint256(IExitDelayQueue.BlockState.None));
    }

    /// @notice A clean request's freeze call succeeds and blocks its receiver
    ///         alongside it - then, before the responder runs verify, the
    ///         Admin separately unfreezes the receiver alone (a real,
    ///         reachable, onlyAdminOrOwner action unrelated to this incident).
    ///         The receiver's recorded trigger is cleared by that call, so it
    ///         no longer names this batch; verify must not read the missing
    ///         trigger as "this was the held group, receiver correctly left
    ///         alone" and print a clean CONFIRMED for a receiver that used to
    ///         be blocked and no longer is.
    function test_verify_freeze_does_not_confirm_a_receiver_unfrozen_after_the_fact() public {
        uint256 clean = _record(ORIG, OWNR, RCVR);

        vm.prank(ADMIN);
        queue.freezeFromRequest(_ids(clean), true, keccak256("drill"));

        vm.prank(ADMIN);
        queue.unfreeze(RCVR);

        vm.expectRevert(
            bytes(
                string.concat(
                    "NOT CONFIRMED: ",
                    vm.toString(RCVR),
                    " - receiver's own freeze call set its block, but it now reads None - a later action must have cleared it; this cannot be confirmed as still blocked - the call did not take effect"
                )
            )
        );
        script.dispatch("verify-freeze", _noAddrs(), _ids(clean), "");
    }

    /// @notice The multisig reports success even when the call inside it
    ///         failed, so before the freeze executes, verify must refuse.
    function test_verify_freeze_refuses_before_the_call_executes() public {
        uint256 id = _record(ORIG, OWNR, RCVR);
        vm.expectRevert();
        script.dispatch("verify-freeze", _noAddrs(), _ids(id), "");
    }

    /// @notice Blacklist escalates the held group too, so its originator and
    ///         owner reach Blacklisted exactly like a clean request's - which
    ///         means a held id's own by-request call IS evidenced, same as a
    ///         clean id's. By-request verify can no longer tell "held,
    ///         receiver correctly untouched" apart from "clean, receiver
    ///         later cleared" from that evidence alone (see
    ///         test_verify_blacklist_does_not_confirm_a_receiver_unblacklisted_after_the_fact),
    ///         so it refuses a held id's receiver claim rather than guess.
    ///         The clean group still confirms by request; the held group's
    ///         parties - which never made a receiver claim in the first
    ///         place - are confirmed by address instead, unambiguously.
    function test_verify_blacklist_confirms_both_groups() public {
        uint256 clean = _record(ORIG, OWNR, RCVR);
        uint256 held = _record(ORIG2, OWNR2, RCVR2);
        vm.prank(ADMIN);
        queue.freeze(ORIG2);

        vm.prank(ADMIN);
        queue.blacklistFromRequest(_ids(clean), true, keccak256("drill"));
        vm.prank(ADMIN);
        queue.blacklistFromRequest(_ids(held), false, keccak256("drill"));

        script.dispatch("verify-blacklist", _noAddrs(), _ids(clean), "");
        script.dispatch("verify-blacklist", _addrs2(ORIG2, OWNR2), _noIds(), "");

        assertEq(uint256(queue.blockStateOf(RCVR)), uint256(IExitDelayQueue.BlockState.Blacklisted));
        assertEq(uint256(queue.blockStateOf(RCVR2)), uint256(IExitDelayQueue.BlockState.None));
        assertEq(uint256(queue.blockStateOf(ORIG2)), uint256(IExitDelayQueue.BlockState.Blacklisted));
        assertEq(uint256(queue.blockStateOf(OWNR2)), uint256(IExitDelayQueue.BlockState.Blacklisted));
    }

    /// @notice The identical shape to
    ///         test_verify_freeze_does_not_confirm_a_receiver_unfrozen_after_the_fact,
    ///         but on the blacklist path for the clean group specifically: a
    ///         clean request's blacklist call succeeds and blocks its
    ///         receiver alongside it, then, before the responder runs
    ///         verify, the Admin separately unblacklists the receiver alone.
    ///         Before this fix, `_receiverCheck`'s guard was scoped to
    ///         `target == Frozen` only, reasoning that blacklist's held group
    ///         already has a legitimate excluded-receiver shape - which is
    ///         true, but does not make a CLEAN id's excluded receiver safe to
    ///         wave through too: the old code fell through to the held-group
    ///         default (`rState < target`), which trivially passed, and
    ///         printed a false CONFIRMED for a receiver that used to be
    ///         blocked and no longer is.
    function test_verify_blacklist_does_not_confirm_a_receiver_unblacklisted_after_the_fact() public {
        uint256 clean = _record(ORIG, OWNR, RCVR);

        vm.prank(ADMIN);
        queue.blacklistFromRequest(_ids(clean), true, keccak256("drill"));

        vm.prank(ADMIN);
        queue.unblacklist(RCVR);

        vm.expectRevert(
            bytes(
                string.concat(
                    "NOT CONFIRMED: ",
                    vm.toString(RCVR),
                    " - receiver reads None with no trigger of its own, but this id's own evidence is recorded",
                    " - this cannot be told apart from a clean request whose receiver was blocked then cleared;",
                    " re-verify this id's originator/owner alone with BLOCK_ACTORS, which makes no claim about",
                    " the receiver - the call did not take effect"
                )
            )
        );
        script.dispatch("verify-blacklist", _noAddrs(), _ids(clean), "");
    }

    /// @notice Two clean requests routed to the same receiver - the shape a set
    ///         of malicious withdrawals sharing one payout address produces -
    ///         must both confirm. `_blockTrigger` keeps only the id that
    ///         processed the receiver last, so the earlier of the two cannot
    ///         be read as clean from its own id alone; verify must still
    ///         confirm both rather than mistake the earlier one for held.
    function test_verify_freeze_confirms_two_clean_requests_sharing_one_receiver() public {
        uint256 a = _record(ORIG, OWNR, RCVR);
        uint256 b = _record(ORIG2, OWNR2, RCVR);

        vm.prank(ADMIN);
        queue.freezeFromRequest(_ids2(a, b), true, keccak256("drill"));

        script.dispatch("verify-freeze", _noAddrs(), _ids2(a, b), "");

        assertEq(uint256(queue.blockStateOf(RCVR)), uint256(IExitDelayQueue.BlockState.Frozen));
    }

    /// @notice Same shape under blacklist: both clean requests sharing a
    ///         receiver must confirm, not only the one whose id happens to be
    ///         the last to have touched the shared receiver's trigger.
    function test_verify_blacklist_confirms_two_clean_requests_sharing_one_receiver() public {
        uint256 a = _record(ORIG, OWNR, RCVR);
        uint256 b = _record(ORIG2, OWNR2, RCVR);

