    /// @notice Blocking is by ADDRESS, not by request: freezing via ONE request id
    ///         holds every other queued withdrawal of the same parties, including
    ///         ones the operator never selected and ones queued later. This is the
    ///         property the operator surface relies on — a fraudulent actor cannot
    ///         be half-blocked, with some of their exits still executable.
    function test_block_by_request_holds_every_request_of_those_parties() public {
        uint256 first = _queueErc20(10 ether);
        uint256 second = _queueErc20(20 ether);
        // A third party who shares nothing with them must stay unaffected.
        address otherOrig = address(0x0BB1);
        address otherOwner = address(0x0BB2);
        uint256 stranger = _queueErc20With(5 ether, otherOrig, otherOwner, address(0x0BB3));

        // Freeze naming ONLY the first request.
        uint256[] memory ids = new uint256[](1);
        ids[0] = first;
        vm.prank(ADMIN);
        queue.freezeFromRequest(ids, false, keccak256("incident"));

        vm.warp(block.timestamp + DELAY);

        // The named request is held...
        vm.prank(OWNR);
        vm.expectRevert(
            abi.encodeWithSelector(
                IExitDelayQueue.ActorBlocked.selector, ORIG, IExitDelayQueue.BlockState.Frozen
            )
        );
        queue.executeExit(first);

        // ...and so is the one that was never named, because the PARTIES are blocked.
        vm.prank(OWNR);
        vm.expectRevert(
            abi.encodeWithSelector(
                IExitDelayQueue.ActorBlocked.selector, ORIG, IExitDelayQueue.BlockState.Frozen
            )
        );
        queue.executeExit(second);

        // A request queued AFTER the block, by the same parties, is held too.
        uint256 later = _queueErc20(1 ether);
        vm.warp(block.timestamp + DELAY);
        vm.prank(OWNR);
        vm.expectRevert(
            abi.encodeWithSelector(
                IExitDelayQueue.ActorBlocked.selector, ORIG, IExitDelayQueue.BlockState.Frozen
            )
        );
        queue.executeExit(later);

        // An unrelated party is untouched and still pays out.
        vm.prank(otherOwner);
        queue.executeExit(stranger);
        assertEq(
            uint256(queue.getRequest(stranger).status), uint256(IExitDelayQueue.ExitStatus.Executed)
        );
    }

    /// @notice The global pause is the locked door, not a freeze on the admin's own
    ///         hands: while every release is paused, blocking must still work, so the
    ///         incident can be worked out and the guilty parties held before the door
    ///         is opened again.
    function test_blocking_works_while_releases_are_paused() public {
        uint256 held = _queueErc20(10 ether);
        address otherOrig = address(0x0CC1);
        address otherOwner = address(0x0CC2);
        uint256 stranger = _queueErc20With(5 ether, otherOrig, otherOwner, address(0x0CC3));

        // Lock the door first, before anyone knows who is at fault.
        vm.prank(ADMIN);
        queue.setSecurityPerimeterPaused(true);

        // Blocking still lands while paused — by request and by address alike.
        uint256[] memory ids = new uint256[](1);
        ids[0] = held;
        vm.prank(ADMIN);
        queue.blacklistFromRequest(ids, false, keccak256("incident"));
        assertEq(uint256(queue.blockStateOf(ORIG)), uint256(IExitDelayQueue.BlockState.Blacklisted));

        address byHand = address(0x0DD1);
        vm.prank(ADMIN);
        queue.freeze(byHand);
        assertEq(uint256(queue.blockStateOf(byHand)), uint256(IExitDelayQueue.BlockState.Frozen));

        // Lift the pause: the door opens, but the holds placed under it stand.
        vm.warp(block.timestamp + DELAY);
        vm.prank(ADMIN);
        queue.setSecurityPerimeterPaused(false);

        vm.prank(OWNR);
        vm.expectRevert(
            abi.encodeWithSelector(
                IExitDelayQueue.ActorBlocked.selector, ORIG, IExitDelayQueue.BlockState.Blacklisted
            )
        );
        queue.executeExit(held);

        // And everyone else is paid, which is the point of lifting it.
        vm.prank(otherOwner);
        queue.executeExit(stranger);
        assertEq(
            uint256(queue.getRequest(stranger).status), uint256(IExitDelayQueue.ExitStatus.Executed)
        );
    }

